window.__D("text/maamarei-admur-haemtzai/c008",{"p":[[1900640129,"<b>ומשתחווה</b> ...ד גמור במלך אע\"פ שעומד בביטול גדול מאחר שמקבל ... השתחוו' דעבד זה בהיותו עומד לפני המלך מוכרח [ש] אינו בטל ב... וכמ\"ש en.במ\"א וד\"ל.\n<b>וכל</b> זה בא מבחי' שם ב\"ן שיורד בריבוי השתלשלות במיעוט אחר מיעוט וצמצומים רבי' מאד עד שבבחי' חיצוניו' ואחוריי' שלו כמו במל' דמל' דעשי' יוכל להסתעף מציאת הע' שרים דנוגה דב\"ן דעשי' שהן הכו\"מ דגלגלי' מעורבי' טו\"ר ממש, והוא מה שיש בהן ביטול לפרקי' בסיבוב והשתחווא' רוחני' וגשמית כנ\"ל, ויש בהן גם מבחי' הפירורד גמור להיות יש ודבר ממש כנ\"ל (הגם שהן רק כגרזן ביד החוצב ממש וכמו שא' מסדר הכוכבי' במשמרותיהם כרצונו דוקא כו'), אבל מבחי' שם מ\"ה גם דמל' דמל' דעשי' לא יומשך ממנו להמצא מציא' אור ושפע להיכלו' דנוג\"ה דק\"נ דעשי', הגם שירד אור שם מ\"ה גם בריבוי ההשתלשלו' דבי\"ע עד חיצוניו' ואחוריי' דמ\"ה דמל' דמל' דעשי', וע\"ז א' וכבודי לאחר לא אתן כו' הוא כבוד הוי' דמ\"ה דוקא אבל שם אלקי' בחי' ב\"ן יורד גם לשפע היכלו' דק\"נ כנ\"ל. וטעם הדברי' יובן עפ\"י הנ\"ל בביאור ענין ובחי' מ\"ה וב\"ן בשרש שרשם עד רום המעלות, דבחי' מ\"ה הוא בבחי' אי\"ן האלקי שלמעלה מן ההשג' ותפיס' כלל, שמזה יבא בחי' הביטול שהוא ההפשטה מן החומר ביטול הי\"ש לאי\"ן כו' מצד שרחוק ונפלא ממנו אור האלקי בבחי' קדוש ומובד\"ל כנ\"ל, וא\"כ הרי לא ירד אור האלקי אצלו להיות בבחי' יש ודבר בהשג' דבר מה בכלי הגבלה כו' אדרבה גבה ומרומם ביותר כמו שהוא בעצמות כו', וזהו בחי' הביטו\"ל לאין שנמצא בכל הנבראי' מריש כל דרגין עד סוף כל דרגין גם בהיכלו' דק\"נ שמתבטלי' לאין בגלגלי' שמשתחווי' כנ\"ל, והגם שירד בריבוי השתלשלו' עד שהביטול לאין בגלגלי' בא בהגשמה כסיבוב הגשמי, מ\"מ ה\"ז בבחי' אי\"ן דאלקו' בלי יגרע אורו כלל כמו שהוא בריש כל דרגין כשרפי' שאו' קדו\"ש כנ\"ל, ועד\"מ כאשר כל העם משתחוי' לפני המלך אע\"פ שהשרי' וגדולי הערך השתחווא' בביטול פנימי יותר ופחותי הערך השתחוואתם בחיצוניו' יותר, מ\"מ השתחווא' אחת לכולם שמתבטלי' מעצמותם מצד אור פני מלך שממשיך הביטול הזה על כל א' וא' לפי ערכו ולא ימצא שום פירוד גם בפחות שבפחותי' כמו שלא ימצא בגדול וקרוב למלך יותר מכולם הכל שוין בזה (וכמ\"כ בבחי' ביטול דבחי' מ\"ה בכנ\"י מגדול הדור עד הפחו' שבהם כמו מבחי' מ\"ה דמשה שא' ונחנו מ\"ה, הרי הי' בבחי' ביטול לאי\"ן בתכלית כי קרוב יותר מכולם כמ\"ש פא\"פ אדבר בו כו', ונמשך הביטו\"ל דמה זה בריבוי יריד' המדרגו' בכל ס\"ר נשמו' בכל א' לפי מדרגתו עד היותר קטן שבכולם כע\"ה ובע\"ת ששב על חטאו כו', הרי גם בבע\"ת שפחד אלקי' לנגד עיניו להיו' סור מרע ובע\"ה שהאלקי' ירא למרוד בפ\"מ ג\"כ הוא"],[1900640140,"מבחי' שם מ\"ה דמשה שבפנימי' יותר מכולם בלי גרעון אור כלל וכלל, שהרי הבע\"ת חזק באופן הביטול עצמו להיו' סור מרע מפחדו מאלקי' כמו בגדול הדור בביטול פנימי שלו, וכן ע\"ה ונשים וקטנים באמונתם הפשוטה חזקי' בביטול שלהם כו' וכמ\"ש במ\"א בענין הן ירא' ה' היא חכמ' בראש ובסוף דנעוץ תחלתן בסופן וסופן בתחלתן דירא' תתאה ירא למרוד בפ\"מ היא ירא' עילא' דביטול במציא' דמ\"ה דחכמה הפנימי' כו'), ולא עוד אלא כשירא' חטאו קודמ' לחכמתו חכמתו מתקיימ' ואם אין ירא' אין חכמ' כו', ומזה מובן עכ\"פ דבבחי' מ\"ה אין בריבוי en.ההשתלשלו' גרעון אור כלל וד\"ל.\n<b>וכל</b> זה מצד בחי' אי\"ן ומ\"ה דגם ברוב השתלשלות שלו במיעוט וצמצום לא יוגרע אורו משום דבר המסתיר עד שגם בנפש החוטא' שנטמא' בתכלית הטומא' תאיר אור הביטול דבחי' מ\"ה לעוררו בתשו' שלימה. וכמ\"כ יובן שיכול להיות אימה ופחד אלקי' גם בק\"נ ובהיכלו' הטומא' כו' וכמו בלעם שא' לא אוכל כו', וזהו יראו מה' כל הארץ וכן מי לא יראך מלך הגוים כו' יראה זו היא בבחי' הביטול דשם מ\"ה למעלה מן ההשג' והטעם דוקא שנמשך עד למטה מטה בלי גרעון אור שלא להיות בבחי' פירוד לעולם כו'. והגם שיש לכל בריא' חומר וצורה והחומר מד\"י גשמיי' או רוחניי' מחשיך ומסתיר על הצורה להיו' בבחי' יש וגסות היפך הביטול, מ\"מ אינו מחשיך כלל לבחי' אור דבחי' מ\"ה שמאיר בו להיותו למעלה מכלי השגתו בבחי' הגבהה והתנשאו' והפלא' מערכו ובתכלית ההפשטה מן הגשם שבו ע\"כ גם חומר גופו יתבטל מזה כו'. וראי' מן הגלגלי' שכלולי' מחומר וצורה כידוע והרי חומר הגלגל משתחוה בסיבובו כו' שאינו מחשיך כלל על בחי' הביטול דמ\"ה שבו מטעם הנ\"ל, וכן כל מלאך ושר שגם שיש לו חומר גופני מאמ\"ר גשמי או רוחני אינו מסתיר לו על בחי' הביטול שלו אדרבה גם הוא en.יבוטל (וכמו שמש בגבעון דום כשפסק הצורה לומר שירה כידוע).\n<b>אבל</b> הנה מבחי' שם ב\"ן שבכל הנבראי' כשיורד ומשתלשל למטה מטה יבא מזה בחי' הפירוד לפרקי' כנ\"ל. והטעם הוא לפי שבחי' ב\"ן הוא מה שאור אלקי"],[1900640150,"בא בהשגה בצמצום כלי הגבלת הנברא בבחי' יש ודבר מה כנ\"ל, אע\"פ שמתפעל במורגש וכאופני' שאו' ברו\"ך, מ\"מ ע\"י ריבוי הצמצום והסתר האור שנמשך דרך יריד' השפע בכל נברא לפי מה שהוא עד שבגלגלי' וכה\"ג בא בצמצום היותר אחרון ובבחי' יש כו', ע\"כ גם שבאור וצורה שלו מתפעל ואו' שירה כנ\"ל אבל בחי' חומר שלו הוא המחשיך אור ההתפעלו' שבהשג' זאת להיות בבחי' יש ודבר בבחי' פירוד וגסות כמו ע' שרי' ששרשם בכו\"מ יכולי' להיו' בבחי' פירוד ויש גמור לומר לי יאורי כו', והוא מטעם שקבלת אור שפעו בא בבחי' יש דב\"ן כו' (וכמ\"ש מלך אלקי' על גוי\"ם בחי' ב\"ן למשול עליהם בע\"כ משא\"כ יראו מה' בחי' מ\"ה כנ\"ל וד\"ל), וכמו באדם למטה אע\"פ שמתפעל בתפלה בהתבוננו' בהשג' אלקי' שנתפס בכלי מוחו ולבו ממה שממלא כ\"ע ומחי' את הכל כו' כל א' וא' לפום שיעורא דילי', מ\"מ חומר גופו הגס מיד ימשיכנו להבלי העוה\"ז ותאות גופני' להיו' בבחי' הפירוד לגמרי וחוזר ושב בתשו' לפרקי' וחוזר ונופל מפני שמעורב טו\"ר, וכל זה מבחי' ב\"ן שבנפשו שהוא בא מצד ההשג' לפי הכלי כו' אבל מבחי' מ\"ה שבנפשו לא יפול לעולם כי גם חומר גופו לא יחשיך ויבוטל גם הוא כנ\"ל וד\"ל (ונמצא שמחמת ההשג' דצורה לא יבוטל החומר וכשיבוטל החומר זהו מבחי' מ\"ה שלמעלה מן ההשג' כנ\"ל. ולפ\"ז הרי מובן דביטול החומר גבוה מביטול הצורה כמו ביטול דחומר הגלגל בסיבובו בא מבחי' מ\"ה שבו שגם החומר לא יחשיך אורו כנ\"ל, והוא גבוה מביטול הצורה שהוא נפש הגלגל עפ\"י ההשג' שלו שיש בזה נפילה לומר לי יאורי כו' וכה\"ג, וזהו מצד שקיבל אור השפע אלקי' בבחי' יש במורגש ההשג' כו' כנ\"ל. וכך הוא באדם דביטול החומר גבוה מביטול ההשג' שבצורה שבבינה שבנפשו כו', וראי' לזה ממה שבביטול החומר כמו למס\"נ על קדה\"ש וכן ירא' חטא גם בע\"ה כו' הכל שוין בזה ובביטול הצור' בהשג' כל א' לפי מדרגתו דוקא ויפול הנופל במעט רגע כנ\"ל).\n<b>ובכל</b> זה יובן ג\"כ ענין צדיקי' ובע\"ת שהן ג\"כ בבחי' מ\"ה וב\"ן שזהו בחי' רו\"ש כנ\"ל. דהנה צדיקי' היינו מה שאור הוי' דבחי' שם מ\"ה מאיר בנשמתם הטהורה כמ\"ש כי אתה נרי הוי' וכה\"ג, שאז יבא ויומשך בנשמתם בחי' הביטו\"ל לאי\"ן למעלה מן הטעם וההשג' רק ביטול בעצ\"ם מקרבתו ודביקותו כו' עד שלא יפרד כלל גם בהי[ותו ע] וסק בעניני גופו כנ\"ל שגם חומר גופו יבוטל כו', וכמו שיהי' ירא' ה' על פניכם לבלתי תחטאו ברע כלל, כי ירא' ה' הוא בחי' מ\"ה דחכמ' דכתיב ימות\"ו ולא בחכמ' כו' דאין רע יורד מלמעלה כלל כנ\"ל ולכך צדיקי' מובדלי' ומופשטי' ממילא מכל רע כו' (וכן בכללו' נש\"י דכתי' ועמך כולם צדיקי'"],[1900640158,"מצד שרש נשמתם למעלה והוא בחי' מ\"ה שבנפש האלקי' שמכחה יש בכ\"א וא' למס\"נ על קדה\"ש כנ\"ל), אבל בע\"ת שרשם מבחי' ב\"ן דוקא כי הרי נפל בנפילה בגסות וחומריות התאוה הרעה שבק\"נ בהיכלו' הטומא' ונטמאה נפשו שזה אינו בא כ\"א מצד בחי' הסתר אלקו' אצלו בתכלית עד שאין פחד אלקי' לנגד עיניו כלל ובשרירות לבו ילך כו', וזהו מפני שנכנס בו רוח שטות כבהמה ממש לפי שסר צלם אלקי' דאד\"ע ממנו ע\"כ נתגשם ברע כ\"כ, וזהו בחי' ב\"ן דנוגה שרובו רע כו' שנפל בשבירה מן בחי' מותרו' ואחוריי' דבחי' ב\"ן דקדוש' כנ\"ל והיינו מבחי' ההשג' בצמצום בבחי' יש שתופס בהתפעלו' במורגש לפי שעה לבד וכאשר יפנה לבו מיד יתגבר ע\"ז בחי' הרע שבחומר גופו הבהמי' ויפול הנופל כו' כנ\"ל כי אזלעו\"ז כו', ואמנם הנה כאשר נפש החוטאת תשוב בתשוב' הרי הרוח תשוב אל ה' כו' שמעומק רע יצא ומואס ברע ושב אל ה' בכל לבו ונפשו דורש ומבקש ה' כו', הנה זהו כדבר פלא ביותר דמאין בא לו זאת אחר שבא לכלל פירוד גמור לומר שלום יהי' לי בשרירות לבי אלך כו' יהופך להיפוך גמור שהוא בחי' הביטו\"ל באמת בבחי' רצוא ותשוקה לצאת מחומר גופו לגמרי ולידבק אחרי ה', אין זה מצד בחי' ההשג' וההכרה בד[עת] אלקי, שא\"כ מה זה שנפרד ונתרחק עד כה וכו' אלא מוכרח לומר שבחי' רצוא זה בא מבחי' כח מ\"ה שבנפשו האלקי' שמעוררו לבא לבחי' ביטול כל העצמו' הזה (כמו ראב\"ד שיצא' נשמתו בבכי' שהוא מצד בחי' עצמיו' שלמעלה מן הטעם ודעת לגמרי כו'). וא\"כ ממילא מובן מזה שבחי' מ\"ה זה למעלה הרבה מבחי' מ\"ה שבנשמו' הצדיקי', כי בחי' הרצוא זה בבע\"ת בא אחרי אשר הוטמא' הנפש כו' בבחי' פירוד גמור הוא חוזר ומתחרט ושב באמת אל ה' וכל חפצי תאותיו הרעי' משליך מנגד ומואס בהם לגמרי כו' בלתי לה' לבדו רצונו ותשוקתו ואין זר אתו כו', א\"כ הרי מבחי' הפירוד והיש נפרד בא לבחי' אי\"ן בהתכללות וביטו\"ל אמיתי לבחי' אי\"ן האלקי להדבק בה' אחד בלב אחד לאביו שבשמי', והרי בחי' רצו\"א זה עושה גם הי\"ש נפרד לאי\"ן שזה ודאי מצד יתרון אור וכח האי\"ן אלקי עד שיכול לעורר ולעשות ביטו\"ל לאי\"ן גם בי\"ש נפר\"ד שנטמא בטומא' ק\"נ להיו' עולה ובטל למעלה, א\"כ הרי גבוה הוא בחי' מ\"ה ורצוא זה הרבה יותר מבחי' מ\"ה ורצוא של נשמו' הצדיקי', הגם שהוא בעצם ש.. מובדלי' ממילא מכל רע כנ\"ל מאחר שבחי' מ\"ה דבע\"ת יאיר גם את החושך לאו\"ר ודאי יתרון אור וכח גדול נמצא בבחי' מ\"ה שבבע\"ת ממ\"ה שבצדיקי', ולזה גזרו או' דמקום שבע\"ת עומדי' צ\"ג א\"י לעמוד, וזהו לאחר בירור דב\"ן ע\"י מ\"ה"],[1900640165,"היותר עליון דוקא שצ\"ג א\"י לעמוד שם כלל (והוא מבחי' ס\"ג שלמעלה משם מ\"ה en.כמשי\"ת).\n<b>ו</b>[מעת] ה יש להבין מ\"ש דמלכא משיחא אתא לאתבא צדיקייא בתיובתא כו'. והנה תחלה יש להבין בתוס' ביאור בשרש הראשון דבחי' מ\"ה וב\"ן דצדיקי' ובע\"ת כנ\"ל, ואיך שיש יתרון מעלה בזה מה שאין בזה ולא ראי זה כו'. ויש להקדים תחלה הקדמה אחת הידוע בס' הקבלה בענין שם מ\"ה החדש שבמצחא כו' שהוא שרש שם מ\"ה דתיקון ושרש בחי' ב\"ן בהבלי' דפה כו'. דהנה אנו רואי' במהות הבל הדיבור שהוא מורכב מאמ\"ר גשמי ויוצא בבחי' פירוד גמור לאויר לחוץ כו', ועכ\"ז אנו רואי' שיש בחי' חיות פנימי ועצמי מעצמות הנפש ביותר ודוקא בהבל זה הגשמי שיוצא בבחי' חיצוניו' מאד, שהרי כל עיקר פנימי' נקוד' הלב וכל בחי' עצמו' שלו בא בהבל הדיבור כמו כאשר מדבר דברי אהבה וחשק שדברי' היוצאי' מקירת הלב נמשכו בהבל הדיבור ונכנסי' בלב השומע להתפעל באהבה או רחמי', לפי שיש בגוף הבל הדיבור היוצא מן הלב אור וחיות גדול מפנימי' הנפש שע\"כ רוח הבל הדיבור הגשמי פועל ועושה רושם גדול. וכן להיפך במרת נפש או כעס פנימי יומשך הכל בהבל הדיבור לעשו' רושם גדול, וכך הוא בתענוג העצמי שבפנימי' הנפש מתגלה בהבל הדיבור לזולתו למשוך אותו אליו כמו ראוה מדברת כו', וכמו\"כ בדברי חכמ' שמגלה כל העומק השכל ע\"י הבל חומר הדיבור יותר מבחי' הצורה שבו שהן צירופי' שעפ\"י אופן השכל שהרי יכנס הדבר חכמ' בלבו ע\"י שמיעה בדיבור מפי רבו יותר מע\"י הכתב גם שיכתוב באריכות יותר כו' .. מוכרח שיש בממשות ההבל מצד עצמו מבחי' פנימי' ועצמו' כחו' הנפש פנימי' וכל עצם מהותה אשר מתגלה ברצון ותענוג ושכל ומדו' ומחשבה שכל זה נמשך בהבל הדיבור דוקא וד\"ל.\n<b>והנה</b> יש עוד מקום שבו מתגלה כל עצם פנימי' הנפש והיינו במצח ופנים שתאיר פני אדם בהגיע לו בשורה טובה מאד או בעת שמחת לבו או כשמחדש שכל וחכמ' חדשה מאד וחכמת אדם תאיר פניו כידוע, שאז יצהיבו ויאירו פניו ביותר עד שהרואה בו ישמח ויקבל אור הארת פנים ג\"כ בנפשו, לפי שהארת פנים זה עושה רושם וחיזוק גדול בנפש זולתו להיות שע\"י השמחה או הבשורה טובה וכה\"ג ניתוסף אור גדול בנפש האדם, היינו מכל עיקר פנימיו'"],[1900640172,"ועצמו' שלה שבהעלם יצא לגילוי בפנים ומצחו דוקא, עד שממילא כל כחו' הנפש שלו באין בגילוי גדול מפנימיו' ועצמו' שלהם כמו הרצון והתענוג מתגלה בפנימי' ועצמו' שלהם, וגם השכל והמדו' יאירו בתוס' אור פנימי' ועצמו' הרבה יותר מכמו שהי' קודם, ויש כח גדול באור הפני' כשמאיר פניו ברוב עוז חיבה וחדוה להאיר בנפש זולתו ג\"כ כנ\"ל. וכמו באור פני מלך כאשר אנפהא דמלכא נהירין ברוב עוז וחדוה מאיזה שמחה יפעול בשרי' העומדי' לפניו הארת אורה ושמחה בפניהם לשמוח גם הם עמו ויתחזקו ביותר לכל דבר עבודה שבלב בתוס' כח ועוז בנפשם כמו בעת מלחמה שיחזקם להפקיר עצמם ע\"י הארת פני מלך כו'. ואמנם באמת א\"א לומר שכל עצם פנימי' הנפש כמו שהוא בא בעור הפני' שקרן עור פניו באור שהרי אין ערך לגשם עור ובשר ודם שבפנים לפנימי' רוחניו' הנפש כלל וכלל, אלא צריך לומר שהמתפעל מאור פני מלך אינו רואה בפניו מהות ועצם פנימי' שבנפש המלך רק ע\"י מעבר וכלי גשם הפנים שבפנים מלובש ומוסתר אור הפנימי וכרואה במראה לבד כו', אך אם הי' זה דרך הסתר לגמרי לא הי' מתפעל כלל כי לא יתפעל אדם מאור פני מלך הנראי' מרחוק כמו במראה וכה\"ג, רק כשרואה בפניו ומסתכל בו ממש שרואה בפנימי' החיות שבא בגילוי באור פניו וכמו יאר ה' פניו אליך שבהארת פני' זה נגלה הפנימי' דשם הוי' אליך דוקא כידוע, אבל מ\"מ בא מהו' ועצמו' הפנימי' בלבוש זה דפנים ממהו' למהות בבחי' דילוג גדול (אך שהפנימי' כמו שהוא ממש מגולה בפנים וראי' ממ\"ש יראה כל זכורך את פני ה' כו' שמזה דוקא יבא כל אור וגילוי אלקות ע\"י תו\"מ כל en.השנה וכענין הקבלת פני רבו כו').\n<b>ונמצא</b> מובן שיש מעלה בגילוי הפנימי' והעצמיו' בהבל הדיבור כנ\"ל הגם שהוא בחי' הבל חיצוני' יותר מן הפנים, הרי לא נמשך בו דרך דילוג ממהות למהו' אלא בממשות ההבל עצמו יש כח וחיו' העצמיו' כנ\"ל, ואע\"פ שהוא חיצוניו' דחיצוניו' וסוף כל מדרגו' האורו' שבנפש, אבל הארת העצמי' והפנימי' בפנים אינו נראה שם מהות ועצמו' הנפש כמו שהוא רק ע\"י הפסק הכלי גשמי של הפנים והמצח שהוא עצם ובשר ועור גשמי כנ\"ל, ויש יתרון מעלה בפנים ששם בא בחי' הגילוי דעצמיו' ופנימי' יותר אשר לא יוכל לבא בהבל הדיבור כלל, שהרי יתפעל אדם ויתחזק בנפשו מאור פני מלך אליו בפנים מאירו' ביותר הרבה יותר משידבר לו דברי אהבה וחשק רב ברוב עוז וחיבה כו'. לפי שבפני' מאיר כל הפנימי' והעצמו' יותר וע\"כ עיקר התגלו' השמחה או בשורה טובה הוא בפני' דוקא ולא במקום אחר, וכן חכמ' אדם תאיר פניו דוקא שלמעלה מהכיל"],[1900640178,"בכלי הדיבור כלל. ולכך נק' פני\"ם ע\"ש הפנימי' וגם ל' פונ\"ה כאשר קוראי' לו נפנה בפנים שזהו הוראה ששם מלובש כל עצמותו כמו פנה אלי וחנני כו' en.ממקומו יפן כו' כידוע וד\"ל.\n<b>והנה</b> יש עוד ענין א' בדמיון ההפרש כזה שאין בזה מה שיש בזה כו'. ויובן ענין זה יותר והיינו ממה שאנו רואי' בענין התלבשות כח הרצון והמחשבה היותר פנימי שבא בכלי העין לראות הדבר האהוב ושחושב בו בעמקות מחשבתו בעת ראותו להסתכל בו היטב כיונים שמסתכלין זה בזה כו', עד שיש כח בראי' והסתכלות זו להוליד כמו הסתכלו' דבת היענה כו' כידוע, ואין זה רק מפני שמתלבש פנימי' ועצמות הנפש במחשבה זו שבאה בהתלבשו' בהבטת כלי העין עד שכל הנפש נמשכת אחרי הדבר שרואה כו' (וכן בקבלת אור פני מלך הנ\"ל מה שמתפעל ביותר עד שיתחזק אור פנימי' נפשו כנ\"ל היינו דוקא ע\"י בחי' ההסתכלו' שמסתכל היטב באור פני מלך שאז נמשך פנימי' נפשו לקבל בחי' פנימי' שבפני מלך כו') וכירא' כל זכורך את פני ה' כו' כשם שבא לראות כו' וזהו לאסתכלא ביקרא דמלכא שזהו באור פני מלך חיים כו' וכידוע באסתכלותא דז\"א בפני' דא\"א מקבל שע\"ה נהורי' כו'). והנה גם בהבל הדיבור הגשמי באה כח המחשבה בהתלבשו' כנ\"ל שאם אינו חושב מה שידבר לא ידע מה ידבר ובכל דיבור ודיבור מלובש מן המחשבה ששייך לאותו הדיבור כו', וא\"כ הרי יש יתרון מעלה במחשבה שבהבטת עין הרבה יותר ממחשבה שבדיבור מצד זה. אך מצד אחר יש יתרון מעלה למחשבה שבדיבור על מחשבה שבהבטת העין, דהנה אנו רואי' שראי' שבעין באה בהגשמה מכח הראי' הרוחני' לפי חומר כלי העין שהוא גשמי מאד מלבשת לראי' הרוחניו' בלבוש גס שלה, וא\"כ ודאי גם המחשבה הרוחני' שבמוח שבא בראי' זאת מתלבשת בלבוש זה הגשמי עד שבאה בשינוי מהות מרוחניות לגשמיו'. ולפ\"ז כששחושב בדבר שרואה בו בכלי העין לא באה שפע המחשבה בדבר זה שרוא' כ\"א בדרך דילוג גדול ממהו' למהות כו' יותר מהתגשמו' הדבר שחושב במחשבתו בלא ראי' העין שעכ\"פ מציירו במחשבתו"],[1900640184,"במוח רק שבא דרך ציור ודמיון אבל בראי' העין באה המחשב' בדילוג כו'), משא\"כ המחשבה שבדיבור הנה הגם שבאה ג\"כ בהעלם מהותה העצמי בדיבור כי לא נראה מהו' מחשבה בדיבור רק אורה ושפעה לבד כנ\"ל, מ\"מ יש במהו' הבל הדיבור מהתלבשו' המחשבה ממש עד שלא יוכל לדבר מה שאינו חושב ואם ידבר בלא דעת כלל ידבר כמבולבל במחשבתו שמבולבל בדיבור והכל א' ממש, אבל המחשבה שחושב בראי' זו שרואה בעין אע\"פ שאינו רואה מה שחושב ומדמה הרי לפעמי' יכול לראות בעין ויחשוב מחשבה אחרת עד שלא יכיר הדבר שראה כלל מפני שהי' בלא מחשבה עיוני' רק בהעברה בעלמא שאינו נק' טביעת עין, ולפ\"ז יש מעלה במחשבה שבדיבור על מחשבה שבעין במה שיש מעצם כח ומהו' המחשבה בגילוי בדיבור ממש אבל אין זה מפנימי' ועצמו' דמחשב' כ\"כ, משא\"כ מחשב' שבעין שכל פנימי' שלה שם הוא כנ\"ל וזהו מעלה במחשבה שבעין על מחשב' שבדיבור כו', והחסרון במחשבה שבעין שכלי העין מפסיק בלבוש ראי' גשמי' כנ\"ל משא\"כ בדיבור שמתגלה בו ממש אע\"פ שמהו' המחשב' בו בהעלם כנ\"ל ואע\"פ שהוא חיצוני יותר, והחסרון במחשבה שבדיבור הוא מצד שהמחשב' בהעלם בו לא נרא' רק הדיבור שהוא הבל חיצוני אבל בעין בא ראי' המחשבה ממש בראי' העין רק שהעין מפסיקו בלבוש גס בדילוג יותר מלבוש הדיבור אל המחשבה כו', ונמצא שיש מעלה בזה מה שאין בזה וחסרון בזה מה שאין בזה כו' ועולה המכוון מכל ענין זה עם ענין הנ\"ל בהפרש שבין גילוי הפנימי' בפנים לגילויו בדיבור, דבפנים מתגלה מבחי' הפנימי' יותר אך כלי הפני' מפסיק להיותו בבחי' דילוג כו' וכן הוא הראי' ומחשב' שבעין כנ\"ל ומחשבה en.שבדיבור היינו ע\"ד הנ\"ל בגילוי פנימי' הנפש בהבל הדיבור והכל א' וד\"ל.\n<b>ומעתה</b> יובן הדוגמא מכל זה בהפרש שבין בחי' הארת שם מ\"ה שבמצחא כו' ובין בחי' שם ב\"ן ששרשו בהבל הפה כו', דהנה בחי' שם מ\"ה החדש הרי הוא באור פני מלך חיים בבחי' הפנימי' והעצמות כמו שהוא ממש כנ\"ל בענין יאר ה' פני\"ו אליך שבפנים מתגלה כל בחי' הפנימי' ממש, אך כלי הפנים מפסיק שהוא בא כמו דילוג ממהו' למהות כמחשבה שבכלי העין כנ\"ל, ומזה בא ענין ההסתעפו' דבחי' מ\"ה בנבראי' ג\"כ בבחי' מעבר ודילוג המהות, שהרי באמת אם הי' בחי' ביטול דמ\"ה הנ\"ל בנבראי' בלי שינוי המהו' בהארת מעבר בעלמא הרי הי' בחי' ביטול זה תמידי ועצמי בלי הפסק כלל וכלל, לפי שהי' הביטול הזה נכנס ויורד לתוך תוכם בכל חלקי איבריהם מראש לרגל בבחי' עצמיו' ממש כמו כל עצמותי תאמרנה מי כמוך כו', וכמו שיהי' לע\"ל שיהי' בחי' פחד אלקי' על כל הברואי' בביטול תמידי בלי שינוי והפסק כלל כו' (וכפחד יצחק שהי' תמידי"],[1900640190,"להיותו מקרוב מאד בבחי' שוב כאופני' שאו' ברוך כנ\"ל, כך יהי' הביטול דבחי' רצוא שהוא בחי' מ\"ה שלמעלה מן ההשגה ממש כמו התפעלו' המורגש בכל גופו שבבחי' שו\"ב הנ\"ל, וכענין וארכבות\"י דא לדא נקשן בתו\"ך תוכ\"ו וכן וגילו ברעדה במקום גילה שם תהא רעדה כו' כמ\"ש במ\"א), אך עתה לא נמצא השפע דבחי' מ\"ה הנ\"ל בנבראי' רק דרך מעבר לבד בכל א' לפי ערכו המצומצם נמשך אליו הארה בעלמא מצומצמת מאד מבחי' אי\"ן האלקי ב[ח] י' מ\"ה הנ\"ל ולפי שעה לבד שהרי מיד חוזר להיו[ת] בבחי' שו\"ב כמו בעמדם תרפינה כנפיהם, וגם השרפי' או' קדו\"ש שעה א' לבד וחוזרי' להיו' בבחי' יש ודבר מה במציאו' כלי כו', והיינו לפי שלא נכנס בחי' אי\"ן ומ\"ה זה בכל גופו מטעם שאינו נמשך בשרשו דשם מ\"ה רק בבחי' מעבר והוא בדילוג גדול שמאיר בדרך מעביר במצחו ופנים כנ\"ל, וע\"כ גם הנברא אינו מתפעל בתכלי' הביטול על בוריו כו' כ\"א בדרך מעבר, אבל זהו המעלה שבו שהוא אור הפנימי' והעצמו' כמו הבטת אור הראי' במחשבה עמוקה ועצמי' כנ\"ל. אבל שרש בחי' ב\"ן הוא מהבל הפה דא\"ק כו' שזהו כמו ענין המחשבה שבהבל הדיבור הנ\"ל דאע\"פ שהוא חיצוני מאד אבל מהו' המחשב' יותר באה בהבל הדיבור אע\"פ שהוא בהעלם ולא בדרך דילוג כ\"כ, ע\"כ בא ההמשכה דבחי' ב\"ן למטה בהשג' הנבראי' בקירוב גדול שיורד ונכנ[ס] בתוך תוכו בהתפעלו' מורגש במוח ולב עד שיהי' לו אור וחיו' ממש כמ\"ש קרבת אלקי' לי טוב, ל\"י טו\"ב ממש כנרא' בחוש לכל מי שטועם טוב טעם ודעת השג' אלקי' במוחו ולבו שיורד ומתקרב הדבר המושג ונדבק במוחו ולבו וכל איבריו כו' להיותו בשרשו בלא דילוג כ\"כ כנ\"ל. אך החסרון שלו שיורד ונמשך גם להיכלו' הק\"נ כו' להרגיש גם עצמו ליש ודבר גס עד שיכול לומר לי יאורי כו' כנ\"ל (שאין זה בבחי' מ\"ה כנ\"ל), זהו .. צד שהוא בבחי' הבל הדיבור שהוא חיצוני ביותר וגם המחשבה שבאה בו בא בתכלית צמצום ומיעוט האור כו' (אע\"פ שיש בה מהתלבשו' מהו' המחשבה ממש כנ\"ל), ולא בא כל בחי' הפנימי' ועצמו' שלה בדיבור כמו מחשב' שבעין ובגילוי אור הפנים דחכמ' אדם או מבשורה טובה וכה\"ג שכל העצמי' מתגלה רק שכלי הפנים והעין מפסיק המהות העצמי ובזה יש en.en.יתרון מעלה למחשב' שבדיבור כנ\"ל, וזהו שיש בזה מה שאין בזה כו' וד\"ל.\n<b>ונמצא</b> מובן מכל זה בשרש בחי' מ\"ה וב\"ן שיש מעלה יתירה לבחי' ב\"ן בשרשו במה שבא ומאיר מן מהות העצמו' יותר ולא דרך מעבר לבד וע\"כ מובן"],[1900640196,"מזה דלאחר שיהי' בירור ותיקון לחסרון דב\"ן שהוא מה שיורד ומתגשם בגסות ופירוד גמור כנ\"ל אז יהי' גבוה מבחי' מ\"ה מצד זה, וזהו ענין א\"ח עט\"ב דשם ב\"ן לאחר הבירור עולה בבחי' ס\"ג שלמעלה משם מ\"ה כידוע. וביאור הדברי' היינו ענין התשובה על החטא דוקא שהרע עצמו שנתגשם ביותר ויצא לכלל פירוד אחר פירוד שהוא כירידת צמצום דב\"ן להיכלו' דק\"נ כנ\"ל ע\"י התשובה מעומק הלב ברצוא ותשוקה כמו בכי' דראב\"ד עד שיצא' נשמתו בבכי' וכה\"ג, הרי עי\"ז הוברר בחי' הגסו' והפירוד שנסתעף מבחי' ב\"ן ועולה למעלה בשרשו ממש שהוא בא בבחי' גילוי אור מן מהו' ועצמו' יותר מבחי' התפעלו' הביטול דאי\"ן ומ\"ה האלקי שבצדיקי' שאינו בא ונמשך בשרשו במצחא כו' רק דרך מעבר לבד כנ\"ל. וזהו הטעם דבע\"ת גדולי' מצ\"ג וכמ\"ש בזוהר דבע\"ת משכי לי' לקודב\"ה בחילא יתיר כנ\"ל שזהו ענין בירור דב\"ן שעולה למעלה משם מ\"ה מטעם זה ביתרון מעלת בחי' ב\"ן על מ\"ה בשרשו הראשון בהבל הפה כו' כנ\"ל וד\"ל.\n<b>אך</b> הנה מבואר למעלה ג\"כ שיש יתרון מעלה לבחי' מ\"ה בשרשו הראשון במצח ופני' שמתגלה שם מבחי' הפנימי' והעצמו' ממש, ע\"כ מובן שאם הי' נמשך שם מ\"ה לא בדרך מעבר בלבד אלא בירידת עצם המהות בלי לבוש והסתר דכלי הפנים והמצח כו' הי' אז גילוי אור שם מ\"ה זה בנבראי' בתכלית הביטול דאי\"ן האלקי העצמי על בוריו ליכנס בתוך תוכם בתמידות ולא הי' נפסק ונסתר מהם אפי' רגע, וזהו מצד הארת העצמות ממש שלמעלה מבחי' ב\"ן בשרשו בהבל הפה כו' שאינו בא מבחי' הפנימי' והעצמיו' כ\"כ כנ\"ל (וזהו יחיינו מיומי' בהארת שם מ\"ה בהארת פנים לבד, ביום הג' יקימנו ונחיה לפני\"ו ממש בביטול עצמי דמ\"ה בתמידות בלי יצטרך להארת פנים דחכמ' כלל שהוא ביתרון מעלה מדורו של משה שא' פב\"פ דיבר ה' כו', ואע\"פ שא' ואתם הדבקי' בה' חיים כולכם כו' היינו כמו יחיינו מיומי' דבחי' מ\"ה העליון שאינו תמידי, וכמו בחי' ראי' דג' רגלי' דכתי' יראה כל זכורך את פני ה' שאינו אלא בשעה זו כו' ומיד שבים לבחי' יש ודבר, וכן תלמיד שמקבל פני רבו אין בו הביטול שמחמת הארת פני רבו רק דרך מעבר לפי שעה זו ולא שנכנס תוך תוכו להיו' תמיד כן, וכך הוא ענין י\"ג מדה\"ר ביו\"כ שנמשכי' מאור פני מלך חיים כו' וכה\"ג, אבל ונחיה לפניו הוא תמידי' כי"],[1900640201,"אינו בא דרך מעבר כו' וכמו והי' ירא' ה' על פניכם לבלתי תחטאו לעולם כו' מצד עוצם גילוי הפנימי' ועצמו' וכמ\"ש ואמר הנה אלקינו זה כו' וכן כתי' כימי צאתך מא\"מ אראנו נפלאו\"ת כו' סדכ\"ס עצמו כו' וד\"ל).\n<b>אך</b> האיך אפשר שיהי' בחי' מ\"ה העליון בא בלא כלי הפנים כו', הענין הוא שלא יהי' המשכת מ\"ה זה מלמעלה למטה בבחי' אי\"ן הרוחני (דבחי' מקיף שמאיר בהארת פנים וכה\"ג) אלא יהי' המשכתו בא למטה בבחי' יש ודבר מה דוקא שהוא ענין גילוי האי\"ן ומ\"ה האלקי בבחי' י\"ש למטה כמו שהוא בבחי' אי\"ן למעלה ממש בשוה, וזהו ענין התשובה של הצדיקי' דוקא כמ\"ש במשיח דאתא לאתבא צדיקייא בתיובתא, צדיקייא דוקא אך אין התשובה שלהם כתשובה של החוטא כי הרי תשובה דרשעי' שנהפך מרע לטוב נק' ביטול הישו' וגסו' לאי\"ן הרי הוא בחי' בירור דב\"ן כנ\"ל ואע\"פ שהוא למעלה מבחי' מ\"ה דצדיקי' כנ\"ל, היינו מבחי' מ\"ה שבא דרך מעבר לבד אבל בחי' מ\"ה זה שנמשך כמו שהוא ובא בבחי' יש ודבר דוקא הוא למעלה מתשוב' דבירור דב\"ן הנ\"ל.\n<b>וביאור</b> הדבר יובן כמו בדוגמא דלע\"ל דכתי' וראו כל בשר כו' הרי גם החומר דכל בשר יבא בו בחי' הביטול דמ\"ה שבנשמו' ומלאכי' שאו' קדו\"ש בהעדר ההשג' כנ\"ל, לפי שיתפס בחי' מ\"ה העליון בכלי הגוף דכל בשר שזהו בחי' גילוי המשכת האי\"ן ומ\"ה האלקי בבחי' יש ודבר דחומר כלי הגופי' שיהי' בהם ג\"כ בחי' הביטול העליון כמו בנשמו' ממש בשוה. וזהו מפני שיהי' המשכת מ\"ה העליון שלא דרך מעבר לבד כמו עכשיו שאז אינן יכולי' להכילו רק הנשמו' כראי' דירא' כל זכורך וכשרפי' כו', אבל בגילויו כמו שהוא שאז גם הגופי' החומריי' כמו שהן בבחי' יש ודבר יהיו בבבחי' הביטול תמיד\"י דאי\"ן והיינו מה שלא יופסק הביטול כלל וא\"כ ה\"ז בחי' המשכת דמ\"ה ביש דגופי' כמו שהוא למעלה בבחי' אי\"ן, וזהו ענין התשובה של הצדיקי' דוקא, דצדיקי' עיקר שרשם בבחי' מ\"ה העליון אבל כאשר יהיו בבחי' בע\"ת היינו שיומשך בחי' מ\"ה העליון כנ\"ל, שבנשמתם גם בגופי' חומריי' שלהם לעשות מי\"ש אי\"ן בדרך ירידה והמשכה מלמעלה למטה לפי שנכנס הביטול דמ\"ה העליון גם בכל כלי גופם בתוך תוכם ממש, וזהו שא' דאתא לאתבא צדיקייא דוקא בתשובה, ותשובה זו ע\"י שם מ\"ה היא באה דוקא מלמעלה למטה ולהיותו בא מבחי' הפנימי' ועצמו' כמו שהוא ע\"כ ודאי הוא למעלה מתשובת החוטאי', גם שזהו בירור הי\"ש לאי\"ן אבל שרשו רק מבחי' ב\"ן העליון כנ\"ל וד\"ל."],[1900640205,"<b>אך</b> הנה מבואר למעלה דבחי' ההתעוררו' של התשובה בחוטא עד שמהפך לבחי' הגסו' שבו לאי\"ן וביטול הוא גבוה מבחי' מ\"ה שבצדיקי' בעצם כו' מאחר שגדול כחו כ\"כ להפוך י\"ש לאי\"ן כו', ולפ\"ז בחי' הרצוא והתשוקה דתשובת החוטא (כמו יצא' נשמתו בבכי' כנ\"ל) בא ג\"כ מבחי' מ\"ה היותר עליון שלמעלה מבחי' מ\"ה דצדיקי' שמקבלי' מהארת פנים העליוני' כו' (רק שגופה של התשוב' מה שנהפך מרע לטוב נק' בירור דבחי' ב\"ן שעולה לבחי' ס\"ג כנ\"ל), וא\"כ נמצא מובן דתשובה דצדיקי' עם תשובת הרשעי' שניהם בשרש א' והוא בבחי' מ\"ה העצמי כמו שהוא שלא דרך מעבר לבד כנ\"ל, רק שבתשוב' דצדיקי' נמשך ויורד מלמעלה למטה בתוך תוך כלי גופם להפוך יש החומרי לאי\"ן בתמידו' ובבע\"ת הוא בא בדרך עלי' מלמטה למעלה והוא כמו ענין התעוררו' התשובה שצועק מקירת לבו ברצוא עד שעושה מי\"ש אין כו' וד\"ל. ובאמת בצדיקי' הרי בחי' מ\"ה העליון כמו שהוא הרי בא להיות הוא עצמו בחי' יש ודבר בגופי' שלהם היינו בלא ביטול הי\"ש לאי\"ן כלל אלא כמו שהן ממש בבחי' יש ודבר אין זה בבחי' פירוד כלל וכלל רק בחי' מ\"ה ואי\"ן וכמו יוסף שהי' טרוד בכתבי' חושבני' והי' מרכבה באותה שעה דוקא וכמ\"ש במ\"א, וכמו ונחי\"ה לפני\"ו הנ\"ל שנחי' בבחי' י\"ש ובו עצמו הוא בא התלבשו' דמ\"ה העצמו' וה\"ז כמו במשיח דמורח ודאין כמ\"ש במ\"א, en.וא\"כ זהו בחי' המשכה דמ\"ה העצמו' מאי\"ן לי\"ש ולא מי\"ש לאי\"ן כבע\"ת וד\"ל.\n<b>אך</b> עדיין יש להבין במהות התשובה של הצדיקי' ולמה ע\"י משיח דוקא כו'. דהנה מהות התשובה באה בכל דבר לפי מדרגתו ומקומו הוא ששב בתשובה לתקן הפגם שהוא לפי מדרגתו כידוע שיש בחי' נר\"נ ובודאי יוכל להיות פגם בנר\"נ והתשובה הוא התיקון לתקן הפגם, ובודאי אינו דומה פגם דבחי' נפש לפגם דבחי' רוח ופגם דרוח אינו דומה לפגם דנשמה כו', כי נפש החוטאת בפ\"מ צריכה תיקון לפי הפגם שבמעשה ופגם דבחי' רוח הוא במדות והוא דק ובפנימי' יותר והתשובה בפנימי' יותר ופגם דנשמה במוחי' דחו\"ב כו' הוא בפנימי' יותר ועד\"ז מתחלק ענין התשובה בכללו' נ\"י מבחי' רגל עד הראש שהן ראשי אלפי כו' וכל en.הגדול יותר פגמו יותר בפנימי' וצריך לתשובה עילא' יותר כו' וד\"ל.\n<b>ועד\"ז</b> יובן ענין התשובה בצדיקי' ג\"כ שהוא לפי ערכם דוקא דהיינו שצריכי' לבחי' תשובה עילא' ופנימי' יותר ולא מצד עצם הפגם אע\"פ שלא פגמו כלום גם בפנימיו' ודקו' רק מפני ערכם ומעלתם בעבודת הקדש היא הנותנת"],[1900640209,"שיחשבו כחוטאי' ממש, ויותר מן הנפש החוטאת בפ\"מ וכמו וסביביו נשערה מאד שמדקדק עליהם כחוט השערה ממש וכה\"ג, לפי שכל הגבוה יותר מחבירו יותר הוא חוטא לפי ערך מעלתו הגם שהחטא הוא בדקות מאד כחוט השערה יותר יחשב לחטא מן החוטא שחטא פחות הערך בדבר עבירה גדולה כו'. ויובן זה עד\"מ הידוע בהפרש שבין אדם לבהמה שאדם הוא בעל שכל ונבדל מעלתו בערך מן הבהמ' וע\"כ כאשר הבהמ' מטנפת בהיכל מלך וצריכי' לנקו' ההיכל אין זה פלא כלל, שדרך הבהמה בכך, אבל האדם שמטנף היכל המלך יחוייב מיתה כי יבער כאש חמת המלך על איש שיעשה דבר מכוער כזה ויצוה להשליכו חוץ ולהענישו ביותר כו'. וכמ\"כ הוא ההפרש בין העבדי' לשרים שכאשר יחטא העבד פחו' הערך עונשו קטן, אבל השר הגדול גם שיחטא בדקות ענין שלא הי' חטא כלל בעבד יחשב לו לחטא גדול עד שיענש עונש גדול כו' שלפי ערך מעלתו כן יגדל עונשו גם בחטא קל ביותר כידוע. וכך הוא למעלה בענין ההפרש שבין חטא פחות הערך לחטא הנשמו' הגבוהות וכידוע שיש ב' מדרגו' בנשמו' בחי' אדם ובחי' בהמה וכמ\"ש וזרעתי את ב\"י זרע אדם וזרע בהמה, כי אור הזרוע לצדיק עליון יש בחי' נשמו' גבוהו' שנק' זרע אד\"ם בגדלות הדעת שבצלם אד\"ם העליון ויש בחי' זרע בהמ' שלמטה מן הדעת בבחי' הקטנו' ביותר כע\"ה וכה\"ג, ולפי ערך כל א' כך ערך עונשו דודאי נשמו' שנק' זרע אד\"ם כשימצא בהם איזה פגם דק שבדקות חוטא גדול יחשב מחטא דע\"ה בפ\"מ כו'. וזהו שאו' בש\"ע סלח לנו אבינו כי חטאנו אע\"פ שבק\"ש או' ואהבת בכל לבבך ובכל נפשך כו' ובש\"ע בא לכלל ביטול במציאו' בקרבתו לאלקי' בתכלית בעילוי ההשג' האלקי' כו', דאדרבה היא הנותנת אחר שקרוב אל אור פני מלך נעשה בנפשו חוטא גדול יותר כשאינו בתכלית העבוד' כדבעי וע\"כ או' סלח לנו כו' לבקש על נפשו סליחה ומחילה יותר מעובר עבירה גשמי' כאותן שהן מבחי' זרע בהמה כע\"ה וכהנ\"ל, וזהו וסביביו דוקא מדקדק עליהם כו', וזהו ענין התשוב' שבצדיקי' דוקא וד\"ל.\n<b>וזהו</b> דמשיח אתא לאתבא צדיקיי\"א דוקא בתשוב' לפי שבימו' המשיח יתגלה מבחי' שם מ\"ה העליון כמו שהוא שלמעלה מהארתו בפנים כו' כנ\"ל ואזי יבואו הצדיקי' לבחי' הביטול בפנימי' יותר בעומק אחר עומק כו' עד שגם חומר גופם יבוטל כמו ביטול הנשמ' האלקי' כנ\"ל א\"כ יהיו בנפשם חוטאי' ביותר ויאמרו סלח לנו כי חטאנו כו' מטעם הנ\"ל שלפי ערך הקירוב והמעלה כן יחשב חטא כו', ולפי\"ז יבאו הצדיקי' לבחי' תשובה עילא' ביותר מתשו' של הפחות ערך והרי יוכללו מב' דברי' הפכיי' מאי\"ן ליש ע\"י הארת שם מ\"ה למטה מטה גם בגופם"],[1900640212,"שזהו מאי\"ן לי\"ש בהתלבשו' הי\"ש דחומר הגוף כמו שהוא למטה דוקא כנ\"ל וגם מי\"ש לאי\"ן ע\"י התשובה במה שיחשבו חוטאי' ביותר מחמ' הארת שם מ\"ה ביותר כנ\"ל וד\"ל. וזהו שתלוי עיקר התשובה של הצדיקי' במשיח דוקא לפי שבו יאיר אור דשם מ\"ה החדש מבלי העלם ולבוש כלל וכמ\"ש בו ישכיל עבדי כו' וגב\"ה מא\"ד למעלה מבחי' אד\"ם כו' וד\"ל. וכידוע שהוא מלך השמיני כו' אך לא ע\"י מעבר לבד כנ\"ל וכמ\"ש ונחי\"ה לפני\"ו ממש כנ\"ל וד\"ל. ואמנם הנה גם בחי' שם ב\"ן יתברר לע\"ל ויעלה לבחי' ס\"ג ע\"י התשו' ממש כנ\"ל שזהו עולה לבחי' העצמו' כמו שם מ\"ה העצמי שיורד מן העצמו' א\"כ ה\"ז כמו עד\"מ ב' בנ\"א א' עומד למעלה מאד והב' למטה מאד שיש ב' אופני' ביחודם וחיבורם א' שהעליון יורד לגבי התחתון והב' שהתחתון יעלה לגבי העליון והאופן הג' הוא שהעליון יורד עד חצי ההר והתחתון עולה עד חצי ההר ומתחברי' שם באמצע ההר כו'. וכך הוא עתה בענין שילוב הוי' באד' כו' וכמו בסמיכת גאולה לתפלה כידוע. אבל לע\"ל ירד שם מ\"ה מלמעלה למטה ממש וגם שם ב\"ן יעלה למעלה ממש וא\"כ יהי' שוה היחוד דמ\"ה וב\"ן למעלה ולמטה כאילו אין כאן מעלה ומטה כלל וזהו שיהי' הוי' אחד ביחוד דמ\"ה וב\"ן ושמו אחד ביחוד דמ\"ה וב\"ן למטה הכל בשוה למהוי אח\"ד en.en.באח\"ד כמו העיגול שמצד עצמו אין בו מעלה ומטה כלל כידוע וד\"ל.\n<b>וזהו</b> לעברך בברית ה' אלקיך, פי' ברית ה' אלקיך הוא בחי' יחוד וחיבור דשם מ\"ה דהוי' עם שם ב\"ן דאלקי\"ם כו' דעכשיו א' כי ה' אלקיך א\"ש אוכל\"ה הוא שזהו בחי' רו\"ש דמ\"ה וב\"ן כנ\"ל לברר לעה\"ד טו\"ר מגבורו' הקשו'. וזהו שמ\"ה מברר לב\"ן ונק' אש הוי' אש אוכל\"ה לאש זרה דב\"ן דק\"נ כו' בהיותו יותר למטה להתלבש בשם אלקי' בחי' ב\"ן המתברר כו', אך לע\"ל ע\"י תשוב' דצדיקי' יהי' יחוד מ\"ה וב\"ן זה בתכלית השלימו' שלמעלה מבחי' עלי' ויריד' כלל דשם מ\"ה יתגלה למטה כמו למעלה ושם ב\"ן יעלה למעלה כו' כנ\"ל וד\"ל (משא\"כ"],[1900640213,"עכשיו דמ\"ה וב\"ן מתחברי' באמצע כמו דוגמת ב' חצאי כדורי' כידוע, והוא כמו שהעליון יורד קצת והתחתון עולה קצת כנ\"ל, וגם בעצם מהו' דמ\"ה וב\"ן יהי' לע\"ל בהיפוך דעכשיו בחי' הרצוא לעלות למעלה הוא בחי' מ\"ה כנ\"ל ובחי' השוב למטה הוא בחי' ב\"ן כנ\"ל ולע\"ל יתהפכו שבחי' מ\"ה ירד מגבוה לנמוך כנ\"ל ובחי' ב\"ן יעלה מנמוך לגבוה כנ\"ל וד\"ל). וזהו מעט מעט אגרשנו מפניך דקאי על בירור דב\"ן ע\"י שם מ\"ה עכשיו, עד אשר תפר\"ה שיומשך שם מ\"ה החדש כו' ונחלת את הארץ בחי' ב\"ן להיו' א\"ח עט\"ב כו' כידוע וד\"ל.\n<b>והנה</b> מעתה יש להבין עפ\"י כל הנ\"ל בבחי' מ\"ה וב\"ן ענין הפסוק ואשמע אחרי קול רעש גדול, מהו אחרי ומהו רעש גדול. דהנה כתי' ואחרי הרוח רעש לא ברעש ה', ואחר הרעש אש לא באש ה' כו', בהיות דג' מדרגו' אלה רוח ורעש ואש יש שהן בבחי' שם הוי' ע\"כ א' דרעש ורוח ואש דכאן לא ברעש ה' ולא באש ה' כו'. וביאור הענין הוא דג' מדרגו' אלה היינו ג' מדרגו' דשרפי' וחיות ואופני הקדש שכל זה הוא נמשך רק משם אלקי' בחי' ב\"ן שבכל עולם לפי ערכו, כמו השרפי' שבעולם הבריא' הוא בהתפעלו' דו\"ר שכליי' דאימא עילא' דאצי' מקננא בכורסייא כו', וזהו ע\"י בחי' ב\"ן דשם אלקי' המאיר בבינה דמל' דאצי' שמלובש בבריא' כו' והוא בבחי' א\"ש שלזה נק' שרפי\"ם. אך היינו בחי' א\"ש אלקים ולא אש הוי' כלל ובחי' התפעלו' החיות הקדש שבעולם היצי' בבחי' רע\"ש והוא למטה מבחי' רשפי אש, וגם זה בא מבחי' ב\"ן שבעולם היצי' ונק' רע\"ש דאלקי' ולא רעש הוי' כלל, וכן האופנים שבעולם העשי' בבחי' רוח וכמ\"ש כי רו\"ח החי' באופנים כו', ולא ברוח הוי' רק מבחי' אלקי', לפי שכל המלאכי' שבג' עולמו' דבי\"ע הכל מקבלים רק מבחי' שם אלקי' ונקראו בני האלקי' ולא משם הוי' כו', להיות שעיקר בחי' כח הפועל אלקי שבהם הוא מבחי' שם אלקי' בכל עולם ועולם לפי ערכו כידוע."],[1900640214,"<b>אך</b> הנה כל ג' חילוקי מדרגות האלה דרוח ורעש ואש דבחי' אלקי' שבבי\"ע בשרפי' וחיו' ואופני' ישנם למעלה בבחי' שם הוי' דאצי' ממש ונק' רוח הוי' ורעש הוי' ואש הוי', והיינו כמ\"ש בזוהר דאית רעש ואית רעש כו' וכמו שידוע בדרך כלל ששרש הנשמו' הוא בשם הוי' ונק' נר הו\"י' והיינו שרש פנימיו' העולמו' ושרש המלאכים בחי' חיצוניו' העולמו' שמקורם הוא בחי' ב\"ן דאלקי' כנ\"ל. וזהו שא' ואשמע אחר\"י קול רעש גדול אחר\"י דוקא לפי שנשמת הנביא ברעש דהוי' כו' לכך שמע רעש גדול דמלאכי' דיצי' בלבד כו' (וע\"ד דוגמא נפש האלקי' גם שבבחי' עשי' שנק' נפש דעשי' היא בפנימי' האופני' דעשי', כמו חי ה' אשר עשה לנו הנפש הזאת, ונפש דק\"נ שהוא נה\"ט שרשה משמרי האופני' והאופני' עצמן בחי' ממוצע לחבר ולקשר הנפש אלקי' בגוף והן המלאכים שחונים לנשמו' גם במי שאין לו רק נפש דעשי' כמ\"ש כי מלאכיו יצוה לך כו' וכה\"ג הרי אנו מוצאי' דמלאכי אלקי' מעלין התפלה שבלב ודיבור בפה שמורכב מהתפעלו' הנה\"א בנה\"ט למעלה כו' לפי ששרש כל הנשמו' דנר\"נ מל' כלים דז\"א דאצי' ממש פנימי' הכלים בנשמה עד חיצוני' הכלי' בנפ\"ש דעשי' וד\"ל).\n<b>והנה</b> להבין בתוס' ביאור ענין ג' חלוקי מדרגו' דרוח ורעש ואש בחיצוניו' כמו במלאכי' דבי\"ע כנ\"ל ואיך שהן בבחי' הפנימיי' דשם הוי' דאצי' כנ\"ל, הנה אנו רואי' באדם למטה בעבודה שבלב ומוח בעת התפלה שכאשר יעמיק דעתו ובינתו להבין ולהשיג בטוב טעם ודעת באלקו' איך שמחי' את הכל דוקא שזהו מבחי' ב\"ן דשם אלקי' כנ\"ל, הנה יוליד מזה התפעלות גדולה בלבו במורגש ברעש גדול הניכר ונראה לכל רואה שזהו בחי' התחדשות בנפשו מה שלא הי' בו מקודם כלל, וזהו עיקר סיבת הרעש שלו כי הי' תחלה נפרד מאור פני מלך חיים ונמשך כולו אחר עניני גופו בהבלי שוא כו' וכאשר נתפעל מהתבוננו' באלקו' נמשך לבו אחרי ה' לבדו ומשליך לנגד הרצון הזר שהי' דבוק בו קודם ה\"ז התחדשות גדולה כי מן החושך יצא לאור מהיפוך להיפוך ע\"כ יבא ענין ההתפעלו' הזאת בקול רעש דוקא בבחי' יש ודבר מה הבולט וניכר לכל והיינו ע\"ד אסתירא בלגינא כו' כי אין זה רק מפני שהי' יש נפרד ויצא מהיפוכו המסתיר לו כו', וזהו הרעש שאינו"],[1900640215,"ברעש ה' וכמו האופני' וחיו' ברעש שיוצאי' מחומר שלהם כו' והוא הנק' התפעלו' חיצוני' שבחיצוני' הלב לבד שהוא רק ביטול הי\"ש הנפרד לאי\"ן האלקי, וכמ\"כ בהתפעלו' רוח שזהו מה שנתעורר רוחו הוא בבחי' חיצוניו' הלב כו', ואפי' התפעלו' היותר פנימי שהוא בהתלהבו' הלב מצד עומק ההשג' האלקי' אינו באש הוי' אלא רק מצד הפלא' ההשג' כנ\"ל שבא ההתפעלו' בבחי' יש ודבר מה שיש מי שמתפעל ומרגיש ביטו\"ל זה שמבטל עצמו כו', שאין זה בחי' ביטול האמיתי שהוא היפוכו דהיינו העדר הרגשת עצמו בביטול זה לגמרי כידוע וע\"כ אינו אש הוי' כלל כי אור א\"ס שבשם הוי' אינו שורה כ\"א על בחי' ביטול בעצמו' בתכלית אמיתתו מבלי ירגיש עצמו באיזה שינוי למעליותא במה שנתפעל ונשתנה מכמו שהי' כו' וכעומד לפני המלך שמתבטל לגמרי מבלי ירגיש עצמו ומקומו כלל והוא בחי' שם מ\"ה הנ\"ל באריכות וד\"ל.\n<b>וזהו</b> שא' ואחרי הרעש אש לא באש ה' ואחרי האש קול דממה דקה וא' בזוהר דתמן קאתי מלכא שהוא כעומד לפני המלך שמתבטל כל עצמותו לגמרי ואין בו שום התפעלו' מורגשת בעצמו ואינה ניכרת לרוא' כלל אלא הוא כאבן דומם ושותק וכל תנועותיו בחשאי ובביטול גדול, וזהו בקול דממה דקה בלא רעש ואש בהתגלו' כלל משום דקאת\"י מלכא כו'. וכמו בסמיכת גאולה לתפלה שאו' אד' שפת\"י תפת\"ח כו' משום דנתבטל בהגיעו קרוב לאור פני מלך עד שאין לו כח הדיבור מעצמו כלל כמו אין מלה בלשוני כו' רק אד' שפת\"י תפת\"ח כו' כידוע וד\"ל. והנה בק\"ש ושתים לפני' עד ש\"ע הכל הוא בבחי' התפעלו' דרוח ורעש ואש שאינו בשם הוי' (דגם באמרו שמע ישראל הוי' כו' הוא בשמיעה דבינה בהשג' דבחי' ב\"ן וממילא התפעלו' ואהבת בא\"ש שאינו אש ה' כו'), אך בש\"ע דתמן קאתי מלכא והוא בחי' קול דממה דקה שהוא בחשאי בצלותא דבלחש דוקא והמשמיע קולו בתפלת\"ו ה\"ז מקטני אמנה היינו בש\"ע דוקא כידוע ,להיות שאז הוא בבחי' שם מ\"ה דאצי' והוא ענין ההשתחוואו' בח\"י ברכו' כשזוקף בשם כו' דהשתחווא' זו בש\"ע היא בבחי' אצי' כידוע, ואמנם הנה גם בבחי' שם מ\"ה זה דאצי' יש כל ג' חלוקי מדרגו' הנ\"ל דרוח ורעש ואש כידוע דגם האצי' כלול"],[1900640216,"מבי\"ע, דהיינו ג' מדרגו' דשרפי' וחיו' ואופני' כו' והוא בחי' נר\"נ דאצי' כו' אך שם נקראי' בשם הוי' דוקא כנ\"ל והוא רוח ורעש ואש דבחי' הוי', רעש ה' ואש ה' כו' וזהו דאית רעש כו' כנ\"ל.\n<b>וביאור</b> הענין יובן עפ\"י המבואר במ\"א בענין מא' הזוהר בבחי' קלא פנימאה דלא משתמע כו' דהנה יש להבין איך שייך לקרותו בשם קול אם הוא בפנימי' דלא משתמע כלל לזולתו כו'. אך הנה ידוע שכמו שהקול היוצא מהבל הלב לחוץ דמשתמע לזולתו מורכב מאמ\"ר גשמיי' ויש בו פנימי' וחיצוניו' כמו צעקת הקול בגשמיו' שניכר בו פנימי' החיות יותר מקול פשוט בלי צעקה שנמשך בקרירות כו', כך ממש יש בקול הבל הלב עצמו טרם שיוצא דרך הפה לחוץ כו', כי הנה בהבל הלב עצמו יש הרכבה מאמ\"ר בבחי' פנימי' וחיצוניו' אך שנק' קלא פנימא' דוקא. והענין הוא כידוע שמשכן רוח החיים בלב בחלל הימני נמשך מן המוח דחכמ' והוא בחי' פנימי' הלב ובחלל השמאלי שבו עובר הדם הוא הנפש בכל האיברי' הוא בשר הלב בבחי' חיצוניו' הבל הלב, שכאשר יבא לו שמחה יהי' בו התפשטו' וכאשר יעצב יכווץ וממוצע מעוצב וחדוה הוא הבל קול הלב שמזווג מאמ\"ר רוחניי' כידוע, וכמו שיש בקול החיצון שמורכב מאמ\"ר גשמיי' צעקת הקול שהוא בחי' הפנימי' כך יש בקלא פנימאה שנק' קול הבל הלב עצמו דלא משתמע לחוץ כלל ג\"כ בחי' צעקה כדוגמת קול צעקה גשמיי' אע\"פ שאינה נשמעת לזולתו כלל ונק' צעקת הלב כמו צעק לבם אל ה' כו' שהלב עצמו צועק שהוא מבחי' פנימי' הלב דוקא, דכמו צעקת הקול גשמי שבא בבחי' פנימי' היינו מצד שלא יוכל להכיל בלבו ע\"כ יצעק בקול להיותו למעלה מכלי הלב הגשמי שנק' בשר הלב שהוא הבל הקול החיצון כו', כך הוא ענין הצעקה בפנימי' הקול שנק' קול צעקת הלב עצמו כנ\"ל שזה בא מצד פנימי' ונקוד' הלב שלפעמי' אין החיו' הפנימי שבנקוד' הלב יכול להכיל ולסבול ההתפעלו' שבא מן מוח החכמ' שבראש שלמעלה מן הכלי פנימי' שבלב להכילו, ע\"כ יצעק בצעקה פנימי' שבלב שלמעלה מן השכל שהוליד ההתפעלו' בלב כידוע שזהו בחי' בכל מאד\"ך וכמו צעק לבם כו' ונק' צעקת הלב שהלב צועק בפנימיו' דוקא מפני שלא יוכל להכיל כו' (וכמו שנראה בחוש בכעס פנימי שבלב כאשר עוצר וכובש כעסו לבלתי יוכר לזולתו מפני הירא' וכה\"ג שישאר עומק התפעלותו בפנימי' הלב שלא יוכל להכילו כלל יעשה תנועות משונות מאד שיוצאי' מדרך בן דעת כו', וכך בהתפעלו' אה\"ר או חדוה ועונג בפנימי' הלב לאוהבו כנפשו שלא יכילנו en.יוליד תנועו' משונו' כו' והכל בפנימי' וד\"ל)."],[1900640217,"<b>והנה</b> מאחר שגם בקלא פנימא' שבתוך נקוד' הלב יש בחי' צעקה פנימי' והרי הוא מורכב מאש מי\"ם רו\"ח פנימיי' כו' הרי יובן שימצא גם שם ג' מדרגו' הנ\"ל דרוח ורעש ואש רק שכל זה הכל בבחי' הפנימי' שבלב דוקא, וכמו התפעלו' רשפי אש בפנימי' נקוד' הלב הוא אש פנימי ביותר שלא נראה וניכר מגודל עומקו כו' (בל\"א די הארצ גלייעט אין וויניק טיף זיער כו'), וכמ\"כ בהתפעלו' רעש שבא מהתחדשות דבר שנוגע לעצמו ופנימי' ביותר שירע\"ש בו הנקו\"ד' הפנימי' שבלב בלי יוכר לזולתו כלל רק הוא בתוך תוכו (וכפחד פנימי שיחרד ויפחד בתוך פנימי' הלב עצור וכנוס בלי היכר כלל כו'), וכמ\"כ התעוררו' רוח ברוח החיים שבפנימי' הלב כמו ורוח לבשה את עמשי כו', וכהנ\"ל הכל הוא רק בבחי' פנימי' עומק הלב שאין להתפעלו' רוח ורעש ואש שבחיצוניו' הלב בקול החיצון ערוך להם כלל וד\"ל.\n<b>ומזה</b> יובן למעלה שיש ג' מדרגו' דרוח ורעש ואש למעלה בבחי' האצי' שזהו כמו פנימי' הלב בקול צעקה פנימי' כנ\"ל שכלול מאמ\"ר כו' שהוא רוח ורעש ואש הכל בחי' הוי' דאצי' ונק' אש הוי' כו' כנ\"ל, והיינו בבחי' קול דממ\"ה דקה שהוא נק' קלא פנימא' דלא משתמע לחוץ בבי\"ע כו', כי הוא בבחי' פנימי' לב האד\"ם העליון כו' ששם ג' מדרגו' הנ\"ל בתכלית הביטול בשם הוי' אש הוי' ורעש הוי' כו' והיינו הכל בבחי' קול דממ' דקה דשם מ\"ה דאצי' כמו קול הטמון ונעלם בפנימי' נקוד' הלב כנ\"ל. וזהו בש\"ע דצלותא בלחש כמו בחנה שא' וקול\"ה לא ישמע לחוץ ואמנם הוא קלא פנימא' שכלול מג' מדרגו' הנ\"ל ג\"כ רק שהוא בבחי' צעקה פנימי' שנק' צעקת הלב באש הוי' וברעש הוי' כנ\"ל וד\"ל. אך הנה בחי' שם ב\"ן דאצי' שרשו הוא בהבל לב האד\"ם דאצי' בבחי' חיצוניו' דקלא דמשתמע לחוץ כמו בדבר ה' שמים נעשו כו' בקול ודיבור ממש ומשם נמשך ג' מדרגו' דרוח ורעש ואש דמלאכי' דבי\"ע בשרפי' וחיו' ואופני' בבחי' יש ודבר מה היפך בחי' הביטול שבפנימי' כו' וע\"כ אינו רעש ואש הוי' כלל כנ\"ל וד\"ל.\n<b>וזהו</b> שאנו אומרי' ויחד לבבינו ב' לבבות כי הנפש הטבעי' שרשה משמרי האופני' דעשי' מדרגת עבודה באוי\"ר מורגש ברעש ואש כמלאכי' כו' והנשמ' שרשה בבחי' מ\"ה דאצי' בפנימי' הלב כנ\"ל וצריך לייחד ב' הלבבו', ולכאורה איך יתייחד הפנימי' עם החיצוניו', אך הענין כמ\"ש ממעמקים קראתיך הוי' ב' עומקי' הא' עומק שבחיצוניו' הלב כמו קול צעקת המתפעל ברעש גדול"],[1900640218,"וכמו כארי\"ה ישא\"ג כו' והב' עומק שבפנימי' צעקת הלב כנ\"ל והיינו ב' עומקי' דמ\"ה וב\"ן דנשמו' ומלאכי' בשם הוי' ואלקי' בדרך כלל כנ\"ל, אמנם כעת המה רחוקים זה מזה בערך כנ\"ל אבל בימו' המשיח דוקא יתחברו ויתייחדו והיו לאחדים ממש משום דבחי' ב\"ן יעלה למעלה מעלה כנ\"ל בבחי' התשוב\"ה שנהפך מי\"ש לאי\"ן ובצדיקי' דוקא שהוא ע\"י ירידת שם מ\"ה למטה מטה ביותר כו' כנ\"ל, א\"כ הרי עומק דבחי' מ\"ה שמלמעלה ועומק דבחי' ב\"ן שמלמטה יחדיו יהיו תמים והיו לאחדי' כאשר יתחברו עומק רום עם עומק תחת ע\"י תשובה שבצדיקי' כנ\"ל שלמעלה מבחי' מעלה ומטה כלל כנ\"ל באריכו' וד\"ל (וזהו ממעמק\"י' ב' עומקי' דלמעלה ושלמטה קראתיך הוי', הכל בשם הוי' למהוי אח\"ד באחד ממש כנ\"ל, וזהו כמשל עומק התהום שיש לו עומק מב' צדדיו בשוה כו' וד\"ל).\n<b>ובכל</b> הנ\"ל בענין משיח דאתא לאתבא צדיקייא בתיובתא כו', יובן עוד מ\"ש במשיח ויתן עוז למלכו וירים קרן משיחו כו', ויש להבין סדר הפסוקים ה' יחתו מריביו כו' עד עליו בשמים כו' ויתן עוז כו'. והנה יש להקדים לבאר תחלה המא' באד\"ר במ\"ש וחסדי מאתך לא ימוש כו' וכתי' בחסד עולם כו' דהיינו ההפרש בין חסד דלגיו ובין חסד דלבר כו' ע\"ש. בהיות שיש להבין שרש ענין הג\"ע שהוא מוסיף אור תמיד ע\"י מעשה המצות בעוה\"ז דוקא כאשר נעשי' בכוונה ורעותא דלבא וכמו שא' באדה\"ר לעבדה ולשמרה וא' לעבדה רמ\"ח מ\"ע ולשמרה שס\"ה ל\"ת ובודאי לא קיים אדה\"ר רמ\"ח מ\"ע בגשמיו' כציצי' ותפילין שלנו, וצריך לומר דלעבדה ברמ\"ח מ\"ע דקא' היינו בבחי' הרוחניו' דוקא דהיינו כמו שהן בשרשן ברוחניו' בבחי' האצי' וכה\"ג, וכידוע שבדוגמא זאת הוא שקיים אברהם אע\"ה כל המצות אפי' ע\"ת וכמ\"ש עקב אשר שמע אברהם בקולי וישמור כו' מצותי חוקותי ותורתי כו' דהיינו ג\"כ בשרש המצות העליוני' כמו שהן למעלה בבחי' הרוחניו', דאיך אפשר לומר שקיים מצות תפילין בד' פרשיו' כשלנו שנז' בהם יצ\"מ וכמו קד\"ש לי כל בכור כו' וכה\"ג כל המצו' התלויו'"],[1900640219,"בארץ, אלא אמיתי' ענין כל המצות כמו שהן בשרשן למעלה קיים הכל אפי' ע\"ת en.כו' וד\"ל.\n<b>ולפ\"ז</b> יש להבין בענין קבלת שכר המצות בתוס' אור בג\"ע כנ\"ל דודאי אין ערך כלל לומר שהתגשמות המצות בפ\"מ כתפילין וציצי' מצמר וקלף גשמי להיו' מוסיף מזה אור האלקי בג\"ע שהוא תכלית הרוחניות כו', אם לא שנאמר שמבחי' הרוחניו' של המצות כמו שהן למעלה מוסיפי' האור בג\"ע והוא עיקר קבלת השכר, ובאמת לא על בחי' הרוחניו' נצטווינו רק לעשות בפ\"מ דוקא ובזה יש יתרון מעלה לבנים על אבות וכמ\"ש ושמי הוי' לא נודעתי להם משום שלא קיימו האבות מצות בגשמיו' רק ברוחניו' כעובדו' דחפירו' בארו' ומקלות כו', וא\"כ עיקר קבלת השכר שהוא על המעשה בפ\"מ דוקא איך יהי' מזה שיאיר אור הרוחניו' דמצות בג\"ע כנ\"ל אחר שהמעשה עצמה גבוה במעלה מבחי' הרוחניו' שלה וזהו שאמרו שכר מצוה מצוה עצמה דוקא כידוע וד\"ל. ועוד יש להבין במה שאמרו דשכר מצוה בהאי עלמא ליכא רק לעוה\"ב וכמא' המשנה כ\"י יש להם חלק לעוה\"ב אפי' פושעי ישראל משום דמלאים מצות כרימון שנא' ועמך כולם צדיקי' במצות בפ\"מ, וא\"כ מהו ענין הג\"ע שניתוסף אור ע\"י מעשה המצו' בעוה\"ז הרי יש קבלת שכר בג\"ע קודם לעוה\"ב ועונש בגיהנם לעוברי רצונו. ולפי המובן ממ\"ש אלה לחיי עולם ואלה לחרפו' כו' היינו הכל לזמן עוה\"ב דוקא ומהו ענין ההפרש בין ג\"ע לעוה\"ב אם מה שבעוה\"ב יהיו נשמות בגופי' אחר תח\"ה, זה אינו מעלה יתירה כ\"כ דודאי נשמות בלא גופי' שנהנין מזיו השכינה בג\"ע העליון יותר נעלה הרבה ממה שנשמ' בגוף יקבל עונג זיו האלקי לעוה\"ב כו' וד\"ל.\n<b>ועוד</b> יש להבין במא' המשנה אלו דברים שאדם אוכל פירותיהם בעוה\"ז והקרן קיימת לעוה\"ב כיבוד אב ואם כו' (ולא מנה מצות דאוריי' כהלווא' המת וביקור חולים כו') שהן ה' דברים בלבד ולמה יצאו אלו מכלל כל המצות ששכר"],[1900640220,"מצוה בהאי עלמא ליכא כנ\"ל, ועוד דמקרא מלא דיבר הכתוב שמתן שכרם של מצות הן בהאי עלמא דוקא וכמ\"ש אם בחוקותי תלכו כו' ונתתי גשמיכם בעתם כו' ונתנה הארץ יבולה כו', ובהיפוך תחרב הארץ ויהי' לקללה ולא לברכה וכמ\"ש ראה נתתי לפניך כו' הברכה והקללה את הברכה אשר תשמעון כו' והקללה כו', וכן א' והי' א\"ש תשמעו אל מצותי כו' ונתתי מטר ארצכם ואספת דגנך כו' ופן יפתה כו' וסרתם כו' וחרה אף ה' ועצר השמי' כו' ואבדתם כו', וא\"כ שכר ועונש בפ\"מ בהאי עלמא דוקא על המצות כולן ואיך א' דשכר מצוה בהאי עלמא ליכא, וא\"כ הכונה דאוכל פירותיהן בעוה\"ז והקרן קיימת לעוה\"ב א\"כ למה פרט ה' דברי' הללו בלבד שאדם אוכל פירותיהן כו' הרי כל המצות כן הוא, ועוד דשכר מצוה ליכא בהאי עלמא משמע שאין שום שכר עכשיו בגשמיו' כו' וזה סותר למקראות en.הרבה כנ\"ל וד\"ל.\n<b>אך</b> הנה יש להבין תחלה שרש ענין הג\"ע מהו דכתי' ביה ויברא ה' אלקי' גן בעדן מקדם כו' דמשמע שהג\"ן הזה בא בבחי' בריא' מאין ליש ואמנם העד\"ן הוא מקד\"ם שנא' בו עין לא ראתה אלקי' זולתך יעשה למחכ\"ה לו שהוא העה\"ב כו'. והנה יש להקדים תחלה ביאור הפסוק אני ראשון ואני אחרון, אנ\"י אותיות אי\"ן כידוע. והענין הוא כידוע דהחכמ' נק' ראשי\"ת בתי\"ו ל' נוקבא כי החכמ' מאי\"ן תמצא וזהו ראשי\"ת חכמה כו', אך ראשון בנו\"ן ל' זכר הוא מקור של החכמ' והוא בחי' אי\"ן דכת\"ר וע\"ז א' אנ\"י ראשו\"ן ואני אחרון דהיינו כמו שאני אחרון בבחי' המל' סופא דכל דרגין להוות הבריא' יש מאין בפ\"מ שנק' עשי' גשמי' כך ממש אני ראשון להוות החכמ' מאי\"ן בבחי' עשי' גשמי' ממש בשוה בלי שינוי כלל."],[1900640221,"<b>ולהבין</b> זה יש להקדים הידוע בענין מלכותך מלכו' כ\"ע כו' דכל עיקר ומקור חיות כל העולמי' הוא מבחי' מלכות\"ך דוקא והוא בחי' מל' דא\"ס עצמו שהוא נק' מלכות\"ך ממש, והוא מקור דמלכות דכל עולמי' שבהשתלשלות דאבי\"ע כמלכו' דא\"ק ומל' דע\"י ואו\"א וז\"א עד מל' דאצי' ומל' דבריא' עד מל' דעשי' שהוא מדרג' היותר תחתונה להוות עולם השפל שלנו כו', וזהו פי' מל\"ך מלכ\"י המלכ\"י' שלמעלה באבי\"ע דהכל נמשך ממלכותך שהוא מלכו' כ\"ע והיינו שעלה במחשבה העצמי' אנא אמלוך כו' שזהו הנק' מל' דא\"ס כידוע. וביאור זה הנה ידוע בבחי' מל' דאצי' שהוא מקור להתהוות ג' עולמו' בי\"ע שנק' בשם מלכו' דוקא ולא לשאר כינויי המדות זולת מדת המלוכה והלא גם בחסד ברא העולמו' כמ\"ש כי אמרתי עולם חסד יבנה וכן במדת הדין כמו שא' בראשית ברא אלקי\"ם שהוא מדה\"ד ושתף עמו מדה\"ר כידוע. הענין הוא לפי שיש הפרש גדול בין מדת המל' למדות חו\"ג וכה\"ג, בהיות שאנו רואי' במדות האדם למטה שהן כוחות עצמיי' מעצמיות הנפש ממש אע\"פ שהחסד או הדין נמשך מן השכל היינו שנולד אופן ההתפעלו' לבד אבל עצם מציאותן ודאי נוגעי' בעצם הנפש ממש כי משם עיקר הוייתן, וראי' לזה מאשר אנו רואי' שתתפעל עצם הנפש ממש ממעשה החסד שעושה לזולתו אע\"פ שהחסד נולד בלב מן השכל, וכן ממעשה דין ועונש יתפעל בעצם הנפש וכן כל המדו' כולן וכן בהתפעלו' אהב' או ירא' ופחד יתפעל כל עצם הנפש כו' (ובמ\"א מבואר שיכול להיו' כליון כל הנפש באהבה כאהבת דוד ויונתן דאהבת נפשו אהבו וכחולת אהבה מאיזה תאוה כו', וכן בפחד וירא' כו' לפי שכוחו' המדו' נטועי' בעצם הנפש וכל עצם בלתי מתחלק כו' וד\"ל), וע\"כ ממילא מובן שהמקבל שפע החסד קיבל דבר ויש מה שהוא מעצם המשפיע ממש כו', אבל הנה מדת המלוכה אע\"פ שהיא מדה כשאר המדו' אבל בזאת נבדלת שאין אור שפעה בבחי' עצמיות כלל שהרי ההתנשאות אינה רק בחי' התפשטות חיצוניו' בלבד שמתפשט על זולתו בבחי' מקיף עליו בלבד ולא שנכנס ומתקבל בתוך זולתו בבחי' יש ודבר מה במציאת כשפע החסד כו' (ואמנם ודאי שתתפעל הנפש בבחי' עצמיו' מן רוב ההתנשאו' או מן הכבוד וגדולה יותר משתתפעל"],[1900640222,"ממעשה החסד ודין, כי גדול התענוג שבהתנשאו' וכבוד וגדולה יותר מכל התענוגי' שבמדות ושכל וכל רצון זולתו כידוע, אך זהו בעצמותו לבד מפני שנטוע בעצם נפשו מדת ההתנשאו' כמ\"ש רד\"ו בדגת כו' שזה טבע אד\"ם דוקא כידוע כמו שנטוע בו מדת הטוב והחסד, ואדרבה מדה זו מגיע בעצמיו' יותר מאחר שהתפעלות הנפש בעצם יותר מן ההתנשאו' עד שיפקיר כל אשר לו עבור השג' הכבוד כו' כמלכי אדמ' שנלחמי' עבור זה כו', לפי שההתנשאו' תנשא ותגביה כל פנימי' ועצמו' הנפש כמו כת\"ר מל' שמכתירין ומנשאי' אותו הרבה מכפי ערך עצמו אבל גם זה עליו בבחי' מקיף ולא שנכנס ומתקבל בתוכו ומכ\"ש שלא יהי' אור שפע זו מן ההתנשאו' על זולתו רק בבחי' התפשטו' חיצוניו' בבחי' מקיף עליו בלבד כנ\"ל וד\"ל), וע\"כ נק' המל' בשם עטרה כידוע כעטרה שמקפת על en.en.הראש בבחי' מקיף לבד וד\"ל.\n<b>והנמשל</b> מכל זה יובן למעלה במ\"ש מלכותך כו' דמבחי' מדת מל' דאצי' דוקא נמשך מקור חיות כל העולמות ולא ממדה אחרת כחו\"ג דאצי' לפי שאין ערוך כלל בין בע\"ג לבלתי בע\"ג, ואם הי' נמשך מאור מדת החסד דאצי' ששרשו בעצמות המאציל כמו משל התפעלו' עצם הנפש במעשה החסד כו' וגם המקבל הי' מקבל מבחי' מהות ועצמו' אור המאציל שבחסד עליון דאצי' הרי לא הי' באפשר שיהי' למציא' בע\"ג אלא הי' הכל בבחי' א\"ס, ולזאת לא נמשך מקור לבע\"ג רק ממדת המל' מפני שהוא בא בבחי' התפשטו' חיצוניו' בלבד כנ\"ל, היינו רק בבחי' מקיף לבד כנ\"ל. וזהו ה' מלך גיאות לבש שההתנשאו' וגיאות ה' על כל העולמו' הוא רק בבחי' לבוש ומקיף מרחוק שמפני זה יכולי' להיות בבחי' הגבלה מאי\"ן ליש וזהו שרש התהוות מציאותם בכל רגע כו' וד\"ל (וזהו שנק' המל' עטרה שהוא בחי' כת\"ר מל' שנק' מלך מרומם לבדו ומתנשא מימו' עולם וכן מ\"ש מלך יחיד חי העולמי' או יחיד חי העולמי' מלך כו' ולא כמלך ב\"ו שאין מלך בלא עם נפרד כו' והרי למעלה א' ממ\"ך הכ\"ל כו' דאין לך דבר חוץ ממנו כו' וא\"כ איך יתכן המלוכה דודאי טרם שנברא העולם הי' הוא לבדו ואחר שנברא אינם בבחי' עם נפרד כו', הענין הוא כמ\"ש במ\"א דע\"י בחי' ההתנשאו' דמל' בטרם שנברא"],[1900640223,"העולם שנק' מלך מרומם לבדו כו' מלך הקדוש וכה\"ג מזה עצמו נעשה בחי' הצמצום והריחוק שיוכל להיו' הבריא' מאי\"ן לי\"ש, וזהו אמיתי' קיומם אחר התהוותם כו' וכידוע במ\"ש ירא' ה' לחיים שהמלאכי' מפני הירא' אלקי' שעליהם חיים וקיימי' יותר כו' וכמו שא' ומוראך עליה\"ם כו', אך אחר הבריא' הרי זה כמלך על עם וראי' מן המלאכי' שעושין כת\"ר מל' באמצעו' הביטו\"ל הי\"ש לאי\"ן כמ\"ש כת\"ר יתנו לך כו' וכמ\"ש בזוהר ע\"פ גבורי כח עושי דברו כו', ונמצא ב' בחי' מלוכה יש, א' התנשאו' בעצמו קודם הבריא' והב' התנשאו' שמצד העלא' מ\"ן דעולמו' כו', ואע\"פ שהתנשאו' שבא מצד העלא' מ\"ן אין ערוך כלל להתנשאו' שמצד עצמו מ\"מ נמשך בזה עונג גדול יותר מעונג שבכל המדו' כנ\"ל וכמ\"ש במ\"א בענין מלכיו\"ת דר\"ה כו' וד\"ל) (ואע\"פ שנא' כי אמרתי עולם חס\"ד יבנ\"ה, היינו בחי' חסד שבמל' דוקא וכמ\"ש והוכן בחס\"ד כס\"א כו' וכן במדה\"ד שבמל' כו' וד\"ל).\n<b>וזהו</b> אנ\"י ראשון אנ\"י אותיו' אי\"ן היינו בחי' כת\"ר כו'. ויובן זה בבחי' מל' דאצי' שנעשה כתר דבריא' כמו בכל השתלשלו' דע\"ס הרי מבחי' מל' שבעליון נעשה כת\"ר לתחתון כו', דהנה החכמ' נק' ראשית וכתי' כולם בחכמ' עשית וזהו מא' דבראשית כידוע, וא\"כ הרי בחכמ' ברא הכל ולא במדת המל'. אך היינו בבחי' חכמה שבמל' דוקא (וכמו והוכן בחס\"ד כס\"א כנ\"ל), והיינו מפני שהחכמ' מאי\"ן תמצא מאי\"ן דכת\"ר מל' הנ\"ל והוא מא' דבראשית שזהו ראשית הגילוי מעצמות העלם הכת\"ר מל' שהוא בחי' התנשאו' בעצמותו כנ\"ל, והיינו אנ\"י היפוך אותיו' אי\"ן שמההעלם דאי\"ן בא לגילוי ונק' אנ\"י ראשו\"ן דאור הכת\"ר דמל' מאיר בחכמ' מאי\"ן ליש כו' נק' ראשו\"ן בנו\"ן ל' זכר, כי החכמ' נק' ראשי\"ת בחי' נוק' לאחר שנמצא' לי\"ש אבל בעוד שמתייחד בכת\"ר נק' אנ\"י ראשו\"ן כו' ואנ\"י אחרו\"ן היינו לאחר שנברא העולם מאין ליש שמתפשט בחי' מל' עליהם בבחי' מקיף לבד כנ\"ל (שזהו בחי' מל' שבמל' כידוע), והרי נעוץ תחלתן בסופן וסופן בתחלתן שזהו אני ראשון דכת\"ר בחכמ' (וכנ\"ל דמלך מרומם לבדו כו' היינו מלך על עם שאחר הבריא' כי אין הצמצום מסתיר לפניו כלל וכלל וכמא' אתה הוא עד שלא כו'"],[1900640224,"ואתה הוא משנברא כו' וכן הוא ענין אתה ה' לבדך גם לאחר שאתה עשית השמים כו' והוא ענין מלך יחיד חי העולמי' ויחיד חה\"ע מלך דהכל א' מטעם זה), וכך הוא בכל עולם ועולם כמו שמבחי' מל' דבריא' נעשה כת\"ר ליצי' (שזהו מבחי' מל' שבמל' דבריא') היינו כת\"ר דחכמ' שבמל' דבריא' נק' אנ\"י ראשו\"ן ומל' דמל' שנעשה כת\"ר ליצי' זהו אני אחרו\"ן עד מל' דיצי' נעשה כתר לעשי' עד מל' דמל' דעשי' שהוא כת\"ר וראש ושרש לעולם העשי' שע\"ז א' ומלכותו בכל משלה ובחי' כתר מל' דעשי' הוא המלך המרומם ומתנשא מימות עולם דעשי' כו'). ועד\"ז יובן ג\"כ בע\"ס דאצי' בכלל שנאצלו מן עצמו' אא\"ס דאנ\"י ראשו\"ן הוא בחי' מל' דא\"ס עצמו שזהו כאשר עלה במחשבה הפשוטה שבעצמו' א\"ס אנא אמלוך כו' וכלולה מע\"ס וכת\"ר מל' היינו בחי' הרצון והתענוג שבמחשבה זו כו', וכדי שיהי' כתר ושרש לנאצלי' שאין ערוך להם לגבי עצמו' הא\"ס ע\"כ לא נמשך מקורם מבחי' המדו' דא\"ס כחו\"ג וכה\"ג מטעם הנ\"ל במל' דאצי' שנעשה כת\"ר לבריא' שהי' הכל בבחי' א\"ס, וכמו שאין ערוך לבריא' עם הבורא כו' רק מבחי' חיצוניו' התפשטו' דמדת מל' דא\"ס בבחי' מקיף ולבוש וכמ\"ש ה' מלך גיאו' לבש וז\"ש מלכות\"ך ממש כנ\"ל, כי ממדות העצמיי' דא\"ס כחסד דא\"ס שלגדולת\"ו אין חקר לא יכול להיו' מקור וראש לנאצלי' מטעם שהוא מבחי' עצמו' הא\"ס כו'. והנה אנ\"י ראשון בכללות היינו כת\"ר מל' דא\"ס שמאיר בחכמ' שבמל' דא\"ס כנ\"ל במל' דאצי', ואנ\"י אחרו\"ן היינו מל' דמל' דא\"ס שנעשה כת\"ר לנאצלי' ונעוץ תחלתן בסופן כו' כנ\"ל. ועד\"ז יובן דרך פרטי פרטו' בכל עילה ועלול דע\"ס דאבי\"ע דמבחי' מל' שבעליון נעשה כת\"ר לתחתון לפי שכל ספי' כלולה מי' כו' וכמו מבחי' מל' שבחכמ' נעשה כתר לבינה ובינה למדו' כו', אך דרך כלל אני ראשו\"ן במל' דא\"ס ואני אחרון במל' דאצי' עד מל' דעשי'. וזהו ראו כי אנ\"י אנ\"י הוא כו' דאנ\"י אחרון דמל' דעשי' הוא אנ\"י ראשו\"ן דמל' דא\"ס לפי שאין הצמצום הראשון שלפני האצי' וצמצום האחרון שלפני הבריא' ויצי' מסתיר כלל וכלל וד\"ל.\n<b>ומעתה</b> יש להבין ענין הג\"ע, דהנה ידוע בענין הג\"ע שהנשמות נהנין שם מזי\"ו השכינ\"ה היינו מבחי' בינה שבמל' דאצי' שמשם מקור חוצב השגתם בזי\"ו השכינה שמאיר בג\"ע דבריא', ובאמת יש להפלא בזה מאחר שכל יסוד ההשתלשלות הוסד באופן שלא נמשך מעליון לתחתון רק מבחי' האחרונה שבו בריחוק ודילוג המדרג' והיינו רק מבחי' מל' שבמל' שבעליון כנ\"ל, שזהו מדה וקצבה במיעוט אחר מיעוט וצמצומי' רבים והכל כדי שיוכל להיות מציאת העלול שאם הי' בחי' העילה המשפיע מאיר ביתר מכפי המדה והקצבה כנ\"ל לא יתקיים"],[1900640225,"במציא' כלל, א\"כ איך יוכל להיות שהנשמו' דבריא' שהן בבחי' גבול י\"ש מאי\"ן כו', יהיו נהני\"ן מזי\"ו השכינה שהוא עצמו' אור הכת\"ר דמל' דאצי' שהוא בבחי' מהות ועצמו' דאוא\"ס שבמל' דא\"ס דאנ\"י ראשו\"ן ממש (דההשתלשלו' מאנ\"י ראשון אינו אלא אחר הצמצום הראשון מעצמו' אא\"ס עד שבכל עו\"ע נמשך רק מבחי' מל' דמל' שבו עד מל' דמל' דאצי' בבריא' כו' אבל איך יקבלו הנשמו' מכת\"ר מל' דאצי', אע\"פ שהוא ענין אנ\"י אחרון דאין בבחי' הכתרי\"ם ענין צמצום וירידת המדרגו' כלל וכמו שאני אחרון כך אני ראשון ממש בשוה רק ע\"י צמצום דכת\"ר בחכמ' עד בחי' המל' שבו הוא שיש ראש\"י' ואחרי\"ת כו') והרי נא' כי לא יראנ\"י האד\"ם וח\"י פי' האד\"ם הוא הנשמ' האלקי' שבצל\"ם אד\"ם העליון שלא יוכל לראו' בעצמו אלקו' שלמעלה מכפי הצמצום דמל' שלא יתבטל ממציאותו לגמרי כבן עזאי שהציץ ומת כו' (וכך הוא עד רום המעלות גם באורו' דאד\"ם העליון דאצי' לגבי עצמו' המאציל דקאי גם ע\"ז כי לא יראני האד\"ם כו' וחי גם על בחי' א\"ק דלית מחשב' תפיס' בי' אפי' מחשב' דא\"ק מאחר שמבחי' מל' דא\"ס נעשה כת\"ר דא\"ק כידוע).\n<b>אך</b> הנה זהו ענין הג\"ע שאע\"פ שגם הוא בא בבחי' ההשתלשלו' מאי\"ן דמל' דאצי' ליש בדרך בריא' ממש, כמ\"ש ויברא ה' אלקי' ג\"ן בעדן כו' (והוא בבחי' פנימי' בינה שבמל' דאצי' כו'), אבל הנה אמרו אל תאמר זהו גן זהו עדן כו' דהעד\"ן הוא מקד\"ם מבחי' קדמונו של עולם הא\"ס ממש והוא בבחי' התענוג הפשוט ונעלם שבעצמו' אא\"ס שלפני הצמצום הראשון דמל' דא\"ס כו', אשר ע\"ז א' עין לא ראתה כו' והוא מקור חיי העוה\"ב שע\"ז א' יקימנ\"ו ונחי\"ה לפני\"ו ממש אך בכל חדש ושבת עולי' הנשמו' גם בג\"ן דעד\"ן העליון לקבל הארה אפס קציהו בלבד, וזהו יחיינ\"ו מיומיי' כו' והוא עיקר ענין הג\"ע שהג\"ן הזה מאיר בו מאור עד\"ן העליון שבעצמו' בכל שבת כו', וע\"ז א' שהנשמו' נהנין מזיו השכינה שהוא מעין ודוגמא דעוה\"ב ממש רק שהוא אפס קציהו לבד וד\"ל. והיינו אור דבחי' כת\"ר מל' דא\"ס שמתצמצם עד בחי' פנימי' בינה שבמל' דאצי' בג\"ע דבריא' לנשמו' להיות בבחי' עונג אלקי מורגש בהשגה עד שנהני\"ן ממ\"ש מזי\"ו כו' כמו בעוה\"ב שא' הנה אלקינו ז\"ה כו' ואע\"פ שנא' כי לא יראני האדם וחי, היינו עכשיו שבא ההשתלשלו'"],[1900640226,"במדה וקצבה במעוט וצמצום דעו\"ע כנ\"ל אבל כמו לע\"ל דכתי' ונגלה כבוד ה' וראו כל בשר כו' וכן א' הנה אלקינ\"ו ז\"ה לנוכ\"ח כו', הרי כולם יראו בראי' חושיי' כו' וכמו שא' מתי אבא וארא\"ה פני אלקי' וכמו לחזו\"ת בנועם ה' לחזות ממש, וכך הארת אפס קצה מזה הוא בא בגילוי אור לנשמו' בג\"ע מדי שבת וחדש שיבא כל כו' (וכדוגמא דירא' כל זכורך כו' בבהמ\"ק ובכל שבת מאיר בכל נשמ' אלקי' אור זה בהעלם גדול והוא ענין נשמ' יתירה שמעין העוה\"ב לפי שבכל שבת יש בו en.en.מיום שכולו שבת שהוא העוה\"ב כידוע).\n<b>אך</b> עדיין יש להבין דמאין יבא גילוי אור גדול כזה מבחי' עצמו' התענוג שבעדן העליון בג\"ן זה דבריאה שנגד סדר ההשתלשלו', מאחר שבא בדרך בריא' יש מאין שבודאי אינו אלא אחר בחי' הצמצום דמל' שבמל' דאצי' כנ\"ל. והנה הענין יובן בהקדים תחלה משל א' והוא כאשר אנו רואי' במהות השמחה באדם למטה שעושה בנפשו גילוי הצפון ונעלם שבתוך תוך לבבו אשר לא הי' מגלה כלל בשום אופן כלל להיותו בבחי' פנימי' והסתר גדול בפנימי' עצמות נפשו אך ע\"י השמחה שישמח ויטיב לבו באיזה דבר מה שהוא מגיע בפנימי' מהותו אז לא יעצור רוח ויגלה כל עצמותו כו', ואם חכם הוא יגלה כל פנימי' ועומק חכמתו בריבוי תוס' אור גדול לתלמידיו בשפע יתירה שלא הי' מגלה כלל זולת השמחה רק במדה הקצובה להם לבד, לפי שע\"י השמח' וטוב לבבו נתרבה ונתגבר בתוס' אור בעצם כח חכמתו שיבא כל מה שבהעלם הגנוז בכח חכמתו לידי גילוי גם ביתר מכפי הרגילו' שלו לעצמו בלימודו, והיינו ההיפוך מטבעו בכל העיתי' כשאינו שמח שלא יאיר בעצמו בתוס' וריבוי חכמ' עמוקה כזאת וכ\"ש לתלמידיו שהוא מקמץ ולא ישפיע ביתר מכפי המדה כלל, אבל בעת שמחת לבו יגלה הכל עד שמפני רוב תגבורת השפע בתוס' וריבוי כ\"כ יפול גם בחי' מותרות השפע בדיבורו הנק' נובלות חכמ' כו' כמו חבית המליאה ביותר שיפול ממנה מותרות כו' והנובלות סימן לעוצם הריבוי בתוס' ביותר כידוע וד\"ל, וכן אם איש חסד הוא ירבה ויתוסף כח רב במדת חסדו שהי' במדה לפזר כל הון ביתר מכפי המדה כו' והכל רק מצד שמח' וטוב לבב שבפנימי' עצמותו, וכן יתפאר ויתנשא ביותר מכפי המדה כו'. ונמצא מובן שיש כאן ב' דברי' והכל א' דע\"י השמח' וטוב לב נעשה תוס' וריבוי גדול בעצם המשפיע ע\"כ היא הנותנת ענין הב' והוא מה שירד en.en.האור והשפע בבחי' נובלו' ומותרו' ביותר כו'."],[1900640227,"<b>והנמשל</b> מכל זה יובן למשכיל למעלה בבחי' שמחה העליונה דהנה ודאי לפי סדרי ההשתלשלו' דאבי\"ע בא במדה קצובה משרש ומקורא דכולא מבחי' מל' דא\"ס כנ\"ל, וא\"כ ודאי יפלא איך יבא האור והשפע דפנימי' ועצמו' אא\"ס שבכתר כו' עד הנשמו' בג\"ע שהן בע\"ג וכנ\"ל ואיך יתקיימו במציאותם ככלל כנ\"ל, אך ע\"י בחי' שמחה העליונה שבפנימי' ועצמו' אא\"ס ממש הרי אז ניתוסף ונתגבר ריבוי אור ושפע ביתר מכפי המדה דהשתלשלו' דקו\"ח כו' שבא הכל בגילוי מהעלם העצמו' שהי' בבחי' הסתר העצמו' תחלה, ונק' סדכ\"ס דלית מחשב' תפיס' בי' (אפי' מחשב' דא\"ק כנ\"ל) עד שיפול גם בחי' נובלות והוא הנק' נובלות חש\"מ כו' שבא מצד עוצם הריבוי והתוס' בעצם המשפיע כנ\"ל דהכל א' והא בהא תליא, ע\"כ יורד האור בתוס' וריבוי ביתר מכפי מא' קו המדה גם באו\"כ דע\"ס דאצי' עד שמאצי' ירד עוד למטה מטה בגילוי אחר גילוי עד הנשמו' שבג\"ע דבריא' ג\"כ שגם המה נהנין שם מזי\"ו עד\"ן העליון שבעצמו' אא\"ס שבכת\"ר דמל' דא\"ס הנ\"ל וד\"ל, ומשם יורד האור העליון עוד למטה בגילוי אחר גילוי עד נשמו' שבג\"ע התחתון דיצי' ועשי' שזהו כמשל בחי' הנובלו' דחכם גדול בעת שמחתו וטוב לבו דוקא עד שגם נשמו' שבגופים למטה בכל שבת ישבעו ויתענגו על ה' מעונג דעד\"ן עילא' זה כו' וכן בכל ק\"ש שהוא בבחי' שבת שבו מעין העוה\"ב כנ\"ל),וכל זה בא מסיבת השמחה והעונג שבעצמות דוקא כנ\"ל במשל וד\"ל.\n<b>אך</b> מאין בא בחי' השמח' עליונה שבעצמות אא\"ס מאחר שאין לאבי\"ע ערוך לו כלל כנ\"ל א\"א שיוכלו לעוררו בשמח' ע\"י העלא' מ\"ן שלהם כו', אין זה רק מבחי' העלא' מ\"ן דמעשה המצות בעוה\"ז דוקא והיינו שמזה דוקא בא גילוי תוס' אור עד\"ן העליון הנ\"ל בג\"ע דבריא' בדרך נובלו' מעצמו' התענוג הפשוט שבעצמו' המאציל ובעוה\"ב יתגלה למטה כמו שהוא, וזהו ההפרש בין ג\"ע לעוה\"ב כנ\"ל וד\"ל, ודוקא משמחה של מצוה ושניהם כא' דוקא היינו המצוה בפ\"מ ושמחה של מצוה אבל שמחה שאינה של מצוה ומצוה בלא שמחה אינו מעורר למעלה שמח' עליונה הנ\"ל שבפנימי' העצמו' ממש וכמ\"ש באדה\"ר לעבד\"ה זו רמ\"ח מ\"ע ברוחניו' כנ\"ל, והעבודה צריך להיו' בשמח' דוקא וכמ\"ש עבדו ה' בשמח' וכתי' תחת אשר לא עבדת בשמח' וטוב לבב דוקא כו' כידוע לפי שלא מצד השמח' לבד יגרום תוס' וריבוי אור העצמו' למעלה כ\"כ אלא דוקא כשהשמחה היא מן המצוה"],[1900640228,"דוקא ונק' שמח' ש\"מ כו', לפי שהמצוה מצד שרשה למעלה היא בחי' כלי להכיל כל פנימי' ועצמות דאא\"ס שבהעלם כו' מאחר שהמצוה נק' פנימי' רצונו והוא פנימי' התענוג שבעצמותו ממש כו', אך ע\"י שמח' ש\"מ יצא האור הנעלם שבפנימי' ועצמו' לידי גילוי בתוס' אור רב כנ\"ל ובלא שמח' נשאר האור בהעלם העצמות ואינו בא לידי גילוי למטה באבי\"ע כלל, וזהו שעיקר ענין הג\"ע הוא ממעשה המצו' שבעוה\"ז דוקא שע\"י השמח' דוקא שהוא הגורם ריבוי תוס' האור מראש לסוף בבחי' נובלו' עכ\"פ כנ\"ל, משום דסוף מעשה דוקא הוא שעלה במחשב' הפשוט' שבעצמו' בפנימי' כת\"ר מל' דא\"ס דאנ\"י ראשון ואני אחרון הנ\"ל עד שיבא כל העלם העצמו' לגילוי עי\"ז דוקא. וז\"ש מה ר\"ב טוב\"ך אשר צפנ\"ת ליריאי\"ך שר\"ב טו\"ב הצפו\"ן בעצמו' בא בגילוי לנשמו' בג\"ע אפס קצהו כנ\"ל בבחי' נובלו' לבד ובעוה\"ב יתגלה רב טו\"ב הצפון כמו שהוא ממש למעלה ליריאי\"ך דוקא שהוא קיום המצות בשמח' כנ\"ל וד\"ל (וז\"ש בעדן עין לא ראתה en.en.עדיין בג\"ע רק יעשה למחכ\"ה לו בעוה\"ב כמ\"ש ונחי\"ה לפני\"ו ממש כנ\"ל וד\"ל).\n<b>אך</b> הנה עדיין יש להבין מהיכן יש כח בשמח' של מצוה לגרום שמחה כ\"כ בעצמו' ממש עד שיהי' מזה כל עיקר ענין גילוי תוס' אור רב טוב הצפון וגנוז בעצמות ממש כנ\"ל. דהנה ידוע בשרש רמ\"ח מ\"ע שהמה הנק' בזוהר רמ\"ח איברי' דמלכא וידוע שהאיברי' הן בחי' הכלים דאורות דע\"ס דאצי' שע\"ז א' איהו וגרמוהי חד כמו דאיה\"ו וחיוה\"י חד כו', אך אע\"פ דאיהו וגרמוהי שהן הכלים דע\"ס חד מ\"מ הן נק' כלים מגבילי' האור כו' והיינו עפ\"י מא' קו המד\"ה שמודד או\"כ כמ\"ש מי מד\"ד כו', וע\"ד הנ\"ל בסדר ההשתלשלו' דניתן שיעור ומדה מצומצם בכל שפע מעילה לעלול רק מבחי' מל' שבו כו', וא\"כ מהו היתרון מעלה במצו' שנק' רמ\"ח איברי' דמלכא שהוא בחי' כלים דז\"א כו' אחר שכבר באו במדה ושיעור דקו המדה ואיך נאמר שע\"י המצות דוקא יתוסף האור במקורא דכולא עד en.שיורד האור למטה באו\"כ דאצי' עד מל' דאצי' בג\"ע דבריאה כנ\"ל.\n<b>והנה</b> באמת יש יתרון מעלה לבחי' הכלים על האורו' (כמ\"ש במ\"א בענין בנין הכלים שקדם לבנין האורו' וראי' מיצירת הולד בבטן שקדם התהוות החומר דציור איברי' גשמיי' להתהוות הצורה הנפשיו' כמ\"ש בע\"ח וד\"ל). ויובן זה עד\"מ באיברי האדם למטה דהנה אנו רואי' שכל חומר יפסיד הצורה או יוסיף כחו"],[1900640229,"וגרעון הצורה או עליתו ותוס' כחו הכל תלוי בחומר שהוא הכלי לאור כו', דהנה חומר העין כשיקולקל יפסיד צורת הראי' הרוחני' וכשיתוקן החומר יותר יותר יוסיף כח בצורת הראי' הרוחניו', וכן החומר דמוח שכאשר הוכן יותר לקבל הצורה שהוא אור השכל יבא יתרון אור השכל ולהיפך בגרעון וקלקול החומר של המוח יפסיד ויגרע אור השכל, נמצא האור תלוי בכלי דוקא שבחסרון האבר יחסר האור ובתיקונו יתוקן, ולא עוד אלא שגידול אור השכל והמדות הפנימיי' תלוי בגידול איברי' שהרי לפי שכלו יהולל איש, שהתינוק דעתו קטן מצד קטנות המוח דוקא דהיינו כלי חומר המוח וכל שיגדל כלי חומר המוח יגדל לפי ערך אור הצורה השכלי', וכן לפי ערך גידולו בשנים יגדלו המדו' שבלב כידוע שמזה מוכרח לומר שיש שרש ומקור להחומר יותר גבוה משרש הצורה והאור עד שימשיך הצורה בתוס' (וראי' מתח\"ה שבתיקון והכנת הגוף יומשך האור שהוא הנשמה ממילא ובתוס' עילוי לפי אופן טוב הכנת החומר כו'), ועוד ראי' לזה ממה שאנו רואי' דגם במי שכלי מוחו קטן בהשגת מושכלות אם מתייגע במוחו דוקא יגיע ויבא לעומקי המושכלו' שלא הי' בערכו כלל תחלה וכה\"ג במדו' שבלב וד\"ל).\n<b>והנמשל</b> מכל זה יובן למעלה בבחי' כלים דאורות עליוני' דאצי' כמו חכמה מוחא ובינה לבא כו' דדרך כלל מוחא ולבא וכבדא הן כלים כלליי' לכללו' נר\"נ דאצי' כידוע, והרי מובן ממשל הנ\"ל שיש שרש לבחי' הכלים אע\"פ שמגבילי' האור גבוה יותר משרש האור והצורה כו' עד שמחמתם יומשך תוס' אור באורו' דאצי' כו' והיינו לפי ששרש הכלים מבחי' המקיפי' ושרש האורו' מבחי' או\"פ כו' כידוע ומבוא' במ\"א וד\"ל, וזהו שרש ענין המצות שנק' רמ\"ח איברי' דמלכא שע\"ז א' ועשיתם כו' כאילו עשאוני כו' והיינו בחי' המקיפי' שהוא שרש האיברי' שנק' כלים כנ\"ל (כידוע דרמ\"ח איברי' דז\"א נגדלי' מה\"ח המגדילי' והן ה\"ח דרמ\"ח מ\"ע, דג\"פ טפ\"ט גי' רמ\"ג ועם ה\"ח הוא רמ\"ח, אך באמת בנין הכלים בג' מיני כלים פנימי אמצעי חיצון כו' כבר נאצל קודם אך ע\"י המצות הוא שנמשך בחי' מקיפי' עליוני' דרמ\"ח איברי' כו' כמו שהקדב\"ה מניח תפילין בראש ועושה צדקה בחסד דרועא כו' וד\"ל)."],[1900640230,"<b>ולהבין</b> זה בתוס' ביאור הנה יש להקדים ענין ב' מיני ידיעה שהן בחי' מקיף ופנימי ונק' ידיעה כללי' וידיעה פרטי' ד\"ע וד\"ת והוא ענין בחי' הכלים באו\"פ ומקיף כנ\"ל. דהנה ידוע בענין ב' כתובים דסתרי אהדדי דכתי' וירא און ולא יתבונן וכתי' עיניך פקוחו' כו', שיש ידיעה בבחי' מקיף מלמעלה עד\"מ ידיעה שאדם יודע דבר שחוץ ממנו שמציירו במחשבתו שלא נכנס גוף הדבר במחשבתו רק שמציירו בדמיונו ברוחניו' ואין לו קשר עמו רק עכ\"ז נראה כאילו מחשבתו וידיעתו בדבר מקפת אותו מכל צדדיו כו' כמ\"ש בלק\"א, וזהו ידיעה שבבחי' מקיף, וידיעה זו למעלה בדוגמא יובן שזהו כמו שא' וירא און לו ולא יתבונן כו' שמקפת הדבר מבחוץ ולא שנכנס בתוך תוכו, רק בבחי' העלם היינו מה שהוא ית' יודע את כל ההשתלשלו' מראש לסוף בבחי' מקיף בהעלם כמו שא' שצופה ומביט עד סוף כל הדורו' בסקירה א' כאדם שמרגיש א\"ע מראש לרגל בבת א' כו' (והוא בחי' שם מ\"ה מלגי\"ו דוקא דאיהו ארח כל האצי' כמ\"ש במ\"א), וזהו שנק' ידיעה כללי' שבידיעת עצמו יודע את כל הנבראי' ונאצלי' כו' (וזהו בחי' מקור כל אורו' וכלים שבמחשב' א' הקדומ' כוללם יחד כמ\"ש במ\"א), וידיעה הב' היינו מה שבא בדרך פרט בכל פרטי הנמצאי' שיורד האור האלקי בגילוי בריבוי צמצומי' בכל עולם לפי ערכו בנשמו' ומלאכי' עד שמשגיח בכל הארץ דעולם העשי' כמ\"ש משמים הביט כו' השגיח על כל כו' וכן עיניך פקוחו' על כל דרכי בנ\"א וכמא' דע מה מלמעלה ממך עי\"ן רוא\"ה להשגיח על כל מעשה בנ\"א דרך פרט כמ\"ש המבין אל כל מעשיהם כו' וד\"ל, וזהו ענין ובחי' הכלים דע\"ס דאצי' שבא משם ירידת האור והשפע בהשגח' אלקי' בכל השתלשלו' דבי\"ע כנ\"ל ושרש הכלים המגבילי' שבא דרך פרט היינו בחי' המקיפי' דוקא שהוא כענין ידיעה כללי' שיודע א\"ע, ובידיעה זו יודע את הכל בבחי' מקיף כצופה ומביט כו' כנ\"ל וד\"ל, ובזה יש יתרון מעלה בבחי' הכלי\"ם בשרשם למעלה מבחי' שרש האורו' עצמן מטעם הנ\"ל באורך וד\"ל.\n<b>ומעתה</b> יש להבין שרש המצות שנק' ג\"כ כלים והן רמ\"ח איברי' דמלכא אך שהן בבחי' מקיפי' שרש הכלים כנ\"ל, דהנה ידוע דמצו\"ה היינו ממש שם הוי'"],[1900640231,"רק שאות המ\"ם וצדי\"ק שבתיבת מצו\"ה בא בחילוף אתב\"ש משם הוי' מאותיו' די\"ה דשם הוי', אבל אותיו' ו\"ה לא נתחלפו כלל ולע\"ל שיהי' גילוי שם הוי' כמ\"ש ונגלה כבוד הוי' היינו שם הוי' שבמצו\"ה שנק' מצות הוי' כו' כי יתגלה אותיו' י\"ה ולא יסתיר הלבוש דמ\"צ כו', וזהו ולא יכנף עוד מוריך כו' וד\"ל. ולהבין זה יש להקדים תחלה ענין שם הוי' באצי' שהוא בחי' פנימי' הכלים דע\"ס דאצי' כמו שם הוי' בניקוד צירי הוא בבינה בשם ס\"ג ובניקוד פת\"ח הוא בחכמ' בשם ע\"ב כו' וכן במדות חג\"ת דאצי' שם הוי' בחסד היינו פנימי' כלי אור החסד דאצי' כו' כידוע בכונו' דשם הוי' שבח\"י ברכו' דש\"ע כו', והטעם הוא כי ידוע דכל שם היינו כאשר בא האור בצרופי אותיו' המגבילי' כו' והיינו שהאור בא דרך המשכה וירידה עכ\"פ אז בא בשמו' וצירופי'. אך חיצוניו' הכלים היינו בשם אלקי\"ם ופנימי' הכלים הוא בשם הוי' כידוע דשם ע\"ב במילוי יודי\"ן הוא פנימי' כלי החכמ' כו' וכה\"ג, וגם בשם הוי' עצמו יש פנימי' וחיצוניו' והוא ההפרש בין י\"ה לו\"ה דאותיו' הללו יו\"ד ה\"א וי\"ו כו' ידוע שזהו בחי' צמצום והתפשטו' והמשכה והתפשטו', דיו\"ד הוא בחי' הצמצום וה\"א התפשטו' אורך ורוחב והיינו אותיו' י\"ה דחו\"ב ואותיו' ו\"ה המשכה בוי\"ו שהן שבלב והתפשטו' במקבל בה\"א אחרונה בדיבור. ונמצא דצמצום והתפשטות די\"ה היינו עדיין במשפיע רק שהוא לצורך ההשפעה אבל ו\"ה היינו ירידת השפע למקבל עכ\"פ וע\"כ אותיו' י\"ה הוא פנימיו' הכלי' כו' טרם שנמשך למטה למקבל, ואותיו' ו\"ה הוא הנמשך מבחי' הכלים למקבלי' כמו מבחי' כלי החכמ' דאצי' להשפיע מקור לחכמ' דבריא' עד חכמ' דעשי' כחכמת שלמה כו', וכמו חסד דאצי' שנמשך לבי\"ע עד שזן ומפרנס כו' הכל מבחי' ו\"ה שבשם הוי' דכלים דאצי' לפי שהוי\"ו הוא בחי' יריד' השפע למטה וה\"א הוא המתפשט בכלי המקבל, משא\"כ חו\"ב די\"ה הם למעלה עדיין מבחי' יריד' האור למטה כנ\"ל (וזהו הכונו' שבשם הוי' בכל ברכה כמו ברו\"ך את\"ה הו\"י' רופא חולי שהוא בניקוד סגול בבחי' ת\"ת היינו להמשיך באותיו' ו\"ה שיבא הרפוא' למטה כו' וכה\"ג). והנה המצות נק' ג\"כ כלים לאורו' עליוני' כנ\"ל ושרשן במקיף דהוי' דכלים דאצי' היינו ג\"כ ע\"ד הנ\"ל בד' אותיו' דשם הוי' דבחי' ו\"ה הוא היורד ונמשך למטה להתלבש במעשה המצוה בפ\"מ בדבר גשמי ואותיו' י\"ה הוא למעלה בהעלם ולא ירד למטה, וז\"ש הנסתרו' לה' כו' י\"ה דכל מצוה והנגלות לנו כו' בחי' ו\"ה כו', שהרי המצוה"],[1900640232,"באה בהתלבשו' בדצ\"ח הגשמיי' דנוג' דעשי' כמו מצות אתרוג ולולב דצומח גשמי שנעשה בו המצוה הרי נתלבש בגשם האתרוג מבחי' אור הכת\"ר עליון שהוא בחי' רצון העליון שלמעלה מן החכמ' כו', ולמעלה הרי הוא פנימי' ומקור דשם הוי' דכלים דע\"ס והוא בחי' מקיפי' דכת\"ר כנ\"ל ואיך אפשר שיומשך למטה במעשה המצוה שבגשמיו', מאחר שגם למעלה הוא בבחי' מקיף על שם הוי' דכלים דע\"ס וכנ\"ל דתוס' וריבוי אור גדול שבא ע\"י הכלים היינו מצד שרשם בבחי' מקיפי' והוא רצון העליון שבמצו' למעלה כידוע, ועכ\"ז כל מצוה כמו שהיא למעלה נעשה על ידה תוס' אור באצי' בשם הוי' דע\"ס כידוע, אבל איך אפשר שיאיר תוס' אור דשם הוי' שבמצות ה' למטה שבאה בגשמיו' דנוג' כו' כקלף וצמר דתפילין וטלית ואתרוג ולולב וסכך הסוכה וכה\"ג. אך הענין הוא דאותיות י\"ה שבם הוי' דמצות הוי' שלמעלה מתחלפי' בחילוף דאתב\"ש במ\"ם וצדי\"ק להלביש ולהעלים האור דיו\"ד וה\"א שהן פנימי' הכלי דמצות הוי' שלמעלה וכנ\"ל די\"ה אינו יורד למטה כו', ואז יכול לבא אור רצון העליון במצוה שבגשמיו' ונק' נסתרות לה' אלקינו בחי' חו\"ב די\"ה כו' מפני שמלובשי' ונעלמי' באותיו' אחרי' דמ' וצ' דמצו\"ה שנתחלפו במקום אותיו' י\"ה כנ\"ל וד\"ל, אבל אותיו' ו\"ה שבשם הוי' שבמצות הוי' דכלים פנימי' דאצי' א\"צ חילוף והלבשה כלל לפי שאותיו' ו\"ה היינו בחי' חיצוניו' הכלי' דע\"ס שמשם יורד האור והשפע בהתלבשו' וצמצומי' למטה מטה עד התהוו' דצ\"ח דעשי' כו' והן שרשי כל הנמצאי', ע\"כ אין בזה הסתר כלל לבחי' ו\"ה שבשם הוי' דמצוה דאצי' שנק' אורחו' הוי' באמת ולא יש שינוי מצד אותיות הללו בין אצי' לעשי' כלל וד\"ל (ועיקר הטעם הוא לפי שהנגלו' לנו ולבנינו באותיו' דו\"ה לענין מעשה נמשך בלי חילוף ולבוש דאתב\"ש כלל משום דנעוץ תחלתן בסופן דוקא כמ\"ש במ\"א וד\"ל).\n<b>ובכל</b> הנ\"ל ענין הג\"ע והעוה\"ב שהוא בא ממעשה המצו' בפ\"מ דוקא מפני שהוא בחי' כלי להכיל ריבוי תוס' אור באצי' ממקורא דכולא רק שבאו אות[יו'] די\"ה בהתלבשו' במ\"צ ולע\"ל לא יכנף כו' ויתגלה שם הוי' גם באותיו' י\"ה שבי\"ה צור עולמי' כי ביו\"ד נברא העוה\"ב כו' וע\"כ המעשה עיקר כמ\"ש היום לעשותם ולמחר לקבל שכרם ושכר מצוה בהאי עלמא ליכא כנ\"ל, דהנה העונש על העדר המעשה אינו בא רק מטעם שחסר בנפשו בחי' הכנת כלים מכלים שוני' דמצות לשכון בהם גילוי תוס' וריבוי אור דהוי' שבמצות ה' שיתגלה לע\"ל, וזהו אלה לחיי"],[1900640233,"עולם לעוה\"ב ואלה לחרפו' כו' וכן הגיהנם שקודם לג\"ע כו' וד\"ל, וזהו ענין ג\"ע העליון וג\"ע התחתון דבמצות הנעשי' בכונה ורעותא דלבא ממשיך ריבוי האור העליון בג\"ע העליון ובמעשה בלתי כונה רק לצאת י\"ח לבד מוסיף אור רק בג\"ע התחתון, לפי שכל עיקר ענין הג\"ע הוא ריבוי תוס' אור מן העצמו' שע\"י ה.. וע\"י הכונה נמשך תוס' זה בג\"ע דבריא' ששם הנשמות נהנין כו' בגילוי פנימי' האור יותר, ומ\"ד מצות א\"צ כונה כי העיקר הוא המעשה בלא כונה דהיום לעשותם לבד וכמ\"ש סוף דבר כו', הענין הוא דסוף מעשה עבמ\"ת ..en. ובאמת מאחר שעיקר ענין המצוה הוא רק תוס' הגילוי ביתר מכפי המדה דקו המדה כנ\"ל, א\"כ כל שבא בגילוי למטה כ\"כ כמו במעשה בלי כונה זהו יותר נעלה מהגילוי שהוא בפנימי', כמו בהיכל מלך פנימי' בג\"ע העליון וכמשל המלך שמתגלה בחצר בית היכלו יותר הוא בא בגילוי עצמותו מכמו שהוא בגילוי לפני שריו הקרובי' אליו בהיכלו כמ\"ש במ\"א בענין המשתה בחצר גינת ביתן וע\"פ כן בקד\"ש חזיתי\"ך הלואי כ\"ן חזיתי\"ך בקד\"ש כו' וד\"ל.\n<b>ומעתה</b> אחר כל הנ\"ל יובן כל ענין הנ\"ל בקבלת שכר על המצות שבפ\"מ דוקא ולא על הרוחניו' שלהם כו' ויתורץ הקושיא על מ\"ש דשכר מצוה בהאי עלמא ליכא ממ\"ש אם בחוקותי כו' ולמה פרט ה' דברי' בלבד דאדם אוכל פירותיהן בעוה\"ז כו'. דהנה מבואר למעלה בענין מצו\"ה בחילוף אתב\"ש בשם הוי' הוא עכשיו לבד כו' וע\"כ גזר אומר דרך כלל בכללות המצות דשכר מצוה דעוה\"ב בהאי עלמא ליכא והיינו בחי' אור הרוחניו' דאור הוי' שבמצות הוי' למעלה בתוס' אור שבאצי' שנק' אורחו' הוי' באמת כנ\"ל, אבל הברכה של המצות בגשמיות נמשך גם עכשיו לכל העולמות בכלל מריש כל דרגין שבג\"ע דבריא' עד סוף מדרגו' הע' שרי' דעשי' בכל משפחו' האדמה ובכל שפע דצ\"ח דנוג' דעשי', רק לא\"י הי' נמשך בפנימי' יותר כמו אם בחוקותי תלכו ונתתי גשמיכם דוקא בעתם בא\"י דוקא ומשם הי' נמשך בבחי' החיצוניו' לע' שרי' הסובבי' בח\"ל כידוע בענין הקרבנו', וגם עכשיו בהיות ישראל בגלות בח\"ל עיקר מעמד ומצב השפע האלקי'"],[1900640234,"לצורך העולמו' תלוי רק במצות שישראל עושין בגשמיו' דוקא אע\"פ שפיזרן בין אוה\"ע כו' וכמו שא' כשם שא\"א לעולם בלא רוחו' כך א\"א לעולם בלי ישראל וכידוע דתנאי הי' להקדב\"ה בוימ\"ב אם יקיימו ישראל כו' שנא' אם לא בריתי כו' חוקו' שמים וארץ כו' ,לפי שבמצות מעשיו' דישראל תלוי בחי' ריבוי האור הנוסף בריבוי גדול בעצמות אא\"ס להיות ישמח ה' גם במעשי\"ו להשפיע להם ביתר מכפי המדה שלא לפי מעשיהם, וע\"כ א\"א לעולם בכלל בלא מצו' דישראל אם רב או מעט כדי קיום העולמו' הרוחניי' והגשמיי' וצריך שלא יופסק שפע זו הכללית תמיד לא יחסר כו', וזהו הנק' השפעה חיצוניו' לקיום העולמו' ובדרך כללו' לכללו' העולם (וכמו בזמן בהמ\"ק בהקרבת הקרבנו' כך גם עכשיו בתפלות שנגד תמידין תיקנו הכל תלוי בכנ\"י, וזהו כל ענין השינויי' תמיד בכל ר\"ה ור\"ה בעולם בחסד או דין בכל הדברים כו'), ואמנם עכשיו כל זאת הברכה והשפע מלובש בהלבשה וצמצום האור האלקי מכמו שהוא נמשך במקורו באצי' ולמעלה מעלה (ועד\"מ מתן בסתר שישנו במציאו' רק שמכוסה כמ\"ש במ\"א), ולע\"ל יתגלה האור הזה למטה כמו למעלה היינו בלי הפרש כלל בין הרוחניו' והגשמיו' שניהם כא' יבאו למטה כמו שהוא למעלה, והוא כמו שהי' קודם חט\"א אדה\"ר עד שגם גופו קיבל ברכ\"ת ה' כנשמתו וא\"צ להתלבש בלבוש וצמצום כלל וכמו בחנוך דכתי' בי' ויתהלך חנוך כו', וכמו האבות שהן המרכבה בעובדו' דבארו' ומקלו' כמצו' העליונו' ממש ע\"כ קיבלו ברכ\"ת ה' בגשמיו' כמו שהוא למעלה ברוחניו' בלי הסתר כלל וכלל, וכמו שא' ג' הטעימן ה' מעין העוה\"ב כו' וד\"ל.\n<b>וכך</b> יש גם עכשיו במצות מיוחדו' דרך פרט שמתן שכרן בא מלמעלה למטה בלי הלבשה וצמצום כ\"כ מעין שכר העוה\"ב שיהיו נשמות בגופי' טהורי' וקדושי' ומובדלי' מכל רע וכו' ויחיו בחיי האלקי' בחיי גשמיי' כו' באור הוי' משום דמצות ה' כמו שהיא למעלה כך יהי' למטה בלי שינוי כנ\"ל וזה אינו בא לכללו' העולמות רק לנשמו' פרטיי' וע\"י מצות פרטיו' דוקא, וזהו שפרט ה' דברי' שאדם אוכל פי' שאד\"ם אד\"ם פרטי שמסוגל נשמתו לזה הוא שיקבל למטה ברכת ה' שבמצו' ה'"],[1900640235,"כמו שהוא למעלה כנ\"ל, והיינו שאוכל פירותיהן בעוה\"ז בשכר גשמי שהוא מעין השכר הרוחני דעוה\"ב (כמו שא' עולמך תראה בחייך כו' וכמ\"ש ר\"ע לר\"ט שמא קיבל ר' עולמו בהצליח לו בגשמיו' כרוחניו' וכרבינו הקדוש שהי' לו תורה וגדולה כא' ממש ושרש כולן הי' יוסף הצדיק שהי' איש מצליח בגשמיו' וה' עמ\"ו ממ\"ש היינו בכל אשר הוא עושה בגשמיו' ה' מצליח בידו כמו שהוא למעלה ממש וד\"ל), וזהו שנק' פירותיהן כפרי תבוא' הגדל ונוסף בריבוי והקרן קיים כו' כך שרש המצוה כמו שהיא למעלה ברוחניו' דהוי' דאצי' נק' קר\"ן קיימ\"ת להיו' מזה ריבוי האור העצמות תמיד ברוחניו' דעוה\"ב. אך פירו' הבא למטה הוא מעין ריבוי האור שלמעלה וזהו שאד\"ם אוכל פירותיה\"ן בעוה\"ז (שהוא מקבל השכר בגשמי שלא נחסר כלל ברוחניו' כשאר שכר המצו' בברכה גשמיו' גם עכשיו כשמקבל בהאי עלמא שאין לו שכר לעוה\"ב כמו משלם לשונאיו בשכר מצוה שעשו בעוה\"ז להאבידו בעוה\"ב כו' אבל ה' דברים הללו אוכל פירותיה\"ן בהלבש' שכר גשמי ולא נחסר כלל בקרן הרוחני שקיימ' לעוה\"ב וד\"ל). והטעם שפרט לה' דברי' אלה לבד מכל שאר המצות, הי' הסוד בזה ידוע לחכמי המשנה (ואע\"פ שיש מהן שאינן מן התור' כביקור חולים והבאת שלום כו' רק כיבוד ואב ות\"ת דאומר בפי' כבד אביך ואמך למען יאריכון ימיך וכן בת\"ת והגית בו כו' כי הוא חייך כו', וגמ\"ח בגופו כמו בביקור חולי' והלוא' המת שיזכה לחיי נצחי להיו' הקרן קיימ' בכל המצו' שעשה וכן הבאת שלום בין אדם לחבירו שגדול השלום שנק' כלי מחזיק ברכה מרוחניו' לגשמיו' שכל זה מעין דעוה\"ב לפי שיש בכל אלה חיבור לרוחניו' עם גשמיו' כו' משא\"כ בשאר מצות זולתן שאין אדם אוכל פירותיה\"ן בעוה\"ז וד\"ל).\n<b>ומעתה</b> יש להבין ענין המא' דלעיל במ\"ש וחסדי מאתך חסד דלגיו וחסד עולם הוא חסד דלבר כו'. דהנה מבואר למעלה שבחי' ריבוי ותוס' האור בעצמו' שנמשך להוסיף אור גם באצי' אינו אלא עפ\"י העלא' מ\"ן דמצות כו' הנה זהו הנק' חסד עולם חסד שהוא לעולם דאצי' ומשם נמשך גם לבי\"ע (בהלבש' גשמי' כנ\"ל) שניתוסף האור מכמו שהי' קצוב עפ\"י מא' קו המדה מראש לסוף"],[1900640236,"הכל כו', להיות ידוע שעיקר ומקור הבנין של עולם הוא בבחי' החסד כמ\"ש עולם חסד יבנה (אע\"פ שמבחי' המל' שבעליון נעש' כו' הרי א' והוכן בחס\"ד כס\"א כו' כנ\"ל), והגם שבכל עולם יש י\"ס וכל א' כלול מי' כו' כידוע, הרי אור החסד שבכל מדה הוא העיקר לענין ההמשכה והשפע מלמעלה למטה בכל עילה לעלול כמו חסד שבחכמ' עיקר הוא באור החכמ' לענין אור השפע מחכמ' למדו', וכן חסד שבכת\"ר להשפיע לחכמ' ועד\"ז ממדה למדה עד גם בחי' גבורה שהוא הצמצום והדין עיקר אורו ושפעו הוא מבחי' החסד שבגבו', וע\"כ יורד כל אור ושפע עד למטה מטה בכל עולם ועולם לפי ערכו עד המזלו' וע' שרי' שגם הם מקבלים בבחי' החסד כמ\"ש כי חסד ה' מלאה הארץ גם לרעי' כמו לטובי' שהרי זן ומפרנס לכל בחסד כו', וכל זה מצד שאור החסד כלול בכל מדה וספי' ונחלק לרבבו' אלפי' מדרגו' בי\"ס דבי\"ע עד שזן את כל העולם בחסד כו', אך כל אור החסד גם כמו שהוא במקורו הראשון בחסד שבכת\"ר לחכמ' וכה\"ג הרי הוא בא במדה ושיעור לפי מא' קו המדה כמו מי מדד בשעלו מים שהוא אור החסד כו', אך בחי' תוס' וריבוי האור דחסד עליון בא עפ\"י אופן העלא' מ\"ן דמצו' וכמ\"ש יהי חסדך עלינו כאשר יחלנו לך (וכן בע' שרי' לפי מעשיהם דוקא כמ\"ש לך א\"ד החס\"ד כי אתה תשלם לאיש כמעשהו דוקא וכמ\"ש השופט כל הארץ כו' רק שמקבלי' חסדם מפנימי' דמצו' דכנ\"י דוקא וא\"ל כבר הי' כלה קיצם כו' כנ\"ל), וזהו שנק' חסד עולם דוקא פי' חסד הבא ונמשך בתוס' אור מן המדה הראשונה רק לפי ערך מעשה העולם בהעלא' מ\"ן מלמטה למעלה כו', ואך מ\"ש כי ההרים ימושו כו' וחסדי מאתך כו' הוא חסד דלגיו שלמעלה הרבה מחסד עולם שנק' חסד דלבר כו'. והענין הוא כידוע שהוא בחי' רב חסד העליון שבעצמו' אא\"ס ממש שנק' חסד\"י ממש וכמ\"ש חסדי ה' כי לא תמנו שהוא בבחי' א\"ס ממש מפני שהוא חסד דא\"ס ממש, ע\"כ נק' חסד דלגיו ולא חסד דלבר שיורד לפי ערך העולמו' בהעלא' מ\"ן en.ע\"כ אינו נק' חסד עולם כלל אלא חסד\"י העצמי כו' וד\"ל.\n<b>והנה</b> להבין ביאור הדברי' יש להקדים תחלה בכלל ענין ההשתלשלו' דע\"ס כמו שהן כלולי' תחתון בעליון בבחי' עיבור והעלם תחלה ואח\"כ יוצאי' לגילוי"],[1900640237,"מעליון לתחתון כו' כמו עד\"מ שכל ומדות באדם שהמדו' שבלב נולדי' מן השכל בדרך עו\"ע שזהו רק ענין גילוי ההעלם, היינו שאין כל חדש בעיקר מציאותם בהתפעלו' שבלב כי כבר היו כלולי' בשכל שבמוח רק שהיו מתאחדי' שם ונחשבי' שם כטפל לגבי העיקר והיינו בבחי' עיבור והעלם גדול כעיבור הולד במעי אמו כו', דעובר ירך אמו הוא ואוכל מה שאמו אוכלת ואינו נחשב למהו' בפ\"ע כי מכוסה ונעלם הוא בבטן כגוף א' ממש כו', וכאשר אנו רואי' בעבודה שבלב בדו\"ר שכליי' שקודם שיתפעל באוי\"ר במורגש בלב כבר נתפעל באוי\"ר אלה ממש במוח הבינה בהיותו משיג ומכיר בוראו שנתפעל במוח בחדוה אלקי' או בירא' אלקי' שנק' דו\"ר שכליי' ממש רק שאינם שם במורגש ההתפעלו' כי נגררי' וטפלי' אחר התפעלו' ההשגה בעצם, ואמנם כלול מהתפעלו' אוי\"ר ממש ונקראו בשם מדות ממש מצד עצם מהותם כמו שהן בלב במהו' התפעלו' הלב אלא מצד בחי' התכללותם בהתפעלות המושג האלקי נקראו בשם שכל והשג' ג\"כ מובדל מערך התפעלו' המדו' שבלב, אך הן כלולי' שם בשכל בהעלם גדול ולא נחשבו למהו' בפ\"ע עד שאינו מורגש כלל וכלל כולד בבטן כו' כנ\"ל, וזהו שנק' בחי' מילוי דשם ס\"ג דבינה כו' (או כצורת הרגל הקצר שבה\"א ראשונה כידוע), ועד\"ז נכללו אותיו' המחשבה בלב כשמתפעל בלב שנק' הרהורי לבו עד שאין כל חדש בהרהור אותיו' מחשבה כי היו כלולי' בהבל הלב ולא הי' ניכר כו', וכן הבל הדיבור הי' כלול תחלה בהבל הלב כי הרכבה גשמיי' דאמ\"ר שבהבל קול הדיבור במורגש לזולתו הוא אותו ההבל שבלב בהרכבה דאמ\"ר רוחניי' ממש רק שהי' שם בהעלם ויצא לגילוי (כידוע שזהו ענין ז' הבלי' עילאי' וז' הבלי' תתאין מהבל הדיבור עד רום המעלו' דכמו שז' הבלי' שבמדו' שבלב נק' ז' הבלין עילאי' לגבי ז' הבלי' דדיבור שנק' זה\"ב תתאי' כך זה\"ב דמדו' נק' זה\"ב תתאי' לגבי זה\"ב דבינה וכמ\"כ גם זה\"ב דבינה לגבי חכמ' עד שזה\"ב דחכמ' נק' זה\"ב תתאי' לגבי en.en.זה\"ב דמדו' שבכת\"ר וכך עד רום המעלו' וד\"ל).\n<b>והנה</b> ע\"ד הנ\"ל בעיבור המדו' בשכל כך יש בחי' עיבור דשכל בלמעלה מן השכל שהוא הרצון והתענוג שנבדל בערך מן השכל בדרך כלל, והיינו כמו שהי' השכל כלול תחלה ברצון ותענוג הרי הי' בבחי' עיבור והעלם גדול כטפל לגבי העיקר לבלתי נחשב כלל למהו' בפ\"ע, כמו שאנו רואי' בעבודה שבלב בנקוד' הרצון שלמעלה מן הטעם לגמרי אע\"פ שכלול בזה טעם לרצון אבל הוא בהעלם מאד ויוצא לגילוי מהעלמו אח\"כ כשאו' טעם לרצון זה כו', וכה\"ג יש עוד בחי' עיבור לבחי' הרצון במקור הרצון והתענוג שהוא עצם הנפש דבחי' יחיד' שמשם יוצא כל רצון כו' שהי' כלול שם בהעלם תחלה ע\"ד הנ\"ל, וכידוע כל זה"],[1900640238,"למעלה כמו בענין והחכמ' מאין תמצא למעלה שזה בחי' עיבור דח\"ע בכת\"ר שנק' אי\"ן ויוצא מן ההעלם לגילוי כו' עד גם בחי' הכת\"ר שהוא בחי' ע\"י וא\"א (שנק' רצון ותענוג שלמעלה מן השכל וחכמ' כנ\"ל) גם הם היו בבחי' עיבור והעלם בעצמו' המאציל עד גם בבחי' התחתונה שבעצמו' א\"ס שהוא מל' דא\"ס שנעש' כת\"ר לא\"ק כו' הי' כלול בעצמו' א\"ס ממש עד שיצא לגילוי כשעלה במחשב' en.ורצונו הפשוט כו' וד\"ל.\n<b>ונמצא</b> שכל זה הוא בחי' ההשתלשלו' מן ההעלם לגילוי מראש לסוף ותחלה הי' התחתון כלול בעליון היינו הדיבור כלול במדו' ומדו' בחו\"ב וחו\"ב בכת\"ר כו' עד מל' דא\"ס בעצמו' א\"ס שנק' אנ\"י ראשו\"ן כנ\"ל. אך הנה לפ\"ז יובן שיש עלי' והתכללו' בז' מדו' מתחתון לעליון עד רום המעלות להיות שמדו' הנגלי' בהבל הדיבור כלולי' בהבל המדו' שבלב ומדו' שבלב כלולי' בשכל ונק' מדו' שבשכל שכאשר השכל עצמו כלול בעיבור בכת\"ר גם המדו' שבשכל כלולי' שם והיינו שהן כלולי' במדות שבכת\"ר ועד\"ז גם מדו' עליוני' שבכת\"ר עולין למעלה במקורם במדו' שבעצמו' המאציל עד שמדו' דמל' דא\"ס עולין ונכללי' בעצמו' המדו' דא\"ס ממש כנ\"ל וד\"ל. וזהו שרש ענין י\"ג מדה\"ר שנק' בשם מדו' גדולו' כידוע, והיינו מצד שעולין בשרש הראשון במדות דא\"ס ממש שחסד דא\"ס אין לו סוף באמת כמ\"ש ולגדולת\"ו אין חקר כו', וכך מדת הרחמי', ולהיות שגילוי ההעלם מעליון לתחתון בא במדה כנ\"ל ע\"כ בהגלו' נגלו' השרש העצמי של המדו' כמו שהן בבחי' א\"ס עצמו באור הכת\"ר שנק' ע\"י וא\"א שנחשב מסוף עולם הא\"ס כידוע, אז יאיר אור החסד ורחמי' גם במדו' שבחו\"ב עד הבל הדיבור לעולמו' בתוס' אור שלמעלה מכפי המדה הקצובה, וזהו כל עיקר ענין י\"ג מדה\"ר דא\"א וע\"י שנק' מדות סתם ע\"ש שרשם במדו' דא\"ס עצמו שאין להן שיעור למטה כמו שאין להם שיעור למעלה כו' להיות נושא עון ועובר על פשע כו' וזהו ויעבור ה' על פניו ויקרא ה' ה' שקרא והמשיך מעצמות מדותיו שכלולי' בעצמותו ממש בב' שמו' דה' ה' בע\"י וא\"א עד למטה ממש וד\"ל.\n<b>וזהו</b> וחסדי מאתך כו' חסדי ממש כו'. דהנה בחי' חסד עולם הנ\"ל הוא שבא ויורד ונמשך ממל' דא\"ס בע\"ס דאצי' עד חסד דעשי' כנ\"ל רק לפי ערך בחי' ההעלא' דמעשה התחתוני' לבד כנ\"ל, אבל ע\"י בחי' עיבור והתכללו' דמדו' שבתחתון בעליון הימנו עד מדו' שבמל' דא\"ס כמו שהן בעצמו' ממש מעורר לחסד העצמי שאין העלא' מ\"ן דמצות מגיע שם כלל, רק חפץ חסד הוא מצד עצמו"],[1900640239,"כמ\"ש ישוב ירחמינו יכבוש עונותינו לפי כי חפץ חסד הוא ולא החזיק לעד אפו, וה\"ק מיכה מי אל כמוך נושא עון כו' לא החזיק כו' כי חפץ חסד הוא ע\"כ ישוב ירחמינו כו', והוא בחי' תשובה עילא' שישוב ירחמינו מצד עצם מדת חסדו העצמי שלא ימיש לעולם ואח\"כ תתן אמת ליעקב וחסד לאברהם אשר נשבעת לאבותינו מימי קדם כו', וזהו דוקא ע\"י תשובה תתא' שמלמטה למעלה בבחי' אור חוזר צעק לבם אל ה' למעלה מבחי' כלי לאור שאין המצות מגיע לשם, כי המצות אע\"פ ששרשם מגיע בעצמות הרצון ותענוג להוסיף אור בריבוי גדול גם באצי' כנ\"ל הרי כל זה ע\"י בחי' הכנת הכלי עכ\"פ וכנ\"ל שיש כח ושרש דמקיפי' בכלים להמשיך תוס' אור כו', א\"כ אין המצו' מגיע רק במקום שיוכל בחי' הכלי להגיע והוא לבחי' המקיפי' עליוני' שרש הכלים שהוא שרש של המצות שהן פנימי' הכלי' דשם הוי' כנ\"ל, אבל במקום שאין שם בחי' כלים מפני שהוא במקום ומדרג' שלמעלה גם מבחי' מקיף כו' והוא בעצמו' הא\"ס שלמעלה מבחי' מל' דא\"ס דשם נא' שמים ושמה\"ש לא יכלכלוך כו', שגבוה מאד נעלה באין שיעור למעלה שלא ירד לצמצם עצמו בבחי' כלי' דמקיף בכלי המצות ג\"כ וכמ\"ש אם צדקת כו' (וכמ\"ש קדושי' תהיו ע\"י המצו' שקדשנו במצותיו, יכול כמוני ת\"ל כי קדוש אני קדושתי למעלה מקדושתכם כו' כמ\"ש במ\"א), אין מגיע לשם רק מה שהוא למעלה מבחי' כלי והוא העלא' מ\"ן דבע\"ת שאין בהן תו\"מ כלל (כראב\"ד שיצא' נשמתו בבכי' בלא תו\"מ כלל כידוע), שאתדל\"ע שיבא מזה הוא ג\"כ אור עצמותו שבלתי מוגבל ונמשך בהתלבשו' בכלים כלל, והוא מ\"ש כי חפץ חסד הוא בחסד ורחמי' שבעצמותו ממש שמשם שישוב ירחמינו כו' וכמ\"ש וחנותי את אשר אחון ורחמתי כו' אע\"פ שאינ\"ו הגו\"ן כבע\"ת שעשו היפך התו\"מ, לפי שאין המצו' מגיע שם כלל, וזהו מצד בחי' עליו' המדו' מתחתון לעליון בבחי' או\"ח עד שעולה במדו' שבעצמו' כנ\"ל והיינו ע\"י התשובה דצעק לבם במדו' שלמעלה מן השכל עד למעלה מן מדו' שברצון עד גם מדו' דבחי' יחידה העצמי' (כתשוב' דראב\"ד וכה\"ג) שמעורר מדו' העצמיי' דא\"ס להיו' נושא עון ועובר כו' וישוב ירחמינו כו' שלא לפי ערך מעשה התחתוני' כלל, וזהו וחסד\"י מאת\"ך חסד העצמו' ואח\"כ תתן אמת ליעקב וחסד לאברהם כו' שהן מדו' שבכת\"ר דהאבו' הן המרכבה שם שנמשך לשם ג\"כ אותו האור באמצעו' התשו' והן י\"ג מדה\"ר שבא\"א וע\"י כידוע וד\"ל. וזהו"],[1900640240,"עיקר ענין משיח דאתא לאתבא צדיקייא בתיובתא כנ\"ל (וכמא' אם ישראל עושין תשו' נגאלין וא\"ל כו') דהיינו תו\"מ דכנ\"י שנק' צדיקים שגם שמוסיפי' ריבוי אור גדול אבל במקום שבע\"ת עומדי' כו' שע\"י התשובה דוקא יגיעו לעצמו' המדו' שאין המצו' מגיעי' לשם כנ\"ל, ולזה גזרו אומר דיפה שעה א' בתשוב' ומע\"ט בעוה\"ז מכל חיי העוה\"ב דהעוה\"ב אינו רק מן המצות כנ\"ל אבל תשו' עם מע\"ט מגיע למעלה מבחי' הכלים כנ\"ל, וזהו שנא' במשיח ישכיל עבדי לברר ברורי' ע\"י תו\"מ בשלימותן והיינו ירום ונשא וגבה שהן מדו' שבע\"י ועד מדו' דמל' דא\"ס שרשם הראשון אבל ע\"י התשוב' מגיע בעצמו' ממש שזהו מא\"ד בלי גבול כלי אח\"כ תתן אמת כו' שהוא חיי העה\"ב שנשבע מימ\"י קדם וכמ\"ש ונח\"י' לפני\"ו en.ממש וד\"ל.\n<b>ובכל</b> זה יובן מ\"ש ה' יחתו מריבי\"ו כו', דהנה טעם שעל תיבת הוי' זה הוא בגרשיים שצורתו בענין זקיפה כלפי מעלה והוא ב' קוים שראשיהם זקוף ועולה למעלה כו' וגם הניגון של גרשיי' הוא ב' תנועות וקולות שהן בדרך עלי' למעלה כידוע, וזה מורה על בחי' עלי' והתכללות מלמטה למעלה דוקא וב' הקוין הן ב' עליו' זו אחר זו כו'. ולהבין זה הנה תחלה יש להבין ענין מריבי\"ו איך שייך מריבה עם הוי' דמי יעמוד לנגדו ומי יאמר לו מה תעשה כו' הרי אדון ושליט הוא על הכל וכולא קמי' כלא חשיבי כו'. אך הנה ידוע בענין ויבאו בני האלקי' להתייצב על שם הוי' שזהו בר\"ה שבחי' כח מדת הדין מתייצב לנגד מדת הרחמי' והיינו בני האלקי' שמבחי' הדין שמתייצבי' לנגד שם הוי' בחי' החסד ורחמי' לתבוע דין וכו' וע\"כ גם השטן בא בתוכם שהוא בחי' גבורו' קשות כו', ומה שבני האלקי' מתייצבי' לנגד הוי' הוא כמו מלחמה וז\"ש ה' איש מלחמה כו' וכמו במצרים בשעת קי\"ס שקטרגו המלאכי' לאמור מה נשתנו אלו מאלו וכו', אך הנה כל בחי' דין וקטרוג דבני האלקי' הוא מבחי' גבורו' דקדוש' עדיין רק שמהם מסתעפי' בחי' גבורו' קשות שנק' שט\"ן כו', וע\"ז א' יחת\"ו מריבי\"ו שהן המריבי'"],[1900640241,"ממש עם בחי' הוי' כו' ולזה א' יחתו מריבי\"ו שיפלו וישברו בהכנעה גדולה ונק' en.מיתוק הגבורו' הקשות כו'.\n<b>והנה</b> תחלה יש להבין עיקר ענין הגבורו' קשות דקליפ' ואיך שמסתעפי' מגבורו' דקדוש' שנק' בני האלקי' כו'. דהנה א' בזוהר דרישא דעשו בעטפוהי דיצחק פי' בחי' כת\"ר דקליפה דעשו שרשו בחיצוניו' דחיצוניו' דגבורו' דקדוש' דיצחק שנק' פחד יצחק כו' ונק' סוסיפתא דדהבא פסולת דפסולת דגבורו' העליונו' דקדוש' כידוע, והנה בעשו א' ועל חרב\"ך תחי\"ה שחיות שלו מן החרב שהוא גבורו' קשו' חרב לה' מלאה דם כו'. ויובן זה למעלה במה שאנו רואי' למטה בטבעי בנ\"א שיש בהן רע גמור כרציחה ממש וכחיו' הטורפין ממש והיינו כמו מי שטבעו רע לבריות (בל\"א איין שלעכטער מענש) הנה ימצא בו הרע בפועל שיפעול תמיד כל מיני רע לבריו' גם לאוהביו ובני ביתו לפי שזה חיותו בעצם כאשר ירע ויצר לזולתו ממש, כמו איש הטוב בעצם שישמח ויחיה מאשר הטיב כו' וכרוצח שיחי' מאשר המית בחרבו וכמ\"ש ועל חרב\"ך תחי\"ה ממש, וכ\"כ הגיע הדבר של רע בעומק נפשו עד שגם אם יכשלו אנשי' ויזוקו יקבל חיות בנפשו ושמח ומתענג מאד כעל כל הון, גם שאינו שונאו כלל רק מפני עצם טבעו הרע יגיל ישמח בתקלת חבירו מאד כשיבא לאיזה צרה כו', ולהיפך כאשר יתעלה חבירו באיזה עושר או כבוד והצלחת ברכה במעשה ידיו או בחיי בניו וכו' יצר לו ויעצב לבו מאד מזה עד שיחלה כו' (בל\"א ער פאר גינט ניט כו') ונק' צר עין בשל אחרי', שמובן מזה ערך עצם טבעו הרע במדה ושיעור לפי הנראה בלבו עומק ההתפעלו' בשמחה על מפלת חבירו ועומק ההתפעלו' בצער על איזה טובה שישיג חבירו כי משקל א' הוא, ויש באופן טבע רעה זו כמה מיני מדרגו' זו למעלה מזו בעומק כו' וד\"ל. ויש בחי' רע שהוא דק יותר והוא כמו שאדם מתפעל בשמעו איזה דבר עבירה על חבירו שחפץ מאד שיענישו ונעשה שליח לעשות בו דין קשה בעצמו, דאע\"פ שמלובש הדבר הרע הזה מצד היותו שונא לעושה רע מ\"מ האכזריו' שעושה בעצמו זהו מטבע הרע שבו וע\"כ יתפעל יותר בזה מזולתו ולא מצד ירא' שמים ומטעה א\"ע בזה שהרי יש יריאי' ושלימי' ממנו הרבה ואינן מתפעלי' כ\"כ לעשות עונש קשה כו'. ויש עוד בחי' רע דק גם מזה והוא מה ששכלו ולבו נוטה הכל לדין לראות ולעיין היטב רק ברעת רעהו ולחייבו בכל דבר ולא ירא' בו טוב כלל רק רע וידון אותו לחוב תמיד וע\"כ שכלו מטה הכל"],[1900640242,"להרע ולא להיטב בכל אשר יפנה וכמו חכמי' המה להרע לבד ולהיטב לא ידע כלל כו', וזהו בחי' הדינין קשי' שבפנימי' יותר והן שרש לרע שבפועל הנ\"ל וד\"ל.\n<b>והדוגמא</b> מכל זה יובן בבחי' הדינין הקשי' שבאין מלמעלה שנק' גבורו' קשו' שנק' שלוחי הדין והן הנק' מלאכי' רעי' דק\"נ שכל עיקר חיותם הוא זה שנשלחו להזיק לאדם בבני חיי ומזוני כו', דהיינו ע\"ד הנ\"ל בטבע בנ\"א רעים בגשמיו' כך ברוחניו' יש מלאכי' רעים שנק' שבט אנשי' ונגעי בנ\"א שפועלי' כל רע להזיק לאדם בעונש דין קשה, אם בפרנס' או בבני כו' ונק' רצועה לאלקא' ונק' אף וחימה וכו' כידוע והוא אשר בא מחמת רעת האדם במעשיו שנא' תייסר\"ך רעת\"ך כו', ויש בזה אלפי' ורבבו' מדרגו' זו למעלה מזו בגסו' ודקו' הרע כו', ושרשם הרע הוא השטן המקטרג כמא' עולה ומסטין יורד ומקטרג וזה כל עיקר חיותו בשרשו ובלתי זה אין לו חיו' כלל (כעלוקה שמושכת הדם כו'), ומה שעולה ומסטין זהו כמו איש רע בטבעו ששונא לרעהו מפני שעשה דבר רע ולפי שכל מגמתו רק להרע לו ע\"כ מוצא בו כל חוב לקטרג עליו כדי לענשו ע\"כ יורד ומקטרג להוציא לפועל רע כו', והדק מרע זה הוא אשר שכלו ולבו נוטה לחוב כו' הוא גבורו' ודינין קשי' העליוני' יותר ומסתעף מזה ענין נתן עיניו במקדש והחריבו לפי שיצר לו מן הטוב לישראל וישמח במפלתם כו', וזהו שיורד ומשתלשל גבורו' הקשות מעליון לתחתון מפנימי' לחיצוניו' ברבבו' מדרגו' עד שבא העונש בפ\"מ וכולם מבחי' דינין דכת\"ר דקליפ' שנק' ריש\"א דעש\"ו כו' כידוע וד\"ל.\n<b>ומעתה</b> יש להבין איך יש שייכו' לרישא דעשו לגבו' דקדוש' דיצחק כנ\"ל, והנה יש להקדים לזה ענין גבורו' ממותקו' שהוא היפך הגבורו' קשו' הנ\"ל ונק' גבו' שבחסד כידוע, בהיות שאנו רואי' באיש בטוב בטבעו בהיפך ממש שכל חיותו העצמי הוא רק להטיב ולא להרע כלל כנ\"ל ואמנם אם הוא איש קר בטבעו יכלה כח טובו וחסדו מיד (בל\"א אקאלטר מענ\"ש קאלטע בלוט), וכל שהוא איש חסד בתגבורת גדולה זהו מצד שהוא איש חם ברתיחת הדמים בכל עניניו (בל\"א איין היישער מענש זודיקע בלוטי'), הנה אז גם בעונג שלו בשפע חסדו וטובו בא ברשפי אש החמימות ביותר ע\"כ יאיר אור חסדו בתגבורת גדולה בלי הפסק כלל"],[1900640243,"ולא ינוח ולא ישקוט ויעמוד לכל מנגד השפע כו', כי יש בזה חיות רב ועצום כחו במאד עד שכל עיקר קיום החסד וסיבת עמידתו ותקפו אינו רק מצד הגבורו' רשפי אש התשוקה שבו ונק' גבורה שבחסד, כידוע דבר זה גם במדת אור האהבה שבלב שהחסד היא הכלי שבה כידוע אם היא בקרירות כמים שנמשך כו' תכלה אורה במעט זמן כי יתקרר הלב מעט מעט עד שיבוטל לגמרי, אבל כאשר כלולה מרשפי אש התלהבו' באהבה שנק' בזוהר שלהובי דרחימותא כמ\"ש רשפיה רשפי אש כו' כמו אל אישך תשוקתך וכתשוקת הזכר לנקבה תאובתא דדכורא כו' הכל מצד חום הגבורו' שבה שיש בזה חיות רב וכח עצום בלי יופסק אור האהבה לעולם וכמ\"ש עזה כמות אהבה ומים רבים לא יכבוה כו' ותגבורת אור שפעה בלי גבול כלל, וע\"כ א' בזוהר דאתערו דרחימו מבחי' הגבורו' דוקא כמ\"ש שמאל\"ו תחת כו' כנ\"ל שכל התעוררו' רוח התאוה באה מבחי' רשפי אש שבאהבה דוקא כו', וזהו שכל עיקר השפע בא מבחי' הגבורו' כידוע דש.. בצפ.. אע\"פ שזן העולם בחסד וכן עולם חסד יבנה אבל הוא בבחי' גבור' שבחסד כנ\"ל וכמו שאנו או' אתה גבור כו' ע\"כ מכלכל חיים בחסד כו' לפי שכל עיקר הגבורו' הוא התגברו' החסד כמ\"ש כי גב\"ר עלינו חסד\"ו כו' וזהו הנק' גבורו' ממותקו' שבאי' בהיפך ממש מגבורו' קשות הנ\"ל שעיקרן רק רע ולא טוב כלל כנ\"ל וד\"ל.\n<b>והנה</b> בזה יובן ענין המקלות שפיצל יעקב כו' להיות שיש עוד מעלה בגבורו' שבחסד הנ\"ל והוא כנ\"ל בענין שמאלו תחת לראשי כו' שמאל\"ו דוקא, שמשם דוקא יש כח לעורר את האהבה והתשוקה במקבל שיחשוק ויתאוה תאוה להתייחד כו' כמו תאובתא דדכורא לגבי נוק', היינו מבחי' הגבורו' רשפי אש חום הטבעי שבאהבתו לנוק' אז עי\"ז דוקא יפעול רושם התעוררו' אהבה ותשוקה בנוק' להיות אל אישה תשוקתה כו'. ויובן כזה בכנ\"י שמה שמתעורר רוח התשובה בתשוקה שבלב לה' אחד לפרקים ועיתי' ידועים היינו כאשר יערה עלינו רוח ממרום ברוח המעורר אהבה ותשוקה בלב המקבל, והיינו כמו שא' בכל חצו' לילה"],[1900640244,"שאג ישאג כו' והיינו רוח האהבה עליונה דמשפיע שנמשך מבחי' הגבורו' שבחסד עליון כו' ומזה יבא רוח התעוררו' בכל נשמה דבריא' ויצי' ועשי' לעלות למעלה ברשפי אש התשוקה מבי\"ע לאצי' ואע\"פ שלא הי' זה בכח ערכם ליפשט מגדר הגבול והצמצום שלהם בהשג' ומדו' אוי\"ר שלהם, וזהו שפיצל המקלו' במחשוף הלבן כו' שכלול מב' גוונין אדום ולבן בחי' החסד שכלול מגבורו' דוקא כדי לחמם הצאן שהן הנשמו' שיתעוררו לעלות ולהתייחד ולהוליד כו', שבלתי חום זה אין להם התשוקה ולא יעלו למעלה כלל והיינו כמו שמבלתי חום התשוקה במשפיע למקבל אינו בא לכלל יחוד (ותולדה דכל חום מוליד שאם אינו מורה כחץ אינו מוליד כו'), כך בלתי חום התשוקה במקבל לא יהי' העלא' מ\"ן כלל וכתי' אשה כי תזריע כו' וד\"ל.\n<b>(אך</b> הנה עדיין יש להבין מאחר שגבורו' דחסד שנק' גבורו' ממותקו' נבדל ונעלה בהיפוך גמור מבחי' גבורו' דרע דק\"נ שנק' גבו' קשות א\"כ איך א' שמבחי' גבו' דקדוש' דיצחק נמשך לרישא דעשו בחי' גבו' קשו' הנ\"ל. הענין הוא כי הכל בא מסיבה א' והוא בחי' חום הטבעי שברתיחת הדמי', אך שכלול מדבר והיפוכו והא בהא תליא דחום הבא באהבה וחסד הרי הוא תכלית שפע גבורת החסד וחיו' רב וכח עצום שבו והן לעורר יחוד ותולדה כנ\"ל והוא עצמו כשבא לכלל כעס ברתיחת חום גדול ירצח וכו', או כמו בשאר תאוה רעה כמעשה בהמה כו' (ודוגמא לזה הוא היין שהטוב שבחום שבו יעורר רב חסד וטוב ביותר מכפי המדה כידוע והרע שבחום זה יעורר רציח' כרבה דשחטי' לר\"ז כו' (וזהו אשכול של ענב\"י' סח\"ט' לו כידוע) (וכן בחום התאוה לזיוג דדכר ונוק' זכו שכינה ביניהן כו' להוליד טוב וקדוש, ואם אש התאוה בוער בהם כבהמה בלי קדושה וכונה לטוב כלל יולידו ולד רע כו', ועיקר הדמיון בזה הוא ענין כעס של ת\"ח שנק' חוי\"א דרבנ\"ן כמ\"ש במ\"א בענין נחש הנחושת כו' דבחי' קטנו' דנח\"ש זה הוא גבו' קשו' לגמרי רק שהוא מלובש בבחי' הקדוש' להיותו מאד בחרון על העובר רצון ה' וכונתו לש\"ש ממש כנ\"ל עד שפועל בקללתו מאד, אך שרשו מגבו' דקדושה שבחסד דוקא להיות שאנו רואי' שכל מי שעבודתו בקדש בתפלה בהתלהבו' אהבה דרשפי אש יותר הרי אז יותר יכעס על העושה עבירה וכמו משלהובי' דרחימותא דוקא יבא יותר הכעס על המונע ביותר כו', או כמו כשמכה לבנו"],[1900640245,"שהדין קשה הזה מסתעף מהרשפי אש פנימי שבאהבתו אליו ע\"כ יכהו כו', ומכל זה יובן הדמיון לגבו' קשו' שמסתעף מגבו' דחסד דוקא שנק' גבורו' ממותקו' en.כנ\"ל משום דהכל א' וד\"ל).\n<b>ובכל</b> הנ\"ל יובן מ\"ש ה' יחתו מריבי\"ו ונקוד טעם גרשיים על הוי' כנ\"ל. דהנה מבואר למעלה בענין ויבאו בני האלקי' להתייצב כו' דשם הוי' הוא כולו חסד ורחמים כו' ובני האלקי' הוא בחי' גבו' דקדוש' לעמוד לנגד מדת החסד דהוי' כו', אך מפני מה מתעוררי' בני האלקי' למדה\"ד הרי זה בא מהעלא' כחות הדינין הקשי' של המקטרגי' רעי' כנ\"ל שהן המעוררי' לבחי' הגבורו' עליונו' דקו השמאל משום שיש להם הסתעפו' ואחיזה שם כענין הנ\"ל ברישא דעשו בעטפוהי דיצחק כו' עד שגם בחי' גבו' דקדוש' מעוררי' את הדין כענין מה נשתנו אלו מאלו בשעת קי\"ס כנ\"ל. וזהו פי' מריבי\"ו פועל יוצא שפועלי' וגורמי' מריבה עליונ\"ה דקו השמאל בקו הימין כו' וכתיב ה' איש מלחמה וכמארז\"ל בים נדמה להם כבחור עושה מלחמה וכמ\"ש תפארת בחורים כחם ובמ\"ת נדמה להם כזקן כו', הענין הוא שבמלחמה זאת שיגבר כח החסד על הדין צריך להיות ע\"י שיומשך בחי' עוז וכח עצום בחסד שהוא מבחי' הגבו' שבחסד הנ\"ל כמו ענין שלהובי דרחימותא וכמ\"ש כי גב\"ר עלינו חסדו כו', וזהו עיקר הישועה שבימין כמ\"ש הושיע לו ימינו לגבור על כח הדין שבשמאל כידוע והיינו דוקא ע\"י בחי' עליי' והגבהה דמדת החסד שעולה במקור הראשון שלמעלה ממקור תולדו' הקוין דימין ושמאל והוא במדו' הגדולי' דפנימי' הכתר שבבחי' פנימי' חכמ' כנ\"ל בענין חסד\"י כו', והוא מה שנמשך בשינוי הרצון מדין לחסד כענין יהי רצון מלפניך כו' שהן י\"ג מדה\"ר כו', וזהו ענין עלי' הא' בטעם הגרשיי\"ם שבהוי' זה שזהו ענין עלי' דחסד דז\"א ששרשו במוחין דאו\"א להעלותו למעלה בפנימי' הכתר דג\"ר ע\"י כו', ששם אין מקום כלל לשרש דשרש אחיז' לדין דגבורו' קשות מפני שכולו טוב ורחמי' פשוטי' כנ\"ל כמ\"ש א\"ך טו\"ב כו', ועלי' הב' הוא בקו השני דגרשיי' זה היינו מבחי' פנימי' הכת\"ר לעצמו' אא\"ס שבמל' דא\"ס שנק' חסד\"י ממש, שהוא בחי' העלם אחר העלם הראשון ומשם מאיר שרש י\"ג מדה\"ר שבכת\"ר כו' מלמעלה למטה עד שיחת\"ו מריבי\"ו שהן כחו' הדינין קשין שלמטה ויכנעו לבלתי יתעורר עוד שום קטרוג גם למטה כלל לפי שנכנעו בתכלית להיות גם הקטיגור סניגור כו' (וכמשי\"ת ב\"ה) וזהו כללו' ענין הב' קוין דגרשיי' זה וד\"ל."],[1900640246,"<b>ולהבין</b> ביאור זה בדרך פרט הנה יש להקדים תחלה ביאור ענין מה שאנו או' בעל הניסי' דחנוכה ואתה ברחמיך הרבי' עמדת להם בעת צרתם רבת את ריבם דנת את דינם כו' דלכאורה יפלא מהו זה שאו' עמדת דוקא, אך הענין הוא משום דכתי' הנה ה' עומד לריב עמים דמשמע דכל ריב הוא בעמידה דוקא ע\"כ גם כאן א' עמדת להם כו' רבת כו', וכן ומלך גיבור לריב ריבם כו' שהוא ית' רב את ריבנו וכמו שאנו מבקשי' בש\"ע דראה בענינו וריבה את ריבנו כו'. דהנה ארז\"ל ג\"ש הראשונו' יושב ועוסק בתו' ג\"ש שניו' יושב ודן את כל העולם כו' עד\"מ מלך בישבו על כסא המשפט לדון אנשי מדינתו הרי ראשו נשפל בישיבתו ורגליו מוגבהין ובעמידה הרי הוא להיפך שראשו הגבה למעלה בזקיפת הראש והרגלי' עומדי' בארץ בהשפלה יותר מבישיבה (וכאדם שעומד לריב שנזקף מישיבתו ויעמוד על רגליו דוקא וראשו זקוף כו'). ויובן זה עד\"מ באדם שמדותיו חו\"ג הכל נמשך מן השכל שבראש כידוע וכאשר יצטרך לדון איזה דבר שבין אדם לחבירו ירד אור השכל במדותיו שבלב אם לזכות או לחוב וה\"ז שפלו' וירידה לעצם השכל שבמוח כשלומדו לעצמו. כך עד\"מ ג\"ש יושב ועוסק בתו' לעצמו ואח\"כ יורד ונמשך במדו' עליונו' דאצי' לדון העולמו' כמ\"ש וישב ה' מלך לעולם כו' וכן ה' למבול ישב וכהנ\"ל כמו ישיבת המלך על הכסא שירד אור חכמתו במדותיו ע\"כ נק' כפיפה שכופף קומתו בישיבתו אך רגליו מוגבהין, הענין הוא כידוע דהרגלי' הוא בחי' הילוך אור החסד ושפע למקבלי' בג' עולמו' כמ\"ש הארץ הדום רגלי כו' (והוא בחי' נה\"י דז\"א שזהו שא' יושב וזן את כל כו'), ובשעה שדן במדו' שבלב עפ\"י הורא' השכל בחי' הרגלי' שהן נה\"י בהגבהה לבלתי ירדו למטה עדיין עד ג\"ש האחרונו' יושב וזן כו' שנשפלי' למטה לעשו' החסד בפ\"מ כו' עד\"מ מלך במשפט אז ירומם בעצמו לבלתי ישפיע עדיין כו' וכמ\"ש ויגבה ה' צבאו' במשפט כו' וד\"ל. אך הנה בעמידה נזקף הראש שהוא בחי' המוחי' שבראש שעולין לבחי' עצמותו בלתי יריד' והשפלה לדון דבר מה כו', ועוד יש יתרון מעלה בעמידה לריב יותר גם מלימוד החכמ' לעצמו בשכל העצמי שלו שלמעלה מישיב' למשפט שהרי גם בישיבתו בלימודו הוא קם מישיבתו לדון ולריב עם"],[1900640247,"מנגדו שזה מורה הגבהה יתירה על עצם כח שכלו לעצמו מפני שצריך לנצח למנגדו בריב שאז יעמוד על רגליו להרים ראשו, והענין הוא כי לנצח למנגד צריך להגביה עצמו ביתר מכפי כח חכמתו והוא בעצמו' כחו שלמעלה ממקור en.השכל שבראש כו' ואז יכנע המנגד כמו קומה ה' ויפוצו אויביך וינוסו כו'.\n<b>וביאור</b> הדבר הנה תחלה יש להבין סיבת העמידה למעלה שהוא בבחי' רגל דוקא שמזה ממילא בא הזקיפה בראש כו' דהנה נשמו' ישראל נק' ברא כרעא דאבוה כי שרש מקור חוצבם למעלה במוח האב כבן שנולד מטפה שבמוח האב שהוא בדומה לעצמותו ממש דכח המוליד בדומה לו ממש וכמ\"ש כי אתה אבינ\"ו ממש, וכל א' מישראל או' אבינ\"ו כו' ובהיותם למטה בבחי' תולדה כמ\"ש בנים אתם לה' כו' בני בכורי ישראל הרי הן בבחי' רגל כברא שהוא כרעא דאבוה כו', וע\"כ כאשר ישראל עוסק בתו' למטה גורם בחי' עמידה ברגל למעלה כבי', כי ידוע דג' קשרין הן ישראל מתקשראן באוריי' ואוריי' בקודב\"ה פי' ס\"ר נש\"י בשרשם שבמוח האב קשורי' בס\"ר אותיו' התו' שמחכמתו העצמי' נפקת דאוריי' מתקשרא בקודב\"ה ממש כו', וע\"כ כאשר נשמת ישראל עוסק בתו' למטה גם שהוא בבחי' רגל לבד מעוררי' לבחי' חכמ' העצמי' שנק' חכמ' בראש וזהו כענין עמידה ברגל שנזקף הראש ממילא, משא\"כ בלי עסק התו' למטה הרי יורד אור ח\"ע דתו' במדו' לדון העולם בבחי' יריד' והשפלה ויכול להיות ריבוי הקטרוגי' להמשיך מדה\"ד כו', וע\"כ א' על מה אבדה הארץ על עזבם תורת\"י כו' שבעון ביטול תו' יחרב הארץ כי שרש התו' למעלה בפנימי' ועצמו' חכמתו ית' שיכול לגבור כח החסד על הדין כמ\"ש ה' עוז לעמו יתן ואין עוז אלא תו' כו', וכך הוא הענין ע\"י מעשה המצות בפ\"מ דוקא שנק' ג\"כ הילוך ברגל כמ\"ש אחרי ה' תלכו"],[1900640248,"ונק' דרכי החיים כו' ובזה דוקא מעוררי' למעלה בחי' כח רגל שהוא בחי' נה\"י כאילו הקדב\"ה עומד על רגליו כו', ומשום דסוף מעשה עלה במ\"ת ה\"ז עלי' והגבהה בבחי' עמידה שהוא זקיפת הראש למעלה שזהו כח עצמו' חכמתו שבתור' שקדמה לעולם כו' וד\"ל, וכמו קומה ה' כו' לפי שנסיעת הארון והלוחו' הי' בדרך הילוך ברגל במסעות בנ\"י כמ\"ש ויהי בנסוע הארון ויאמר משה קומה הוי' בבחי' זקיפה בראש ואז יפוצו אויבך ממילא לפי שמתבטלי' כל המקטרגי' הרעי' שנק' מריבי\"ו ויחתו וינוסו מפניו וכמ\"ש יקום אלקי' יפוצו אויבי\"ו כו', להיו' שיש בקימה זו בחי' ההתנשאו' יתירה בעצמותו ממש וכמ\"ש ואתה מרום כו' כי הנה אויבך יאבדו יתפרדו כל פועלי און כו' אין מרום אלא תור' ומצו' משום דשרש התו\"מ בעצמותו ממש משום דנעוץ תחלתן בסופן וסופן בתחלתן, וכמו שאנו רואי' שעיקר קיום והעמדת הראש הוא על הרגלי' דוקא וכאשר הכח עמידה חזק ברגל בזה דוקא יהי' מעמד ומצב הגוף עם הראש כו' (אך כשאין כח ברגל לעמוד לא יועיל תוקף המוח והלב כו'). וזהו ענין יתרון מעלה שבעמידה לריב עם המנגד שהוא גבורת כח העמידה ברגל דוקא שאז נזקף הראש ביתר מכפי כח החכמ' שבו להיות שצריך לנצח ולהפיל אויבו כו' שאז מעורר כל כחו העצמי. וז\"ש ועתה יגדל נא כח אד' כו' שהן י\"ג מדה\"ר שלמעלה גם ממשפט התו' למחול ולסלוח לעוברי רצונו להיו' נושא עון כו', גם שעפ\"י תור' אין יסורי' בלא עון כו' וי\"ג מדה\"ר הוא לעשו' שינוי הרצון שעפ\"י תור' מדין לחסד כמו יהי רצון מלפניך שיכבשו רחמיך את כעס\"ך כו' ואין זה רק מבחי' זקיפ' בעצמו' אא\"ס שלמעלה גם מח\"ע דתו'. והיינו ענין ב' עליו' הנ\"ל א' עליי' במדו' שבפנימי' הכתר שבפנימי' חכמ' שבתו' כנ\"ל ועלי' הב' הוא בעצמו' אא\"ס שבמל' דא\"ס שנק' חסד\"י כו' שמשם שרש י\"ג מדה\"ר למטה להכניע המקטרגי' ולהכניעם בתכלית כמ\"ש יחתו מריבי\"ו וכמו קומה ה' ויפוצו אויבך כו' כנ\"ל וד\"ל.\nוזהו ואתה ברחמיך הרבים עמד\"ת להם"],[1900640249,"בעת צרתם רבת את ריבם כו' בעת צרתם דוקא, דהנה בימי מתתי' חשמונאי ובניו עמדה מל' יון להשכיחם תורתך ולהעבירם חוקי רצונך לבד והם עמדו במס\"נ על התו\"מ ע\"כ עמד\"ת להם בעת צרתם ורבת את ריבם כו', דהגם שהיו ראוי' עפ\"י מדה\"ד להשכיחם תו\"מ מפני חטאם שגרם קטרוגי' גדולי' ולא היו יכולי' לעמוד בזכותם לנגד מדה\"ד, אבל רבת בעצמו את ריבם כו' והוא בבחי' עמידה וזקיפה בראש שלמעלה מן המשפט שעפ\"י החכמ' והוא ברחמיך הרבים דוקא, וזה נתעורר למעלה מב' דברי' א' ממס\"נ שלהם על התו\"מ והב' מחמת התגברו' החושך דקליפ' יון עד שטמאו כל השמני' שבהיכל כו' להחשיך האור דחכמ' דתו' וביקשו להעבירם על חוקי רצונך, אז נתעורר ר\"ר העליוני' שבעצמות ממש דהיינו כרחם אב על בנים בצר להם שיעמוד לעוזרם ולהצילם כמשל אב שרואה בצרת בנו מן האויב יעמוד על רגליו ויעורר בכל כחו העצמי להושיעו ולהצילו מיד אויבו הקם עליו כו', וזהו עמד\"ת להם בעת צרתם דוקא בבחי' עמידה ברגל שהוא זקיפה בכל כחו בר\"ר העצמיי' שלמעלה גם ממדה\"ד שעפ\"י תו' כו' כנ\"ל, והוא בעת צרתם דוקא שאז מתעוררי' בתשובה שלימה כמו בצר לך ומצאוך כו' ושבת עד ה' בכל לבבך כו', והתשובה ג\"כ גורמת למעלה בחי' עמידה ברגל לעמוד לריב להכניע כל מקטרג ואויב כו' משום דבע\"ת משכי' לי' לקודב\"ה בחילא יתיר כו', כי צעק לבם אל ה' במר נפש ביותר עד שיעוררו אותו לעמוד מכסאו על רגליו לעזור להם כמשל איש מר נפש שצועק אל המלך מעוצם צערו שאז יפתח לו המלך הפתח בעצמו גם שהוא סגור בהיכלו יושב על כסאו יעמוד מכסאו על רגליו לפתוח לו, וכמ\"ש פותח שער לדופקי בתשוב' כו' וד\"ל. ונמצא שב' דברי' גורמי' בחי' העמידה למעלה לריב ריבנו כו' א' העסק בתו\"מ שנק' הילוך ברגל, והב' התשובה במר נפש שלמעלה מן הדעת כו' דמשכי' לי' בחיל\"א יתי\"ר לפתוח שערי ר\"ר כו' בבחי' עמידה ברגל דוקא וכמו עתה יגדל נא כח כו' כח עצמותו שלמעלה מן החכמ' שבראש כנ\"ל, וזהו עיקר ענין הגאולה כמו שאנו או' בש\"ע ראה נא בענינו וריבה ריבנו וגאלינו גאולה שלימה כו', משום דהא בהא תליא דאם ישראל עושי' תשוב' נגאלין גאולה שלימ' בימו' המשיח דכאשר ישראל עניי' בתו\"מ והמקטרגי' רבו למעלה ולמטה מבקשי' ריבה אתה את ריבנו בר\"ר שלמעלה ממשפט התו' כו' כנ\"ל ואז וגאלינו גאולה שלימ' נצחי' בל תמוט לנצח והוא בזמן משיח דכתי' ה' ימלוך לע\"ו, וזהו דמלכא משיחא אתא לאתבא צדקיי' בתיובתא שע\"י התשוב' יעלו לבחי' עצמו' אא\"ס שלמעלה מתו\"מ דצ\"ג כו' כנ\"ל שלא יוכל להיו' עוד קטרוג לפי שגם הקטיגור יהופך לסניגור, וזהו ה' יחת\"ו מריבי\"ו יחת\"ו לעתיד וכמו שמסיים ויתן"],[1900640250,"עוז למלכו כו', וגם עכשיו בכל יו\"כ שמרבה לסלוח בי\"ג מדה\"ר כמ\"ש ויעבור ה' על פניו כו' וכן בכל עת צרה ליעקב יושיעם בר\"ר כמ\"ש עמד\"ת להם בעת צרת\"ם en.דוקא וד\"ל.\n<b>אך</b> הנה עדיין יש להבין במ\"ש ה' יחת\"ו מריבי\"ו דמשמע שיחתו וישברו באין כח לעמוד לקטרג אבל לא שנהפך הקטיגור לסניגור רק כמו קומה ה' ויפוצו וינוסו כו' או כמו יאבדו ויתפרדו כו', ובאמת זהו יותר מעלה כאשר האויב נהפך לאוהב להיו' מלמד זכות יותר משיהי' לו מפלה ואבדון כידוע בענין ואני אר\"א' בשונא\"י שאין נקמה גדולה מזו באויב ושונא כאשר יהפך לסניגור כו', וכמו שאנו מוצאי' בבלעם שהוכרח להיו' אוהב לברך את ישראל עפ\"י ציווי ה' ונתקיים ברכתו והרי נהפך הקללה שלו לברכה וכמ\"ש ולא אבה ה' לשמוע אל בלעם ויהפוך הקללה דבלעם לברכה, שזה ברכה מרובה יותר על עצם הברכה כידוע בענין זדונו' שנעשו כזכיו' כי\"א ארורי' שנהפך לברכה כו', שזהו כסם דמות שנהפך לסם חיים שע\"ז א' טוב מאד זה מ\"ה כו' (שלזה הטעם הקטרת תעצר המגפה וכעובדא דר' אחא בכפר טרשא וכמ\"ש במ\"א), וכך ע\"י התשו' ביו\"כ שנהפך הרע עצמו לטוב זדונו' נעשו זכיו' הרי ניתוסף הברכה מן הקללה דרע הרבה יותר כו' וד\"ל.\n<b>ואמנם</b> באמת הנה זהו שמסיים בסוף ויתן עוז למלכו כו' אך תחלה א' ה' יחתו מריביו שיכנעו וישברו ע\"י בחי' ב' עליו' דגרשיי' שעל תיבת הוי' זה. ויש להקדים תחלה בענין ב' עליו' הללו שאחר העליו' הרי יש בחי' ירידו' ממקום שעלה שם והיינו ג\"כ ב' ירידו' זו אחר זו כמו שהי' תחלה ב' עליו' זו למעלה מזו כנ\"ל. וביאור הדברי' הנה יש להבין במ\"ש בי\"ג מדה\"ר ויעבור ה' על פניו ויקרא ה' ה' כו' מהו ויעבור תחלה ואח\"כ ויקרא ה' ה' כו', וגם מ\"ש וימהר משה ויקוד ארצה וישתחו מהו ענין השתחוא' זו דמשה במהירות כו' בהיות שבאמת יש"],[1900640251,"להבין בענין אור חסד העצמו' ממש שא' וחסד\"י כו' איך יוכלו המקבלי' לקבל אורו כי ודאי גם באצי' ולמעלה לא יכילוהו להיותו בבחי' א\"ס עצמו ממש כו' (וראי' לזה מבחי' חפץ חסד שבעצמו' קודם ההשתלשלו' שהוצרך לצמצם האור הגדול דחסד זה בצמצום והעלם העצמו' כדי שיוכל להיו' בחי' הקו\"ח מקור ההשתלשלו' דאבי\"ע כו'). אך הנה זהו שא' ויעבור ה' על פניו כו' פי' העברה זו היינו בחי' העלי' שהוא הצמצום וההעלם אחר העלם בעצמו' דוקא כנ\"ל בב' קוין דגרשי\"י' כדי שיומשך אח\"כ בירידה אחר ירידה, וזהו ויקר\"א כו' להיות מתקבל אור החסד הגדול הזה גם למקבלי' באבי\"ע בכל עולם לפי ערכו עד עוה\"ז השפל en.שגם שם נמשך י\"ג מדה\"ר להיות נושא עון בפ\"מ בכל פעם שאו' י\"ג מדה\"ר כו'.\n<b>וביאור</b> הדברי' הנה באמת גם אם הי' מאיר מחסדו הגדול להיו' נמשך י\"ג מדה\"ר הי' כלי המקבל מתבטל ממציאותו לגמרי או שהי' עובר עליו בבחי' מקיף בהעלם ולא הי' האור נכנס תוך תוכו כו' ולא הי' פועל לענין מעשה כלום לסלוח ולמחול לעבור ולבטל כל דין וקטרוג שבפ\"מ רק בבחי' מקיף הי' עובר כו' והוא שהי' נשאר האור למעלה בלבד (וגם בבחי' מקיף לא ירד למטה שאם הי' יורד עכ\"פ בבחי' מקיף הרי הי' בבחי' שומר עכ\"פ כענין ופרוס עלינו סוכת שלומך ובצ\"ל כנפי\"ך כו' כמ\"ש כנשר יעיר קינו על גוזלי\"ו ירח\"ף דאימא רביעא על בנין לשומרם מכל צרה כו'), וזהו וימהר משה ויקוד ארצה כו' מהירות זו הי' להמשיך כח החסד דא\"ס מלמעלה מעלה שעלה לשם כמ\"ש ויעבור ה' על פניו כו' שהן ב' עליו' הנ\"ל להוריד ולהמשיך למטה מטה דוקא והן י\"ג מדה\"ר שנמשכי' עד למטה מטה עד עוה\"ז לסלוח העון שבפ\"מ לנפש החוטא' כו', וזהו רק מכח ההשתחווא' דמשה כשמיהר בהשתחווא' למהר בחי' הירידה דאל רחום למטה דבחי' השתחוא' על פניו ארצה הרי זהו כמו ענין נפילת אפים ממש שהוא בחי' היריד' למטה בתכלית כידוע, והיינו שהוריד משרש הי\"ג מדה\"ר שעלה למעלה בעצמו' ממש שיומשך בבחי' מדו' דהוי' דז\"א דאצי' ומשם ירדו בבי\"ע תמיד בכל עת שיעוררו באמרם ה' ה' אל רחום כו' ומפני שכמו שהן בעצמו' א\"ס לא יכלו לקבל ע\"כ הי' עוצם עבודתו בהשתחוא' זו שירדו י\"ג מדה\"ר למטה שיוכלו המקבלי' לקבל להיו' נושא עון בפ\"מ וד\"ל.\n<b>ותחלה</b> יש להבין ענין ויעבור ה' שהוא ב' עליו' הנ\"ל, דהנה פי' על פני\"ו ל' רבים כי יש אנפי רברבי ואנפי זוטרי כידוע והיינו בחי' ז\"א ובחי' א\"א וע\"י דנק' אדם קדמא' כו' וכמ\"ש מ\"ה שמו כו', עד\"מ אדם הגדול בדעת כזקן שקנה חכמ' מדותיו בגדלו' הדעת ונק' פנים ארוכי' שהפני' מורה על הפנימי'"],[1900640252,"שבמוחי' דחב\"ד כו', וכתי' חכמת אדם תאיר פניו כר\"א שמצא תוספ' חדשה וצהבו פניו שהוא בא מחידוש כח המשכיל כל שכל שנק' פנימי' ח\"ס כו' והמוחי' דחו\"ב יאירו בפני' ממש והן בחי' תרין תפוחי', וכמו במ\"ת שנדמה להם כזקן כו' בהדרת אור פנים העליוני' דבחי' א\"א כמ\"ש באור פניך נתת לנו כו' וכן א' יאר ה' פני\"ו אליך פני\"ו העליוני' שנק' אנפי רברב\"י כו' והוא שרש הי\"ג מדה\"ר כידוע (ויש פני' עליוני' מזה שמשם מקור ושרש להארת פני' די\"ג מדה\"ר דא\"א והוא מ\"ש ישא ה' פני\"ו כו' והיינו בבחי' א\"ק כו'), ובחי' אנפי זוטרי הוא במוחי' דחו\"ב שבמדות עליונו' דז\"א כו' וז\"ש כתפארת אדם כו' תפארת בחורי' כחם כו', וכאשר א' ויעבור ה' על פני\"ו היינו שעלה ועבר ודילג למעלה מכל בחי' פני' העליוני' דאנפי זוטרי ואנפי רברבי דא\"א וא\"ק כו' עד בחי' עצמותו ממש שלמעלה מבחי' אד\"ם כמ\"ש כי לא אד\"ם הוא כו' (וכידוע דגם א\"ק נק' אד\"ם דבריא' בכללות), והיינו ענין ב' עליו' דגרשי\"י' הנ\"ל ואח\"כ ויקרא ה' ה' כו' פי' אחרי ב' העליו' זו למעלה מזו הנה ממקום שעלה לשם משם ירד וכמו שעלה בב' עליו' זו למעלה מזו כך ירד ב' ירידו' זו למטה מזו. והענין הוא כי ב' הויו' הללו א' הוי' דחכמה שבכת\"ר בדרך כלל שנק' אנפי רברבי כנ\"ל והב' הוי' שבמדו' דאו\"א שמלובש בז\"א ולשניהם עבר ודילג בעליית\"ו למעלה בעצמו', ואחרי העלי' צריך לירד באותן ב' מדרגו' דה' ה' ביריד' אחר יריד', ירידה א' מעצמו' אא\"ס לבחי' הוי' דפנימי' ח\"ס דא\"א וע\"י (או לחכמ' דא\"ק כו') וירידה הב' מפנימי' ח\"ס דא\"א לחכמה ובינה דז\"א שנק' אנפי זוטרי כו' דוקא כדי שמשם יוכל לבא האור גם לכל עולם לפי ערכו עד למטה ממש כנ\"ל וד\"ל. וזהו ה' ה' פסיק טעמא בגוייהו לפי שאין ערוך לה' שבז\"א לה' דח\"ס ועכ\"ז דילג בירידתו מן העצמות כמו שדילג מלמטה למעלה בעלייתו עד\"מ הדולג ועולה בסולם בשליבות ומדרגות ירידתו ג\"כ באותן en.מדרגו' וד\"ל.\n<b>וכל</b> זה עדיין לא הי' נמשך בגילוי למטה בפ\"מ כ\"א ע\"י השתחווא' דמשה שנפל על פניו ארצה כנ\"ל משום דשרש נשמת משה מבחי' חכמ' הקדומ' כמ\"ש כי מן המים כו' וכמ\"ש מ\"ה שמ\"ו מ\"ה שם בנ\"ו כו' כידוע, וע\"כ כל התור' ניתנה לנו"],[1900640253,"ע\"י משה דוקא כמ\"ש תורה ציוה לנו משה שביכולתו להוריד מים החכמ' עילא' דעצמו' עד למטה בנשמו' שבגופי' כו' (וכמו שיכול בהעלא' מלמטה כמ\"ש וגם דל\"ה דל\"ה לנו כו'), וזהו נגד כל עמך אעשה נפלאו' אשר לא נבראו כו' שזה הי' דבר חדש שלא בא בהשתלשלו' דאבי\"ע מעולם שיהי' דילוג גדול כזה מלמעלה מעלה מן ההשתלשלו' למטה מטה כ\"כ להיו' חנון ומרבה לסלוח העון בפ\"מ, וע\"כ נק' נפלאו' נפלאו' רבים פלא אחר פל\"א העלם אחר העלם הן ב' עליו' הנ\"ל דויעבור ה' על פניו . והנה מבחי' נפלאו' הללו עצמן בא לידי גילוי למטה לכנ\"י וזהו נגד כל עמך אעש\"ה בגילוי נפלאו' העליוני' כו' שהרי נמחל להם עון חטא העגל בפ\"מ ע\"י המשכת י\"ג מדה\"ר הללו כידוע וד\"ל. וע\"ז א' ה' יחתו מריביו פי' בחטא העגל שקטרגו למעלה על ישראל ונעשו מריבי\"ם עם שם הוי' דחסד ורחמי' כו' וע\"י ירידת אור החסד העצמו' בי\"ג מדה\"ר כשא' ה' ה' אל רחום כו' יחת\"ו המריבי' המקטרגי' שנכנעו ונשברו בתכלית, והוא מב' סיבות א' מן ב' עליו' דב' קוי\"ן דגרשי\"י' שעל הוי' והיינו ויעבור ה' על פניו כנ\"ל, והב' מבחי' המשכה ויריד' שאחר העלי' הגדולה הזאת דוקא במ\"ש ויקרא ה' ה' כו' שירד עד למטה להתקבל בבחי' או\"פ למחול חטא העגל בפ\"מ כנ\"ל וד\"ל (והן ת' עלמין דכסופין דהיינו ד' מאות שקל כסף מקור החסדי' העליוני' הטובי' שבפנימי' ע\"י דנהרי' לצדקייא לע\"ל בבחי' או\"פ ועתה הן רק במקיף למקיף שזהו עוב\"ר לסוח\"ר כידוע, ובי\"ג מדה\"ר הוא שבאין לבחי' הגילוי מהעלם אחר העלם שבעצמו' התענוג הפשוט שנק' שעשועי המלך בעצמו כו' עד אשר בכחן להמתיק לד' מא' ב\"ד דז\"א שנק' גבורו' עליונו' שמהן מסתעף הדיני' שלמטה כו' שהרי א' יחת\"ו מריבי\"ו כו' ונמחל להם העון כנ\"ל, וכל זה ע\"י משה שמיהר והשתחוה ארצה שהורידן בהתלבשו' בז\"א להמתיק כל הדינין עד למטה מטה וע\"כ י\"ג מדה\"ר דמשה למעלה מי\"ג מדה\"ר דמיכה כמ\"ש בזוה\"ר רק ביו\"כ הן באין מעין דלע\"ל ממש כו' וד\"ל).\n<b>וזהו</b> ויתן עוז למלכו כו'. דהנה בסמוך לו א' עליו בשמים ירעם כו' עליו ב' פירושי' עליו למעלה הימנו ופי' הב' עליו בשבילו כו' ועלו כתיב חסר י'"],[1900640254,"ועליו קרי כו'. בהיות שכל הענין המבואר למעלה בענין ה' יחתו כו' שהן ב' עליו' וב' ירידו' כו' מחסד\"י העצמי כו', הכל הוא בחי' ירידת והמשכת אור החסד העליון שבעצמו' ממש באור הכת\"ר שהן י\"ג מדה\"ר ומשם נמשך עד למטה מטה להמתיק כל הדינין וקטרוגי' הקשי' כו' כנ\"ל, אך כל זה אינו רק מיתוק הגבו' קשו' בריבוי אור החסדי' עליוני' מאד (וכמו ויורהו ה' עץ כו' וימתקו המים שנמתקו המרירו' דגבו' קשו' במים דחסדי' עליוני' המתוקי' ביותר שהוא בחי' עה\"ח שלמעלה מעה\"ד כו' וכך הוא ע\"י תו\"מ ששרשם בעה\"ח מבררי' לעה\"ד כו'), אך הנה ידוע דעיקר מיתוק הגבו' אינו אלא בשרשן דוקא דהיינו בבחי' מקור הגבו' עליונו' דקדוש' דוקא לפי שאין מיתוק הדין אלא בשרשו דוקא (כמו אש הגיהנם שאוכל אש זרה דתאו' כו' שאין האש יוצא אלא ע\"י האש כמכוה האש שיוצא ע\"י חו\"ם האש יותר גדול ממנו וכן בקרירו' כו'), והרי באמת עיקר יניקת הגבו' קשו' הוא בגבורו' העליוני' כנ\"ל ברישא דעשו כו' וא\"כ איך יהי' מיתוק הדין בשרשו דוקא. אך הענין הוא דדוקא ע\"י גבו' עליונו' דקדוש' יפלו וישברו הגבו' קשו' וזהו יחת\"ו מריביו ע\"י שעליו בשמים ירע\"ם כו', והיינו כמ\"ש יגער ה' בך השטן כו' דהשטן הוא בחי' מקור לכל גבו' קשו' ודינין קשי' ואינו מועל לו רק הגער\"ה והוא הנזיפה וההרחקה בקול רעם כו', וכענין לעולם ירגיז אדם יצ\"ט על יצה\"ר כו' לפי שאין עצה לגרש היצה\"ר רק ע\"י רגזון וכעס עליו בשמאל דוחה להרחיק כו', וכמו שאנו רואי' בחוש שיסורין ממרקין כו', והתינוק לא יועיל לו להדריכו לדרך הטוב ע\"י קירוב ואהבה בלבד רק אדרבה ע\"י תוכחת מוסר לומר לו דברי' קשין ולהוכיחו בשבט מוסר ולהרחיקו בגער\"ה ונזיפ\"ה אמיתי' בזה יפול זדון לבו הרע ולא יהי' עוד שובב בדרך לבו להיו' סורר כו', וזהו שא' יצ\"ר ותינו\"ק ואש\"ה שמאל דוחה לרחק כו' לפי שכל ג' אלה הן בבחי' הגבו' דקטנו' ואין מיתוק הדין אלא בשרשו כמוהו דוקא דהיינו ברוגז וכעס וגער\"ה ונזיפ\"ה כו' ע\"כ א' יגער ה' en.בך השטן, יגער דוקא וד\"ל.\n<b>וביאור</b> הענין למעלה הנה בחי' גבורו' קשו' דק\"נ מבואר למעלה שזהו בחי' עצם כח הדין לפעול כל רע בפ\"מ וזהו חיותו העצמי כטבע איש רע כו' וע\"כ עולה ומסטין ויורד ומקטרג להרע בפ\"מ כו', ואין לו מיתוק אלא בשרשו דוקא היינו באופן הדין והכעס בגבו' ודין דקדושה לרגוז עליו בחרון אף ולהרחיקו שבזה יפול כל חלקי עצם הרע שבו בלי יהי' לו כח להרע כלל כי נלקח ממנו בזה הכעס"],[1900640255,"דגבו' דקדוש' עיקר שרש חיותו כו' וד\"ל (וכמעשה שסיפר הבעש\"ט ז\"ל שפ\"א רבו הקטרוגי' רעי' מן השטן עד להשחית כו' ולא הי' מועיל לפוטרו בשום טענה וזכו' לישראל וצוה ראש ב\"ד העליון לגעור בו ולדוחפו חוץ כו'). וזהו עליו בשמים ירעם במקור הגבורו' עליונו' עלי\"ו ל' מקיף למעלה מעלה ועליו בשבילו כו', דהנה ב' עליו' הנ\"ל בשם הוי' דחסד עד למעלה מעלה אע\"פ שאין שם אחיז' לקטרוגי' דק\"נ כלל ומה גם בירידת האור העליון למעלה מעלה כ\"כ למטה מטה שעי\"ז יתבטלו ממציאותם כענין קומה ה' ויפוצו וינוסו או יאבדו כו' ולא יהי' בהם כח לקטרג עוד, מ\"מ אין זה מיתוק הדין בשרשו לבער חלקי הרע בשרשו לבער חלקי הרע משרשו העצמי, כ\"א ע\"י בחי' ההמשכה ממקור הגבו' עילא' דכת\"ר עליון (שנק' בצ\"ק ולמעלה מעלה בבחי' גבו' דעצמו' המאציל כו' בחסד העצמו' הנ\"ל) שירד ונמשך עד למטה מטה בהשתלשלו' הגבורו' מגבורו' דאצי' בבי\"ע להיכלו' הנוג\"ה ג\"כ להמתיק הגבו' קשות שמסתעפי' שם עד שיחתו וישברו ממש מצד שרשם דוקא שמשפיע בהם כו' וד\"ל (כענין י' מכות באלקי מצרי' בבחי' גבו' עליונו' דקדוש' שמשם יונקי' גבו' קשו' דאלקי' אחרי' כמ\"ש תשלח חרונ\"ך כו' שזהו עיקר ענין האותו' ומופתי' שבמצרים שנק' ארץ חם כידוע שז\"ש בזוהר דתבר שלשליהון לעילא כמ\"ש ויסר אופן כו', וכמ\"כ בנסיעת הארון במדבר נחש שרף ועקרב גקה\"ט שנתבטלו ונשברו מבחי' הגבורו' עליונו' דשם מ\"ב שמשם מקבלי' מבחי' אחוריי' כו' כמ\"ש מלך אלקי' על גוים כו', וכן במחנה סנחריב כו' ובמחנה סיסרא וכה\"ג הכל מבחי' גבו' עליונו' דה' איש מלחמ' שנמשך בהשתלשלו' עד ע' שרי' שלמטה להכניעם בשרשם דוקא, ולע\"ל יומשך פחד אלקי' על כל העמי' וכמ\"ש כל העמים כו' כי ה' עליון נורא כו'), ומפני שצריך לעורר למקור כל הגבו' למעלה מעלה בעצמו' ממש וכמ\"ש מי יודע עוז אפ\"ך וכיראת\"ך עברת\"ך כו', וע\"כ א' עלי\"ו בבחי' מקיף דמקיף שבבחי' הגבו' כמו עלי\"ו דב' קוין דחסד דהוי' הנ\"ל וזהו עליו בלא יו\"ד שהוא למעלה מגבו' דאור אבא שביו\"ד, ועוד למעלה גם מבחי' הגבו' שבכת\"ר כו', והוא בגבו' ודין שבעצמו' כמו שפוך חמת\"ך ממש כו' חרון אפ\"ך ממש תרדוף באף כו' והיינו בחי' יריד'"],[1900640256,"והמשכה דגבו' עילא' עד למטה ממש (כמכות דמצרי' כו'), ופי' עלי\"ו בשבילו היינו כדי שלא יעמדו לריב ולנגד שם הוי' דחסד ורחמי' על ישראל וכמ\"ש יחתו מריבי\"ו משום דעליו בשבילו דשם הוי' בשמי\"ם דמקיף עליון ירע\"ם בקול גבו' ודין חזק להכניעם בעצם שרשם, וב' הפי' א' דמה שירעם על כח הדין בשרשו en.למעלה מעלה היינו בשביל שם הוי' שיומשך חסד ה' לעולם כו' וד\"ל.\n<b>והנה</b> דוד ע\"ה א' ג\"כ וירעם בשמים ה' ועליון יתן קולו ברד וגחלי אש וישלח חיציו ויפיצם כו' דהנה כל השירה זאת הוא בהצילו מכף אויביו בהיותו בצרת נפשו הי' תולה ההצלה בעוז גבורו' ה' על הרשעי' שחמתו נשפך עליהם כמ\"ש עלה עשן באפו ואש מפיו תאכל בערו גחלים, שכל זה להט החרב לה' מלאה גבו' שנמשך על ראש רשעי' למטה להומם ולאבדם בשרשם דוקא, ולא תלה ההצלה בזכות עצמו כי חסיד ועניו הי' ואדרבה מצא בעצמו חטאי' ועונו' שיבא מזה עליו הקטרוג הרע אך מה שניצול הוא מבחי' הגבו' ודין העליון על ראש רשעי' יחיל, וע\"כ סיבת הצלתו בא מב' דברי' א' מצד החסד ורחמי' כמ\"ש בתחלה ה' סלעי כו' עד בצר לי אקרא הוי' דחסד ורחמי' כו' והב' מפני המשכו' גבו' ודין העליון הקשה על הרשעי' להומם כו', וזהו וירעם בשמים ה' ועליון יתן קולו מצד עצמו כו' וד\"ל. ומ\"ש ועליו\"ן דוקא, היינו בבחי' מקור כל הגבו' עליונו' כנ\"ל בפי' עלי\"ו בשמים כו' בבחי' העלם הגבו' שבעצמו' ממש, ומשם יורד ונמשך עד למטה בגבורו' דאצי' בב' אופני' בר\"ד וגחלי אש ומשם ישלח חיצי\"ו בעולמו' הנפרדי' בהשתלשלו' עד ע' שרי' דנוג\"ה דעשי' כו' והכל מגער\"ת ה' כו' כמ\"ש יגער ה' בך כו' כנ\"ל וד\"ל. וזהו מה שמסיים ה' ידין אפסי ארץ וכמו השופט כל הארץ כו' וכמלך ששופט זה ישפיל וזה ירים וכמ\"ש תחלה ה' מוריש ומעשיר משפיל אף מרומם וכמו כי לא שלם עו\"ן האמור\"י עד הנה כו' והוא בבחי' דין וגבורו' עליונו' ידין אפסי ארץ להשפילם בשרשם דוקא משום דה' יחתו מריבי\"ו ועליו בשמי' ירעם למעלה מעלה כנ\"ל ע\"כ ממילא ידי\"ן אפסי ארץ למטה בפ\"מ en.כנ\"ל וד\"ל.\n<b>ויתן</b> עוז למלכו וירם קרן משיחו, פי' אחר שנמתקו הדינין וגבו' קשות בשרשן דוקא בגבו' עליונה דעליו בשמים ירעם כו' כנ\"ל אז דוקא מזה עצמו יתן עוז למלכו שהוא מלכא משיחא לע\"ל כידוע במשיח דכתי' בי' ישכיל עבדי ירום"],[1900640257,"ונשא כו'. וביאור הענין הנה מה שמבואר למעלה בענין מיתוק גבורו' קשו' בשרשם בדרך המשכה מגבורו' דקדוש' להומם ולאבדם כו', היינו דוקא לחלק הרע שבהם לבד כי הן מעורבי' טו\"ר וק\"נ דעשי' רובו רע גמור, אך לאחר איבוד ושבירה להרע גמור דק\"נ נשאר בהן בחי' הטוב דקדוש' שנפל בהם משבה\"כ דתוהו שקדם לתיקון כידוע, והיינו בחי' גבורו' עליונו' דקדוש' דבחי' ב\"ן דז' מלכי' דתוהו שהוא בבחי' ס\"ג דנקודי' שלמעלה מבחי' מ\"ה דברודי' דתיקון כו' (והוא מ\"ש ויתן עו\"ז גי' ס\"ג כשהוא מלא בוי\"ו כו'), והיינו כענין הנ\"ל באריכו' בבחי' גבו' שבחסד שהוא תוקף החסד ביותר מעצם אור החסד, והוא כאשר באה האהבה ברשפי אש וחום התלהבו' יתיר' שנק' שלהובי דרחימותא בתשוק' מרחוק דבע\"ת כו', עד שגם אתערות' דרחימו במקבל להיו' אל אישה תשוקת' ג\"כ מגבו' דחסד שזהו שמאל\"ו תחת לראשי כו' שמאל\"ו דוקא והוא התעוררו' התשוב' מעומק בכנ\"י כו', וזהו אשר פיצל במקלו' לייחם הצאן כו', וכך יובן שאחר ביעור ומפלת ואיבוד הרע שבק\"נ יעלה בחי' הטוב שבהם שהוא בשרשו בגבו' שבחסד כנ\"ל כענין רישא דעשו כו' (בדמיון חום התאו' ברתיח' הדמי' כשהוא לטוב וכיין המשמח כו' או כמו כעס ת\"ח ועובד ה' בהתלהבות שיכעס על הרע יותר או כמכה לבנו כו', שאחר המיתוק הן עוצם רשפי אש דקדוש' האלקי' שע\"ז א' טו\"ב מא\"ד זה מ\"ה שזהו ביצה\"ר שבוער כאש כשנהפך הרע עצמו לטוב בבע\"ת כנ\"ל וד\"ל), ולהיו' שהטוב דקדוש' העולה מגבו' קשות יותר נעלה מהטוב שבחסד יתן תוס' כח ועוז במל' דקדושה כמו ברכות דבלעם כשנהפך הקללה לברכה וכזדונו' שנעשו זכיו' דקטיגור עצמו נעשה סניגור, וזהו שתלוי ביאת משיח בתשוב' דוקא עד שגם לצדיקי' ישוב בתשו' כנ\"ל מפני שמזה דוקא יבא תוס' הכח ועוז למל' דקדוש' והוא בחי' התנשאו' יתירה שנא' במשיח וגבה מאד (וכמ\"ש במ\"א בענין והריחו בירא' ה' כו' שיאיר עליו מבחי' הוד דע\"י כו'), כי שרש הגבו' בעצמו' הוא בחי' ההתנשאו' בעילוי אחר עילוי בעצמו' כמ\"ש כי גא\"ה גא\"ה כו' התנשאו' על התנשאות דהיינו למעלה מהתנשאו' דימות עולם אלא כמו שהוא מלך יחיד מרומ\"ם לבד\"ו מצד עצמו כו' (שזהו ענין אגוסטוס יושב ומלך עומד כמ\"ש במ\"א),"],[1900640258,"וזהו עד יעבור כו' לשם הוי' עם זו קני\"ת בעצמותו כו', וכן ענין אהי' אשר אהי' אנא זמין לאתגלא' מבחי' התנשאו' דעצמותו ממש במלכא משיחא כו' וד\"ל, וזהו ויתן עוז למלכ\"ו סתם בוי\"ו על היות שהוא במל' דא\"ס כמו שהוא בעצם טרם שנק' מלכותך מלכו' כ\"ע סובב הכללי כו'.\n<b>וזהו</b> וירם קרן משיחו דהנה מ\"ש ויתן עוז למלכו זהו מ\"ש ה' מלך גיאו' לבש עו\"ז כו' היינו מבחי' הברורי' דגבו' דרפ\"ח כו' שהוא העולה למעלה מעלה במקור כל הגבורו' ויתן כח נוסף בחסד דימין דוקא, שז\"ש כי ההרים ימושו וכו' וחסד\"י מאתך כו', ואמנם מ\"ש ירום ונשא וגבה שהן מבחי' חג\"ת דע\"י עד מא\"ד שהוא בעצמו' ממש היינו בחי' עלי' ב' דמשיח, והוא מ\"ש וירם קרן משיחו פי' שירים קרנו עוד למעלה מעצם מדרגתו והוא למעלה מבחי' הברורי' דרפ\"ח כו' כי ע\"י התשוב' סומע\"ט בבחי' או\"ח היינו בחי' ע\"ס דאו\"ח ואו\"י שהן ב' קומות דאד\"ם כו', אבל מ\"ש מא\"ד למעלה מבחי' אד\"ם והוא מ\"ש עד דוד הגדיל שהגדיל למעלה מעלה מבחי' מ\"ה דאד\"ם והיינו בבחי' עצמו' אא\"ס ממש שלמעלה גם מההתנשאו' שמצד עצמו בלבד כנ\"ל, לפי שכל בחי' התנשאו' הוא בבחי' מל' עכ\"פ ויש בזה ערך והשתוות לכל אשר יסתעף בסיבת הצמצום והשיעור, ששיער בעצמו בכח מה שעתיד להיו' בפועל שנק' טה\"ע כו', אבל בחי' עצמותו ממש שוה הוא בהיותו למעלה ולמטה ולא שייך לשון עילוי למעלה בהתנשאו' ולא ל' ירידה למטה דמ\"ש דאא\"ס למעלה עד אין קץ ולמטה עד אין תכלית אע\"פ שהן בחי' חו\"ג שבעצמו', אבל הוא עכ\"פ בחי' התפשטו' אורו שיתכן בו העלי' עד אין קץ והיריד' עד אין תכלית, אך כמו שהוא בעצמותו ומהותו לא שייך ל' עלי' וירידה כלל כידוע (והוא ההפרש בין התנשאו' דאד\"ם שמתנשא על זולתו כטבע האד\"ם שיש בו התנשאו' על כל הברואי' לפי שכולם כלולי' בו, אבל למעלה מבחי' אד\"ם לא שייך ל' התנשאות מאחר שלא שיער בעצמו בכח עדיין כו' רק הכל בבחי' העצמו' שלא יתכן שם ענין מעלה ומטה כלל וכלל, א\"כ גם התנשאו' שמצד עצמו לא"],[1900640259,"יתכן רק בבחי' אור דא\"ס ולא במהות הא\"ס עצמו וד\"ל). וזהו וירם קרן משיחו en.en.להיו' בדומה לעצמו' ממש וזהו ונח\"י' לפני\"ו ממש וד\"ל.\n<b>ולהבין</b> ענין וירם קרן משיחו בתוס' ביאור יש להבין תחלה מ\"ש במ\"א ע\"פ למרבה המשרה ולשלום אין קץ כו' דקאי זה במשיח דפסוק זה נא' בישעי' (סי' ט') גבי חזקי' כי ילד יולד לנו בן נתן לנו ותהי המשרה על שכמו ויקרא שמו פלא יועץ כו' למרבה המשרה כו' (דביקש לעשות לחזקיהו משיח ובאמת פסוק זה על משיח בן דוד נאמר), ויש להבין ענין המ\"ם סתומה שבאמצע התיבה דמרב\"ה דפלא גדול הוא ולא נמצא בכתובי' כן. אך הנה תחלה יש לבאר סוף פסוק זה במ\"ש ולשלום אין קץ מהו אין קץ כו' על כסא דוד ועל ממלכתו להכין אותה ולסעדה מעתה ועד עולם כו'. דהנה פי' כסא דוד וממלכתו הוא בחי' בנין המל' דאצי' בתכלית הגדלות כמ\"ש עד דו\"ד הגדי\"ל והוא משיח ב\"ד שיהי' למלכותו קיום נצחי כמו שאו' בקידוש הלבנה דוד מ\"י חי וקיים וכן א' בדניאל וע\"י יתיב כו' עד מלכותי' מלכו' עלם כו' ה' ימלוך לע\"ו כו' וז\"ש להכין אותה ולסעד' מעת\"ה ועד עול\"ם וד\"ל. והטעם ידוע במ\"ש במשיח חיים נתת לו פי' חיים נצחיים נתת במתנה עולמי' כו' להיות ידוע דמה שלא נתקיים מל' דוד עתה היינו לפי שנא' בו חיים שאל כו' דע' שנין דדוד שאולי' מאדה\"ר כו'. והענין הוא דשרש נשמת דוד הי' מבחי' מל' דאצי' דלית לה מגרמה כלום רק מה שנשאל מבחי' ז\"ת דא\"ק שהוא ז' מדו' דחכמה שנק' אדה\"ר כידוע בענין מ\"ה שמו מ\"ה שם בנ\"ו כו' דאבא יסד ברתא ששרש אותיו' הדיבור מז\"ת דאבא (וכמשי\"ת), וזהו ימי שנותינו בה\"ם ע' שנה לבד והן הע' שנה שנלקחו מאדה\"ר כו' (והיינו ת\"ר אלף נש\"י שבימי משה שקיבלו מאור אבא שרש משה ואוריי' מח\"ע נפק' להאיר בס\"ר נש\"י הללו,"],[1900640260,"וכן דור אחר דור המסתעפי' מהם עד ביאת משיח ששרשו באור פנימי' הכת\"ר כמ\"ש אשר אה\"י' אנא זמין לאתגלא' בימי המשיח שנק' גואל אחרון והוא בבחי' פנימי' ע\"י כו' ובחי' מלכו' משיח הוא בבחי' מל' דא\"ס עצמו שבא בבחי' חיי\"ם נצחיי\"ם דאור א\"ס עצמו וזהו חיי\"ם נת\"ת לו כו', וזהו דוד מ\"י חי וקיים לנצח וכמו שא' ברוך חי לעד וקיים לנצח (והיינו נשמתא דפרחא מחי העולמי' שמאיר בכל שבת מעין יום שכולו שבת כו'), וכמ\"ש ה' ימלוך לע\"ו כו' וד\"ל. וזהו כללות ענין מל' משיח שעליו א' כאן על כסא דוד וממלכתו להכין אותה ולסעדה מעתה ועד עולם בבחי' נצחיות.\n<b>אך</b> מ\"ש להכין אותה ולסעדה עכשיו דוקא כו' איך יכינו בנין המל' עכשיו להיו' בבחי' הנצחי' אחר שבנין המל' עתה רק מז\"ת דחכמ' דאור אבא לבד כנ\"ל, וגם להבין שרש ענין בנין המל' איך דלית לה מגרמ' כלום כו'. הנה יש להקדים ענין הידוע בעיקר בנין המל' איך שהוא מו\"ק דז\"א דהיינו מבחי' מל' דחסד דז\"א נבנה בחי' חסד שבמל' דאצי' ומבחי' מל' דגבור' דז\"א נבנה בחי' גבורו' שבמל' כו' ועד\"ז בכל פרטי הספי' דז\"א עד בחי' מל' דמל' דז\"א נעשה מל' דמל' דאצי', וכך הוא כחב\"ד דמל' דחכמ' דז\"א נבנה חכמ' שבמל' ועד\"ז בהתחלקו' כל ספי' לי' כו' וכללותם הן י' מלכיו' שבע\"ס דז\"א שמהן נבנין ע\"ס דמל', והיינו יו\"ד מלכיו' שא' דוד כו' שאומרי' בכל ר\"ה בשביל בנין הנוק' (שהיא אחת מצלעותיו כידוע בענין הנסירה כו'), וזהו שא' במשנה האשה נקנית בג' דרכי' כו' והן נחלקי' לי' שהן ל' מעלות שהמל' נקנה בהן שהוא ל' כלים דז\"א כו', והיינו בחי' ל' הגבורי'"],[1900640261,"אשר לדוד שהוא חב\"ד דז\"א שכל א' נחלק לי\"ס וכן נה\"י כו' כידוע בזוהר בענין ג' עדרי צאן רובצי' עלי' כו', וזהו שא' באד\"ר דו\"ק שבמל' היינו ו' אלפי' רבבו' ספיראן (כי כל ספי' דז\"א נחלקת לי' וי' לי' עד ה' פעמי' הרי עולה ת\"ר אלף שהן ס\"ר, ועוד נחלק פעם הו' לי' הרי י\"פ ס\"ר הן ת\"ר רבבות, ועוד נחלק פעם הז' לי' הרי י\"פ ת\"ר רבות הן ו' אלפי' רבבו' לפי שההתחלקו' לי' הן ז' פעמי' לנגד ז' מדו' דכל ספי' וד\"ל).\n<b>ולהבין</b> ביאור הדברי' הנה ידוע דעיקר בחי' המל' הוא רק בחי' ההתגלות של עצם הדבר לבד ואינו נחשב בבחי' מהות ועצם הדבר כלל אך הוא בחי' הישות שלו לבד כו', דהיינו מה שנגלה הדבר באיזה מציאת ויש עכ\"פ והוא אשר נתפס ומתלבש בענין דבר מה הנגלה כו' משא\"כ טרם הגלותו במציא' ויש לא הי' נראה בבחי' יש ודבר מה כלל וד\"ל. עד\"מ מדת החסד שבא בהתפעלות בלב איש החסד בטבעו, דודאי טרם שבא לכלל גילוי בלבו לא הי' ניכר מציא' חסד כלל כי הי' בלבו בהעלם והוא בבחי' היול\"י שזהו בכ\"ח ולא בפועל, וכשיתעורר החסד בלבו בא לידי גילוי במציאת יש ודבר מה והוא באותו ענין שנתפס ומלובש בו אותו החסד והטוב כמו בנתינת כסף צדקה לעני או לחם ולבוש כו' או בגמ\"ח בדבר שבממון או בחסד שבגופו כביקור חולים כו', וכה\"ג יש הרבה חלוקי ענינים של חסד בגילוי בלבו וכולם כלולי' בכח מדת החסד וטוב שבטבע איש החסד כו' ויצא מן ההעלם לגילוי לבד לפעמי' בדבר זה ולפעמי' בדבר אחר, שאין זה רק גילוי והתלבשות אור עצם החסד שנתפס ומתלבש בדבר מה כממון או לחם או לבוש או דבר חסד בגופו הכל שוה ממש לגבי עצם אור מדת החסד הנטוע בטבע לב האיש הטוב והחסד כו' כי הרי כל מה שיבקשו ממנו טוב וחסד יתעורר בלבו מיד בלי עיכוב כלל כו', ולזאת יובן שזה הגילוי הוא ההתעוררו' חסד בלב יש בו ג\"כ בבחי' כלל ופרט דכאשר יבא לכלל התעוררו' חסד לאו\"נ ובנו יחידו וכה\"ג עדיין אין בו חלוקי עניני' בפרט רק דרך כלל ואח\"כ מתחלק ובא ומתלבש בעניני חסד שונים כו', ונמצא שהענין שבו מתלבש החסד הוא הנק' גילוי מציא' בדבר מה בפרט שאינו רק לבוש לגבי העצם כנ\"ל, אבל גופו של בחי' הגילוי התעוררו' חסד בכלל נק' גילוי עצם החסד שנחשב כמו כח העצם של חסד ממש מאחר שלא בא עדיין דרך פרט, אך הוא כחומר היולי לגבי צורה היולית כו' כחומר המוח לגבי צורת השכל שמוכן להיות כלי מקבל כל דבר חכמה להכילו בכלי המוח כל מה שיש בכח השכל להשכיל ולהמציא כל שכל וסברא וכהכנת חומר כלי העין"],[1900640262,"להביט כל שאור הראי' יראה כו', וכך הוא ענין הכנת כלי חומר הלב להכיל כללות אור עצם אור החסד ההיולי שיש בכ\"ח בהעלם הכל יבא בו בגילוי בכלל התעוררו' טרם שמתחלק לפרטי עניני' שנק' חומר היולי כנ\"ל וד\"ל.\n<b>אך</b> א\"כ יש להבין מאין נמצא בחי' ההתחלקו' של החסד בעניני' שונים כלחם וממון ולבוש כנ\"ל דכמו שאין זה מצד האור והצורה שהיא פשוטה כך גם החומר הוא פשוט וכן במוח החכמ' לקבל כמה עניני' חלוקי' כו' , אלא צריך לומר דחומר הצורה נבדל בזה מעצם האור במה שיוכל להתחלק לעניני' ולבושי' פרטיי' ונק' גילוי דגילוי העצם כמו גילוי התעוררו' החסד שמתגלה ומתלבש בלבושי' שונים כו' וזהו הנק' התחלקו' לי' כלים לי' אורו' משא\"כ בגילוי הראשון שהיא רק כלי א' (וזהו דמיון להבין ההפרש בין בחי' עקודי' שכל הע\"ס עקוד בכלי א' לנקודי' שנחלק לי' כו'), ועד\"ז יובן שיוכל אור החסד להתחלק לי' חב\"ד חג\"ת נה\"י כו' דחסד בעצם הוא עצם האור וכלול מי' היינו גם ממדת הדין והוא גבו' שבחסד לצמצם החסד כפי הצריך לבד כו' וכן נצח שבחסד כו' עד חב\"ד שבחסד, חכמ' שבחסד הוא כמו שפע שכל שבטובו משפיע שכל וחכמ' לתלמידו ובנו וכן בינה שבחסד להסביר לו בטוב טעם ודעת ועד\"ז כת\"ר שבחסד ורצון ותענוג של חסד (ובאמת גילוי השפע חסד יהי' במה שיהי' אם בשכל או בממון ולחם הכל נק' חסד שבא בהתלבשו' דבר מה כנ\"ל אלא הטעם והשכל למה יתחסד זהו חב\"ד של מדת חסד כו'), ומצד שהאור דחסד יש בו התחלקו' מי' ע\"כ גם ימצא בכלי הלב בהתחלקות לי' כנ\"ל, והא בהא תליא רק שבאור אין ההתחלקו' ניכרת ולא נתפס בדבר מה ובכלי הלב יש לכל היכר בפ\"ע כי ודאי חסד שבא בלב ליתן לחם וממון אינו דומה לחסד שבא בלב להשפיע שכל או דבר תענוג רוחני (ככבוד וגדולה וקירוב הלב בדברי אהב' או כחשק השפע דאיש לאשתו כו'), וכן חדוה ומרירות שהן ב' הפכי' לכ.. במדת החסד יש תענוג וחדוה ובהעדרו והיפוכו יש צער והן ב' en.en.קוין שקולין שמסתעפי' יחד ואינן ניכרי' כל א' בפ\"ע כ\"א בכלי הלב דוקא וד\"ל.\n<b>ונמצא</b> מובן עכ\"פ שאין התחלקו' ניכרת כ\"א בבחי' המל' של כל מדה ולא בט\"ס שבה כו' והיינו בחי' הגילוי של כל מדה כאשר בא בפרט דוקא כמו בחסד חב\"ד חג\"ת כו' שבה כמו שהוא קודם שמתגלה בלב דרך פרט (רק בהתעוררו' חסד בכלל כנ\"ל) אין שם התחלקו' ניכרת רק כאשר מתגלה בלב אז לכל א' גילוי באופן מיוחד כמו מל' שבשכל דחסד ומל' שבגבו' שבחסד ומל' שבנצח דחסד כו', והן י' חלוקי גילויי' מרצון של חסד עד יסוד שבחסד שהוא הבא במורגש בלב להשפיע לדיבור ומעשה כו' (אך מל' שבחסד היינו כל גילוי דכל פרט מן החסד אם מחו\"ג וחו\"ב כו' וע\"כ אין המל' שבכל מדה נחשב למהו' במציא' בפ\"ע כי אינו רק בחי' הגילוי של הט\"ס אבל הוא בחי' גילוי דגילוי העצם הנ\"ל וד\"ל), וכך הוא באור הגבו' ואור הת\"ת והנצח וכהנ\"ל הכל בבחי' המל' שבהן הוא שבא בהתחלקו' לי' כו', ולמעלה הוא הנק' ט\"ס דז\"א שבא לכלל גילוי בלב האדם העליון בבחי' המל' שבכל א' וא' ומבחי' המל' שכל ספי' נבנה בנין המל' היינו"],[1900640263,"בחי' גילוי הדיבור שהוא בחי' גילוי נפרד בהבל הפה שאין לו השתוות לגילוי שבלב כ\"א במראה ולא בעצם, היינו שכל מה שמתגלה בלב בא גילוי זה בדיבור אבל זהו כמו אותיות החותם שנחקק בדבר זולתו נבדל מעצם החותם כשעוה שאין בשעוה רק דמות ומראה לבד מעצם האותיו' שבחותם כו', כך נא' נעשה אדם בצלמינ\"ו כדמותינו צלם היינו אותיו' דט\"ס עצמן כשהן בגילוי בלב וכה\"ג כנ\"ל שנק' גילוי העצם כאותיו' השכל ואותיו' גילוי החסד שבלב אבל מה שבא גילויו בהבל הדיבור אין זה רק כמו שיוצא לחוץ בדבר נפרד ממש, ומ\"מ הרי הבל הלב אחוז וקשור בהבל הפה והיו לאחדים ממש אשר ע\"כ כל אופן הגילוי של כל מדה כמו שהיא ממש באותו אופן ממש בא בהבל הדיבור אם דבר החסד בלב ממון או לחם כך יוציאו בגילוי בדיבור ואם הוא שכל ותענוג כך יוציאו בדיבור כמו ראוה מדבר\"ת כו' דברי אהבה וחשק, וכן במדת הדין הרי בא בגילוי הדיבור דברים של כעס ורוגז רק כמו שהוא בלב כו' רק שנמשך הגילוי הזה במהו' נבדל בפ\"ע כמו כח הציור דאותיו' החותם בדבר נבדל שזהו ענין אתוון א.. וזהו ענין בנין המל' שהוא הדיבור רק מבחי' מל' דכל ט\"ס דז\"א כמו ממל' שבחסד דז\"א נבנה חסד שבמל' וממל' דגבו' דז\"א כו' דהיינו שכל מציאת אור אהבה וחסד שבא בגילוי הדיבור אינו רק מבחי' גילוי החסד ואהבה בלב כו' וכך כל פרטי הע\"ס en.שבמל' שנק' דיבור העליון כידוע וד\"ל.\n<b>והנה</b> מובן עכ\"פ מכל הנ\"ל שבחי' המל' הוא בחי' הישות של כל מדה הן בהיותה בלב או בגילוי הדיבור הכל הוא רק בחי' גילוי העצם או גילוי דגילוי כנ\"ל, אבל בחי' אור של המדה היינו בחי' האי\"ן שלה שהוא בחי' העצם שלה כמו שהיא נטועה בכח והיולי שלא נגלה במציא' מדה עדיין כנ\"ל והיינו בכל ט\"ס שבה נק' אור ולא כלי שהוא הנק' אי\"ן ולא י\"ש כו', והיינו מצד שכל ט\"ס שלה כלולי' בהעלם בעילה שלו שמקבל משם ואינו יוצא משם כלל למטה להיו' במציא' יש ודבר מה רק בחי' המל' שבו לבד, ע\"ד דוגמא בהשתלשלו' המדה דחסד מן החכמ' שהחסד ענף החכמ' הרי החכמ' נק' עילה והחסד עלול כמו התפעלו' החסד בלב מצד השכל והטעם שבמוח למה יעשהו וכן אהבה התלוי' בדבר טעם ודעת שבודאי לא נגלה בלב רק בחי' הישות שלו שהוא גילוי שלו לבד בלב אבל ט\"ס שבו שהוא חב\"ד וחג\"ת ונה\"י שבו כלול בעילתו שהוא החכמה שבראש בבחי' אי\"ן ממש, ועד\"ז גם החכמ' שכלולה מי\"ס אין הגילוי שלו במוח רק בחי' המל' וט\"ס דחכמ' כלול בהעלם בלמעלה מן החכמ' בבחי' אי\"ן דהיינו במקור השכל שנק' משכיל וכמ\"ש והחכמ' מאי\"ן תמצא פי' מאי\"ן דכח המשכיל תמצא בגילוי בבחי' יש שהוא מל' דחכמ' לבד כידוע, ועד\"ז בכל ספי' ומדה"],[1900640264,"שיורד מעילה לעלול כל ט\"ס דעלול כלולי' בעילה בבחי' אי\"ן ממש ורק בחי' המל' שבו יורד בגילוי במציא' דבר מה (שהרי אנו רואי' גם ברצון ותענוג שלמעלה מן החכמ' אינו בא בגילוי במציא' רצון או תענוג רק בחי' המל' שבו אבל המדו' ושכל וטעם הכמוס לרצון ותענוג זה כלולי' בעילה שלו שהוא מקור כל רצון ותענוג כו' שמשם יוצא לאור גילוי כל רצון ותענוג, וכמו שידוע בענין ע\"ת רצו\"ן כו' שנמשך מבחי' רעוא דכ\"ר כו', וכן גילוי מציאת התענוג ממקור התענוג שנק' תענוג הפשוט כו' עד גם בבחי' האחרונה שהוא הדיבור גם הוא כלול מי\"ס ולא בא בגילוי ממנו במציא' יש רק דיבור שבדיבור שהוא הבל הפה מורכב מאמ\"ר גשמיי', אבל בחי' מדו' ושכל שבו כלולי' בעילתו שהוא המחשבה שבמוח או המדות שבלב כו' אע\"פ שנגלין מדו' אוי\"ר ושכל בדיבור הכל הוא רק בבחי' גילוי לבד, וכן גילוי מל' דחכמ' כלול מי' אבל הוא רק בבחי' הגילוי ולא כמו שהוא בבחי' אי\"ן העצמי בעילתו כו'.\n<b>(אך</b> עדיין יש להבין דלפ\"ז שבחי' מל' היינו הגילוי של כל מדה ונק' ישות שלה הרי זהו בחי' הכלי לאור וכמ\"ש במ\"א בענין אור וכלי שהן ב' הפכי' דהאור בחי' אי\"ן עולה למעלה והכלי בחי' יש יורד למטה וע\"כ כל שפע בא מן הכלי דוקא ולא מן האור כידוע, ולפ\"ז אין הפרש כלל בין בחי' המל' לבחי' כלי דהיינו הך שהוא רק בחי' הגילוי והישות לבד. ובאמת הרי בחי' המל' דכל ספי' הגם שהוא בחי' הגילוי לבד אבל נחשב עדיין בבחי' אור עכ\"פ ולא בבחי' כלי שהרי כל ע\"ס שכלולי' בכל ספי' נק' אור ולא כלי גם בחי' המל' שבה כו'. אלא צריך לומר דגם שבחי' המל' הוא רק הגילוי לבד אינו יש מוגבל עדיין דאינו רק בחי' התגלות העצם כשנגלה במציא' דבר מה אך עדיין אינו בא בבחי' הגבלה כלל כו', אבל בחי' הכלי לאור מלבד ישותו בשינוי המהו' הוא בחי' הגבלה דוקא שמגביל את האור בגדריו והיינו מצד שהכלי הוא העושה את האור בשינוי המהות ובישות מוגבלת לפי אופן הגבלת הכלי דוקא כו', ע\"ד דוגמא כלי המוח שמבואר למעלה שנק' חומר פשוט לצורה פשוטה שכולל הכנת כל המושכלו' ומתחלק לכמה עניני' של שכל לחסד ולדין הרי זהו התחלקו' הכלי והגבלת הכלי כי מאחר שהשכל שבכלי המוח הוא בא ונתפס ומתלבש בענין דבר מה שהוא דבר מוגבל בעצם בהכרח שבא גם ההגבלה הזאת באותו שכל שנתפס ברגע זו בחומר המוח באותו ענין פרטי, וכן במדת חסד בכלי הלב שגם הוא חומר מוכן לכל מיני חסד כנ\"ל הרי מתחלק לבא בלבושי' שונים כמו ליתן צדקה או להשפיע שכל כו' ה\"ז בא בבחי' הגבלה גמורה מצד שנתפס ובא בצדקה זו או שפע שכל מצומצם לתינוק וכה\"ג בכל ספי' נק' הגבלת אותו הענין שנתפס בו בחי' הגילוי דבחי' המל' שבו בשם כלי המגביל כו' אבל בחי' הגילוי עצמו אינו בבחי' הגבלה עדיין"],[1900640265,"מאחר שהוא מגלה אור העצם הבלתי מוגבל, ויובן זה גם בגילוי הדיבור שיש בו גילוי העצם דמדו' ושכל שבלב ומוח בבלתי מוגבל כמו שהן בלב ומוח ויש בדיבור מצד אותיו' וצירופי' שבהן הענין של המדה או השכל מוגבל באופן כך וכך ולא יותר כו' ככלי המכיל המשקה שמגבילו לפי מדת הכלי והוא בא בשינוי המהו' והכל א' משא\"כ ההתגלו' דמל' אינו בא בשינוי המהו' מאחר שהוא הגילוי של העצם רק שנק' י\"ש לגבי בחי' האי\"ן דעצמו' המדה כו' (ולא כהפרש שבין אותיו' החותם לאותיו' שבשעוה שאותיו' החותם אע\"פ שנק' צורה עצמי' מגביל הוא כו', ומ\"ש למעלה דהבל הדיבור הוא כמו חותם שבשעוה גם זה אמת והוא מצד כלי הדיבור בהבל ה' מוצאו' שמגבילי' אבל גילוי הבל הלב בדיבור בלתי מוגבל בעצם כהבל הלב עצמו רק שמעשיו מוגבלי' בצירופי' דהבל כלי הדיבור באותו ענין שנתפס בו כמו בדברי אהבה או דברי רוגז הרי מוגבל שם לפי מראה en.הגבלת אופן צירופי הדיבור אבל עצם הגילוי זה אינו מוגבל כו' וד\"ל).\n<b>והנה</b> עכ\"פ מובן דרך כלל דבחי' התגלות המדה עדיין אין בו בחי' הגבלת כלי להכילו ולהלבישו בדבר מה (כגילוי החסד בלב ליתן צדקה בפועל שאע\"פ שמוגבל בלבו כמה יתן אבל עדיין אינו גבול בפועל עד הנתינה בפועל) רק שנגלה במציאת בלבד אבל באיזה ענין ודבר מה שנתפס ומוגבל בו גילויו הוא הנק' כלי המגביל שנק' יש מוגבל כו', וכמו גילוי השכל במוח שבא בענין מחשבת שכל בדבר מה מוגבל בו גילויו נק' כלי, וכן החסד בלב כשבא בהתלבשו' בענין נתינת צדקה בפ\"מ הוא הכלי שמגביל גילויו וזהו עיקר ענין ההפרש בין בחי' מל' לבחי' כלי (ולפ\"ז הגילוי בלתי מוגבל והכלי מוגבל והן ב' הפכי' לכאורה ובאמת אנו רואי' שהכל א' שכאשר נגלה המדה ממילא בא להגבלת ענין דבר מה כו', כמו בהגלות החסד לדבר פרטי כנתינת צדקה מוגבל בפועל אח\"כ כפי אופן הגבול בגילויו בלב לא יוסיף ולא יגרע כלל, אלא צריך לומר כמ\"ש במ\"א שיש ג' מדרגו' בכלל אור וכלי ולבוש והיינו דמה שנתפס המדה בענין דבר מה הוא הנק' לבוש והכלי הוא הגבול בכח בהיותו עדיין בלב או במוח שמגביל לעצם האור להיו' באופן כך וכך ולא כדלעיל דאל\"כ האיך ימצא בחי' ההתכללו' בכלים מאחר שבא בגבול בפועל כך ולא כך האיך ישונה מדבר להיפוכו משא\"כ בהיותו עדיין בכח ולא בפועל בלבוש הענין יוכללו כמשי\"ת וד\"ל).\n<b>ובכל</b> הנ\"ל יובן בפסוק דלמרבה המשרה מהו ענין ריבוי השררו' כו' ומהו ענין ריבוי השלום שא' אח\"כ ולשלום אין קץ כו'. אך יש להקדים תחלה ענין א' בכלל והוא בבחי' התוהו והתיקון והוא במ\"ש דעד דלא הוה מתקלא לא הוו"],[1900640266,"משגחין אפין באפין כו' שזהו מא' קו המדה שנק' מתקלא ונק' משחתא שהוא מקור בחי' התיקון כידוע. וביאור הענין הנה ידוע בענין ואלה המלכי' כו' דמ\"ש וימלוך וימת כו' לפי שע\"ס דבחי' התוהו הן זה תחת זה כו' דהיינו מפני שאין להן חיבור וקשר זע\"ז כלל וכלל אלא כל א' וא' י\"ש ודבר גדול בפ\"ע דוקא כו', וע\"כ א' וימת פ' ואח\"כ וימלוך פ' משום דבשעה שמלך זה לא הי' באפשרי שימלוך השני לפי שעיקר בחי' המלוכה הוא בחי' היש ודבר בפ\"ע דוקא וע\"כ אין מלכו' נוגע' בחברתה אפי' כמלא נימא, וכנראה בטבע בנ\"א החשובי' שכל א' יש ודבר בפ\"ע בגדולה וחשיבות ביותר לא יוכל לבא לידי חיבור ואחדות עם זולתו הגדול וחשוב כמו ב' מלכי' או ב' שרים גדולים וכה\"ג כל שהמה גדולים בעצם ביותר יותר לא יוכלו להתחבר ולהתאחד לפי שכל א' תופס מקום ויש גדול בפ\"ע עד שלא יוכל לסבול שום גדולה וחשיבות זולתו משום דכלא ממש חשיבי כולא קמי' מצד עצם גודל הרוממות שלו וע\"כ לא יכיל התפשטו' וישות זולתו כלל (ומה ששני מלכי' ושרי' יכולי' להתחבר היינו למלחמה או עצה שיתכללו יחד להיות לעזר זה לזה וזה צריך לזה וכל א' יש לו ביטול ישותו לגבי זולתו היפך הפירוד כשכל א' על מקומו דוקא משום דכל אחדות וחיבור א\"א כ\"א מצד שפלות כל א' וצמצום עצמותו לגבי זולתו דהיינו מה שימצא כח ועזר לו בזולתו שאין בו כמשי\"ת), אבל הנה בנ\"א הקטני' בערך כל שהמה קטני' בעצמם יותר יותר יוכלו להתאחד ולהתחבר יחד לפי שכל א' אינו תופס מקום ויש כלל בעצמו ובקל הוא נכנע ובטל להתכלל בזולתו הגם שהוא היפכו (כמו ב' עניי' שפלים בטבעם נמוכי רוח אע\"פ שהן ב' הפכי' בטבעם יתאחדו ויאהבו זא\"ז ובטל כל א' מפני חבירו וכן ב' נרדפי' שאוהבי' זא\"ז כידוע (וכן במקבלי' כתלמידי' ונשים זונות שמפרכסות זא\"ז כו' משא\"כ במשפיעי' כו').\n<b>ונמצא</b> דכל בחי' אחדו' וחיבור ובפרט בב' הפכי' א\"א כ\"א ע\"י בחי' ביטול ושפלו' עצמו היינו בחי' העדר הרגשת עצמו כ\"כ שזהו הנק' בחי' אין ומ\"ה (כמו שא' שמשים א\"ע כאילו אינ\"ו וכמ\"ש ונחנו מ\"ה כידוע), וכל עיקר סיבת הפירוד וההתחלקות בתכלית הוא בא מבחי' הישות וגסות בתכלית, וכל סיבת האחדות בתכלית בא מתכלית השפלות והביטול דבחי' אי\"ן ומ\"ה היפך הישות כו' (וכהפרש זה יש גם בדיעות בנ\"א כמו בני א\"י שנוחין זה לזה כשמן שכל א'"],[1900640267,"מתכלל בדעת זולתו ההפכי שזה מכח מ\"ה דחכמ' יותר ובני בבל להיפך שסותר לחבירו ועומד בדעתו לנגד דעת חבירו ההפכי כו', וכך כל ענין של פירוד ומחלוקת או שלום ואחדות הכל תלוי באופן הישות או האי\"ן ומ\"ה כו' שיש אנשי מקום ששונאי' זא\"ז ומרבי' מחלוקת תמיד מצד ישותם וגסותם כל א' רוצה להשתרר על זולתו ויש מקום להיפך שנכנעי' זה לזה כו' וד\"ל). (ובמ\"א מבואר שמלבד ענין הישו\"ת והאי\"ן יש טעם אחר לענין הפירוד או האחדות והוא כמו באנשי סדום ששרשם הי' מבחי' התוהו ע\"כ אמרו שלי שלי שלך שלך שהוא מד\"ת סדו\"ם, דהיינו שכל א' רוצה להיות בבחי' השלימות בפ\"ע בלתי יצטרך לקבל שפעו מזולתו כלל כי זה שצריך לקבל מזולתו הוא מצד שנחסר לו בעצם שלא יוכל להשלימו כ\"א ע\"י זולתו שיש בו אותו הדבר מה שאין בו ואין זה בחי' שלימות כידוע, וע\"כ הי' מדתם לו' שלי שלי שלא ישפיע לזולתו כלל וגם זולתו לא ישפיע לו, ושלך שלך כי הי' ארצם מובדל מכל ארצות בלתי צריכי' לקבל שום טובה בפרנסה מארץ נכרי' ולא שאר חסד מאיש נכרי וכן ביניהם לא הי' צריכי' זה לזה כלל כו', אבל ה' בחכ\"מ' יס\"ד ארץ שכל הארץ היא בבחי' התיקון דחכמה שהוא היפך זה ממש והוא שיקבל כל אקלי\"ם שפע פרנס' מארץ זולתו וזהו עיקר המסחור כידוע, ונמצא כל ארץ מקבל מזולתה ומשפיע לזולתה, וזהו ואגודת\"ו על ארץ יסדה כאגוד\"ה זו שבין הכל כא' חשוב ואין לחלק א' שלימות בלי זולתו וכמו איברי האדם שמתכללי' זע\"ז ואין לא' שלימות כלל בלי יקבל חסרונו מזולתו שכולם יש בהן חסרון ששלימותו מקבל מאבר זולתו כידוע, וכמ\"ש לעשו\"ת לתקן שא' יתוקן ע\"י זולתו והוא בחי' התיקון כידוע, ולכך נחרבה סדום שאין קיום לבחי' התוהו כמ\"ש לא לתוה\"ו ברא\"ה לשב\"ת יצר\"ה בבחי' התכללו' זה מזה להיו' כל א' נשלם ע\"י זולתו דוקא וע\"כ הארץ בכלל הרי היא בציור אד\"ם כמו עי\"ן הארץ טבו\"ר הארץ ערו\"ת הארץ פ\"י הארץ כידוע ומבואר במ\"א עמ\"ש אנכי עשיתי ארץ ואד\"ם עלי' בראתי כו'. ונמצא מובן דמלבד טעם דישות וגסות אי\"ן ומ\"ה ההפכיי' כנ\"ל, הנה עיקר בחי' התוהו והתיקון הוא שע\"י בחי' השלימות דכל א' או החסרון שנשלם ע\"י היפוכו ואמנם הכל עולה לסגנון א' דהיינו הך דכל שהוא בבחי' יש הוא רוצה בשלימות עצמו שלא יצטרך לקבל מזולתו, וכל שהוא בבחי' מ\"ה ואי\"ן רוצה ונמשך לקבל חסרונו ושפלותו לקטן"],[1900640268,"הימנו או היפוכו דוקא כענין נוחי' זה לזה כו' וכמשה שא' ת\"ר אלף אשר אנכ\"י בקרבו שזהו הראש מקבל מן הרג\"ל מפני שהי' עני\"ו מכל כו' כמ\"ש ונחנו מ\"ה, וכן ע' נפש דיעקב מתכללי' בד' מחנו' כאיש א' והיפך ע' אוה\"ע ענפין מתפרדין כו' להיו' שזה מבחי' התוהו דעשו איש אדו\"ם ויעקב מבחי' התיקון, והב' עניני' en.הנ\"ל נכללו בכללו' ענין התוהו ותיקון שזהו בחי' מ\"ה וב\"ן כמשי\"ת וד\"ל).\n<b>וזהו</b> כל עיקר בחי' התוהו והתיקון למעלה בהיות ידוע דכל בחי' התוהו הוא בבחי' ב\"ן דכל מלוכה הוא בבחי' שם ב\"ן ובז' מלכי' כתי' וימלו\"ך כו' שזהו בחי' יש ודבר מה דוקא והוא הסיבה שאינו יכול לסבול איזה דבר ויש זולתו כלל כמשל הנ\"ל בב' מלכי' ושרי' (או בענין הב' הנ\"ל שמצד השלימות בעצמו שלא ירצה לקבל מזולתו, והכל א' כנ\"ל), וע\"כ בחי' אורו' דעולם התוהו הן זת\"ז דוקא כנ\"ל (והוא מ\"ש בע\"ח דאורו' דתוהו תקיפי' וחזקי' ביותר עד שלא יכלו הכלים לסבול האור כו' וכמ\"ש במ\"א בענין המא' דאל יהא אדם קשה כארז אלא רך כקנה כו', והוא ענין טעם שלישי לענין ההפרש בין בחי' התוהו והתיקון דהיינו מפני שהתוקף והקושי כארז בלי ינוע לרוח היום מורה על היות העדר ההכנעה והביטול בעצמו כלל וכלל רק עומד בתקפו ובמעמדו במדותיו ושכלו ורצונו בלי יזוז ממקומו להיפוכו כלל, וההיפך הרכות כקנה שינוע לרוח היום מורה על בחי' הביטול וההכנעה במדו' שבלב ושכל ורצון להכלל בהיפוכו המנגדו בקל מאד כו', והכל עולה לענין א' שהוא בחי' האי\"ן ומ\"ה דתיקון או להיפך בחי' הישו' וגסות, וכן בהפרש שבין השלימות והחסרון ושפלות הנ\"ל דכל ג' אלה העניני' המכוון מהם א' הוא רק משוני' בלשון כו'), אבל בחי' התיקון הרי הע\"ס כלולי' זע\"ז בתכלית שיש להם אחדו' וחיבור עד מבלי שימצא ראש וסוף (דהראש מקבל מן הסוף שאין שלימו' לא' בלא זולתו) משא\"כ בחי' אורו' דתוהו נק' ענפי' מתפרדי' כו'). וזהו ההפרש בין בחי' מ\"ה לבחי' ב\"ן, דהנה אד\"ם גי' מ\"ה הוא בחי' התיקון כידוע (וכן האדמה וארץ כנ\"ל) והיינו בחי' שם מ\"ה מלגיו דאיהו ארח כל האצי' כידוע) והיינו כל סיבת בחי' האחדו' וחיבור הע\"ס דתיקון הוא ע\"י שם מ\"ה דוקא שזהו בחי' האי\"ן וביטו\"ל דמ\"ה שמצד שיש בחי' שם מ\"ה זה בכל אור מתכלל הוא בהיפוכו המנגדו (מטעם ג' משלי' הנ\"ל שעולין לענין א' כנ\"ל), וכענין עושה"],[1900640269,"השלום במרומיו בין מיכאל וגבריאל דגם שהמה ב' הפכי' בתכלית זה שר של אש וזה שר של מים ואין מכבי' זא\"ז כלל מפני שמתכללי' זה מזה והיו לאחדי' ממש, וכן למעלה בבחי' האצי' מתכללי' חו\"ג דאצי' אור החסד מאיר בכלי הגבו' ואור הגבו' בכלי החסד כו' כידוע בענין שם מ\"ב דק\"ש כו', וזהו רק ע\"י שם מ\"ה שמחבר כל ב' הפכי' וכמו עד\"מ ב' שרים גדולים בתכלית והן ב' הפכי' בתכלית כאשר יבאו לפני המלך שרם ומתנשא על שניהם כל א' מתבטל וניזוז ממקומו ע\"כ יוכלו להתאחד יחד כאילו לא הי' ביניהם פירוד כלל, והוא רק מצד בחי' הביטול שנק' מ\"ה כו' וכמו האחדו' וחיבור שימצא בבנ\"א שפלי' ונמוכי רוח כו' כנ\"ל (וכן ב' תלמידי' חלוקי' בדיעותיהם לב' הפכי' כאשר יבאו לפני רבם מפני שמתבטלי' שניהם מדעתם יתאחדו וישמעו לדעת רבם כו'), לפי שבחי' מ\"ה הוא בחי' האי\"ן היפך הישות לגמרי דהיינו שהוא בהעדר הרגשת עצמו מכל וכל כמ\"ש ונחנו מ\"ה כו' הוא ע\"י בחי' מ\"ה זה בא סיבת האחדו' והחיבור וההתכללו' גם בב' הפכי' ממש כנ\"ל. משא\"כ בחי' אורו' דתוהו הוא בבחי' שם ב\"ן שהוא כמו המלוכה שהיא בחי' יש לעצמו אנא אמלוך כנ\"ל אין להם אחדו' וחיבור כלל (כאש en.ומים שא\"א שיתחברו כלל, משא\"כ בבחי' התיקון א' טרף אש ומים ובללן כו').\n<b>ובכל</b> זה יובן ענין המא' דלעיל במ\"ש עד דלא הוה מתקלא, פי' מתקלא הוא בחי' שם מ\"ה מקור התיקון (כקו המאזנים ששוקל במשקל לא יכריע הא' על זולתו אלא מתכללי' כא' והוא בחי' קו המדה כו') שעושה בחי' ההתכללו' ואחדו' וחיבור להיו' כל א' כלול מהיפוכו המנגדו במשקל שוה כו' (כמו איה סופר איה שוקל כו'), לא הוו משגחי' אפין באפין פי' בבחי' התוהו שקודם לבחי' התיקון לא הוו כו' שלא הי' אז בחי' יחודי' עליוני' בע\"ס פב\"פ בכל ב' הפכי' דחו\"ג או בבחי' משפיע ומקבל, משום דהיחוד פב\"פ מורה עוצם בחי' האחדות וההתכללו' זה בזה בפנימי' שלהם דוקא שאין זה רק ע\"י בחי' שם מ\"ה דחכמה דוקא מטעם כל הנ\"ל, אבל עד דלא הוה בחי' מתקל\"א זה לא הוו משגחי' פב\"פ רק בבחי' אב\"א דהיינו שלא הי' היחוד וחיבור בב' הפכי' דחו\"ג או משפיע ומקבל עו\"ע רק בבחי' החיצוניו' ואחוריי' שלהם בלבד ולא הוו משגחי' אפי' באפין פב\"פ כלל, וזהו עד\"מ ב' מלכי' גדולי' שא\"א שיתחברו ויתאחדו יחד בבחי' הפנימי' שלהם שנק פב\"פ מצד שכל א' נבדל ביש ודבר בפ\"ע רק בבחי' חיצוניו' ידבר עם זולתו מן השפה ולחוץ לצאת י\"ח בלבד כו', משא\"כ באחדו' האמיתי כאשר יתחברו מצד שמקבלי'"],[1900640270,"זה מזה ומתכללי' זה מזה יחדיו יהיו תמים וידברו בבחי' פנימי' שבהם דוקא גם שהן ב' הפכי' (כמו במלאכי' דמקבלין דין מן דין כו' שכלולי' זה מזה וכמ\"ש בזוהר דכלילן דא ודא ושליבן דא בדא כו' וכידוע דגם המרכבה דפני ארי' ופני שור כו' וכן שאר חיו' ושרפי' ואופני' כולם מבחי' התיקון ע\"כ כולם מתאחדי' ומתחברי' יחד לשאת את הכסא כו' וד\"ל).\n<b>והנה</b> ראי' ברורה לכל ענין הזה במא' דעד דלא הוה מתקלא כו' הנה מזה יובן במה שמצינו בזמן בהמ\"ק שהיו כרובים וארון וכפרת כמ\"ש ועשית שנים כרובי' כו' וכתי' בהו ופניהם אי\"ש אל אחי\"ו דוקא דהיינו ענין משגחי' אפין באפין הנ\"ל ע\"י בחי' שם מ\"ה דתיקון, ומשחרב בהמ\"ק שחזר להיות בבחי' אב\"א ולא פב\"פ אין הכרובי' פניה\"ם אי\"ש אל אחי\"ו כו' וד\"ל (וביאור הדבר מבואר במ\"א ע\"פ מי יתנך כאח לי כו' דכנ\"י בגלות או' מי יתנך כאח לי כמו בזמן בהמ\"ק שהיו הכרובי' פניהם איש אל אחיו מפני שכנ\"י בזמן בהמ\"ק דוקא בא\"י למען בי\"ת כו' אז .en.. אחים שכנ\"י נק' אחים וריעי' כמ\"ש למען אחי כו' למען בית כו'. וביאור הענין הנה הכרובי' הן בחי' אנפי זוטרי כרבי\"א ואד\"ם הגדול היינו בחי' שם מ\"ה דחכמ' עילא' דהיינו בחי' אור אבא שרש כל האצי' ושרש מקור מחצב לכל נש\"י כמ\"ש כי אתה אבינ\"ו כידוע במ\"ש מ\"ה שמו מ\"ה שם בנ\"ו כו', ומלובש אור ח\"ע בלוחות העדות שבארון בי' הדברו' והכרובי' א' מימין הכפרת בחי' אור ישר להמשיך מבחי' ח\"ע דאד\"ם הגדול לבחי' ח\"ת שהוא בחי' רביא כמשל התינוק קטן ששכלו ומדותיו מצומצמי' והוא לבחי' מוחין דכנ\"י נשמו' בגופי' שנק' אנפי זוטרי והיינו הכרוב הב' שמצד השמאל (שהיו הכרובי' בציור דכר ונוק' כידוע), וזהו ופניהם איש אל אחי\"ו דוקא שהיו בתכלית היחוד והחיבור כדכר ונוק' כו' ונק' תרין ריעי' דלא מתפרשין והיינו לפי שאור ח\"ע מאיר בתמידו' ע\"י הכרוב הא' לכרוב הב' (רק שכרוב הב' הוא בבחי' אור חוזר בהעלא' לקבל והן בחי' העלא'"],[1900640271,"מ\"ן דכנ\"י כידוע) (וזהו והכרובי' פורשי' כנפי' וא' בזוהר דאקיש\"ו בגדפייה\"ו ג' זמנין ביומא והן ג' תפלו' דעכשיו בכל יום שעולין נש\"י לקבל אור ושפע מאביהם שבשמי' בבחי' הארת פנים דמ\"ה דח\"ע דאד\"ם העליון וכמ\"ש כמים הפנים כו' כן לב האד\"ם לאד\"ם, אד\"ם העליון דבחי' מ\"ה דאור אבא לאדם תתא' בחי' אנפי זוטרי שנק' נער והיינו כרוב\"י' כרבי\"א כנ\"ל, וכמ\"ש כי נער ישראל ואוהבהו וכמ\"ש מ\"ה שמו מ\"ה שם בנ\"ו דכנ\"י נק' בנים כו', ואמנם בבחי' יחוד הכרובי' נק' אחי\"ם וכמ\"ש למען אחי\"י כו' והיינו ופניהם אי\"ש אל אחי\"ו לפי שמקבלי' ממקור א' העליון והוא בחי' ח\"ע שבלוחו', ובחי' הכפר\"ת הוא בחי' כת\"ר דחכמ' שסובב על הארון בבחי' מקיף אך הכרובי' פורשי' כנפיהם על הכפרת בבחי' העלא' מ\"ן בג' תפלו' וכמו שרפי' עומדי' ממעל לו כו' וכה\"ג, והיינו ג\"כ ג' מועדי' פסח ושבועו' וסוכו' בכלל דכנ\"י עולין לרגל דכתי' ירא\"ה כל זכור\"ך את פני ה' כו' שכל זה הי' בכל יום ג' זמנין ביומא בכרובי' דאקישו גדפייהו ועתה הן ג' התפלו' כידוע שאז נק' כנ\"י אחים כו', והעיקר לכל אלה הוא הי' בזמן מ\"ת דכתי' בכנ\"י פב\"פ דיבר ה' עמכם פני אדם העליון (שנק' אדם קדמא' מ\"ה שמ\"ו כו') דהיינו בשעה שירד ה' ואמר אנכי וכו' דכתי' בי' חכמ' אד\"ם תאיר פני\"ו וכן אנו או' באו\"ר פני\"ך נתת לנו תורת חיים כו', שזהו בחי' אור פנים הגדול דאד\"ם הגדול דבחי' אד\"ם העליון כנ\"ל שהאיר לאנפי זוטרי שהן בנ\"י, עד שעל כל דיבור ודיבור פרחה נשמתן הרי קיבלו דברי אלקי' חיים פב\"פ מאור פני אד\"ם העליון, ונמצא שהיו אז בבחי' אחי' וריעי' להקדב\"ה כמ\"ש למען אחי וריעיי אדברה כו' וכמו בכרוב\"י' דכתי' בהו ופניהם איש אל אחיו דוקא לפי שמתכללי' המשפיע והמקבל והיו לאחדי' כמו ב' ריעי' האהובי' שיחודם תמידי כו' כמ\"ש כחדא שריין כו', ע\"כ בגלות אומרת כנ\"י מי יתנך כאח לי כמו במ\"ת שהי' מאיר בכנ\"י בבחי' פב\"פ ביחוד תמידי כאח ואחותו כו', משום דבגלות הוא להיפך כידוע דקודב\"ה בגלותא אסתלק לעילא"],[1900640272,"לעילא כמ\"ש ואנכי אסתי\"ר פנ\"י ביום ההוא וכן אלכה אשובה אל מקומי העצמי דאין העולם מקומו ולית מאן דתפיס בי' כו', וכנ\"י ירדה למטה ביותר עד היכלו' דק\"נ וכמ\"ש ובפשעיכם שולח\"ה אמכ\"ם דאתתא אתתרכא מבעלה כו' כידוע, והיינו שאו' מי יתנך כאח לי שיוחזרו כנ\"י פב\"פ כמ\"ש השיבנו ה' אליך, חדש ימינ\"ו כקדם כו' דמה שעכשיו יש יחוד זו\"נ או או\"א באמצעו' המצו' או ג' תפלו' וג' מועדי' בכלל ובכל שבת אינו רק בבחי' אב\"א ולא פב\"פ כידוע, וזהו שמבקשי' השיבנו כו' וכמו את פניך ה' אבקש להחזירם ביחוד פב\"פ כו', היפך מבזמן בהמ\"ק שהיו הכרובי' פניהם איש אל אחיו ומכ\"ש במ\"ת דבאור פני\"ך נתת לנו כו', ולזה אומרת כנ\"י שיש לה תקוה גם בזמן הגלות להיות כא\"ח לי כמו במ\"ת ובזמן בהמ\"ק ע\"י הכרובי' והוא במ\"ש יונק שדי אמי אנהגך כו' שזהו ע\"י מצות ת\"ת דוקא ובתשבע\"פ דוקא, דהנה ארז\"ל משחרב בהמ\"ק אין להקדב\"ה בעולמו רק ד\"א של הלכה בלבד, דקדקו לומר ד\"א של הלכה דוקא להיות שאנו או' ודבריו חיים וקיימי' שכל י' הדברות כמו שנאמרו בסיני חיים וקיימי' גם עתה להאיר בדבר ה' שהוא ההלכה שבתושבע\"פ דוקא, כי הנה ידוע דאוריי' מח\"ע נפק' היינו מח\"ע דאור אבא בחי' שם מ\"ה דא\"ק כנ\"ל כמו שהי' במ\"ת דחכמ' אד\"ם העליון תאי\"ר פני\"ו בשעה שדיבר י' הדברו', וכמ\"כ עתה מאירי' אותיו' דתשב\"כ באור פנים העליוני' דח\"ע דאד\"ם העליון לכל איש מישראל שקורא בתורה כמו שישראל קיבלו כל דיבור ודיבור בזמן מ\"ת ממש, מאחר שדברי\"ו חיי\"ם וקיימי' לעד בכל דור ובכל זמן כו' ולזה אנו אומרי' באור פניך נתת כו' ומברכי' נות\"ן התורה ל' הוה שגם עתה באור פניך נותן כו', וע\"כ אמרו מה להלן באימה וירא' ורתת כו' כך עתה ממש יוכל להיו' אותה האימה וירא' ורתת שהי' בזמן מ\"ת ממש, וידוע"],[1900640273,"דתשבע\"פ הוא בחי' מקבל האור מתשב\"כ והוא דבר ה' זו הלכ\"ה דוקא דשרש חכמ' דתשבע\"פ הוא בבחי' ח\"ת דהיינו כמו בחי' אנפי זוטרי שמקבל כנ\"ל בענין הכרובי', ע\"כ בכל דין והלכה מאיר מבחי' ח\"ע שבלוחו' כמו הארת אור ח\"ע שבלוחו' בכרובי' בזמן בהמ\"ק להאיר לכנ\"י, וזהו שא' שעכשיו ד\"א של הלכה דוקא במקום היכל ק\"ק שבד\"א של הלכה עכשיו מאיר מח\"ע דלוחו' העדו' כמו שהי' מאיר מאור ח\"ע שבלוחו' בהיכל ק\"ק בזמן בהמ\"ק ע\"י הכרובי' שמקבלים משם כנ\"ל, וא\"כ גם עכשיו מקבלי' כנ\"י בבחי' הארת פב\"פ כמו הכרובי' שהיו פניה\"ם איש אל אחי\"ו דוקא וכמו בזמן מ\"ת ממש דכתי' פב\"פ כו' כנ\"ל, והוא ע\"י לימוד תשבע\"פ כאשר שונה דבר ההלכה שבה שורה מאור פני אד\"ם העליון דבחי' מ\"ה דח\"ע בי' הדברו' הכוללי' כל תשב\"כ, וזהו שא' בכל מי שיושב ושונה הלכה שהקדב\"ה יושב ושונה כנגד\"ו פי' דוקא כנגד\"ו להאיר באור פנים העליוני' בח\"ע לח\"ת שבדבר הלכה זו ששונה כל איש מישראל למטה וכדוגמא דירא' כל זכורך לקבל אור פני אביהם שבשמים וכמ\"ש כשם שבא לראו' כו' וד\"ל. ונמצא דע\"י ג' תפלו' בכל יום בפרט דעכשיו וג' מועדי הוי' דירא' כל זכורך לקבל פני אביהם כו' בכלל וע\"י מצות ת\"ת בדיבור בתשבע\"פ שמקבל מתשב\"כ נחזרו כנ\"י בבחי' פב\"פ להיו' פניהם איש אל אחי\"ו כו', וזהו שאו' מי יתנ\"ך כא\"ח לי גם בזמן הגלות כמו בזמן בהמ\"ק ע\"י שאנהג\"ך אל בית אמ\"י דוקא שהוא להאיר מח\"ע דתשב\"כ לתשבע\"פ שנק' אמ\"י כו' שאז נק' כנ\"י אחי\"ם להיו' בבחי' פב\"פ כנ\"ל וד\"ל, ובכל זה יובן בתוס' ביאור ענין המא' דלעיל דעד דלא הווה מתקל\"א לא הוו משגחי' אפ\"י' באפי\"ן שע\"י אור ח\"ע דשם מ\"ה שנק' מתקלא שמאיר בתשבע\"פ כמ\"ש אי\"ה סופר איה שוקל כו' נחזרי' או\"א בבחי' אפין באפין משא\"כ בלא מתקלא כמו משחרב בהמ\"ק אינם בבחי' פב\"פ אלא בבחי' אב\"א וע\"י עסק התורה חוזרי' להיו' בבחי' פב\"פ גם אחר החורבן מטעם הנ\"ל וד\"ל).\n<b>ואחר</b> כל זה יובן ענין למרב\"ה המשר\"ה כו' דהנה פי' משר\"ה ל' שררה ומלוכה ומרבה המשרה הוא שעושה ריבוי השררו' ומלכות וא\"כ מה שייכות לכאורה לזה עם מ\"ש ולשלום אין קץ כנ\"ל. אך לפי כל הנ\"ל יובן דבאמת הא בהא תליא ממש דמשום דמרב\"ה המשר\"ה דשררו' ומלכות באין שיעור ע\"כ ולשלום אין קץ כו'. דהנה מבואר למעלה בענין מ\"ם דלמרב\"ה המשרה ל' מפעי\"ל שהוא מפעיל הריבוי בבחי' המל' והשררה להיות שכל מדה ומדה כלולה מי' וי' מי' עד ז' פעמי' ע\"כ יש ששה אלפי' רבבו' ספיראן כו', והיינו לפי אופן פרטי התחלקו' המדות כך יש ריבוי בחי' המל' בכל מדה וספי' בכל פרט ופרט שמתחלק, וזהו פי'"],[1900640274,"מרבה המשרה בחי' ריבוי המל' והשררה מצד שיש בחי' מל' בכל פרט כו' והמלוכה והשררה הוא בבחי' יש ודבר דוקא שהוא בחי' שם ב\"ן כנ\"ל, ועכ\"ז יש מספר קצוב והוא עד ו' אלפי' רבבו' שלמספר זה מתחלק וא\"כ יש ו' אלפי' רבבו' בחי מל' ושררה וא\"כ מהו למרבה המשרה ולשלום אין קץ, דאין קץ זה קאי על מרבה המשרה ג\"כ שאין קץ לריבוי המל' והשררה והרי יש קץ ושיעור שהוא ו' אלפי' רבבו' לבד (וכדוגמא שאמרו בשיעור קומה של יוצר בראשית כנ\"ל).\n<b>אך</b> הנה באמת הגם שמתחלק רק לו\"א רבבו', אין קץ לריבוי המל' והשררה. ושניהם אמת ויש להבין תחלה עפ\"י הנ\"ל בהפרש שבין בחי' התוה\"ו והתיקו\"ן שזהו בחי' שם מ\"ה וב\"ן בכלל ובפרט כו' דהיינו בחי' הי\"ש של כל מדה וספי' כאשר באה בבחי' גילוי המציאו' עכ\"פ הוא בחי' המל' בחי' ב\"ן אבל כל בחי' הט\"ס שבה הוא בחי' העצמיו' שלה כמו שהיא כלולה למעלה בעילה שלה נק' אין ומ\"ה כו', וכמו שמבואר למעלה באריכו' בענין ע\"ס בלי מ\"ה בלי מהות כלל דזהו בבחי' האי\"ן ומ\"ה דכל ספי' כמו שהיא כלולה באור העצמות, רק בחי' המל' שהוא בחי' ההתגלו' שלה בבחי' יש כחכמה במוח שבא בגילוי יש בענין פרטי וכן חסד בלב בדבר פרטי כו' הוא בחי' מל' דחכמ' ומל' דחסד ובדיבור הוא בא בבחי' גילוי דגילוי כו' שזהו בחי' בנין המל' מי\"ס דז\"א מבחי' המל' דכל ספי' כנ\"ל באריכות וד\"ל. והנה מבואר למעלה בבחי' התוהו והתיקון דמצד בחי' ב\"ן שהוא בחי' הישות של כל ספי' היינו כמו עד\"מ הישות של ב' מלכי' ושרי' שא\"א שיתחברו כו' עד שעושה תכלית הפירוד וההתחלקות, וזהו בחי' ע\"ס דבחי' ב\"ן דתוהו שהיו זת\"ז דוקא וימלוך וימ\"ת כו' והוא מה שא' דלא הוו משגחי' אפי' באפי' כנ\"ל באריכות, וא\"כ ממילא מובן שכל עיקר בחי' התיקון לתוהו הוא בחי' השלום שזהו בחי' האחדות והחיבור שנעשה בהם ע\"י בחי' שם מ\"ה דחכמ' דבחי' התיקון, דהיינו מפני שבחי' אי\"ן ומ\"ה דט\"ס דכל מדה הוא העושה תכלית האחדות והחיבור כנ\"ל באריכות וע\"כ גדול כחו של בחי' מ\"ה זה דתיקון לעשות בחי' האחדות והחיבור גם במה שהי' בתכלית הפירוד וההתחלקות שזהו עיקר השלום, דאין ענין השלום רק במקום מחלוקת דוקא ואם אין מחלוקת א\"צ לעשות שלום כלל, וגם כאן הרי בכל ט\"ס דכל מדה וספי' שבהן הארת שם מ\"ה דחכמ' בעצם שכלולי' בבחי' אי\"ן תמיד כנ\"ל א\"צ לעשות בהם שלום כלל, דאין שם מחלוקת ופירוד כלל אדרבה תמיד הן ביחוד וחיבור ואחדו' להיותם בטילי' מכל עצמותם וכלולי' במקורן בבחי' העדר הרגשת עצמותן מכל וכל, ונק' ע\"ס בלי מ\"ה בלי מהו\"ת כנ\"ל ע\"כ תמיד הן ביחוד עליון זע\"ז והיו לאחדי', וזהו ע\"י בחי' שם מ\"ה מלגיו כו' דמייחד לון ומקשר"],[1900640275,"לון כו' וכמבואר למעלה במשל יחוד וחיבור שבין ב' אנשי' שפילי רוח בעצם שמקבלי' ונוחי' זה מזה כו', או כמשל שבאין לפני הגדול משניהם יחד כמו לפני מלך שגם שכל א' יש גדול מתבטלי' ממציאותם ונעשה שלום ביניהם כמיכאל וגבריאל אש ומים ואין מכבי' זא\"ז וכה\"ג, והרי במשלי' אלו יש הפרש גדול דבבחי' אי\"ן ומ\"ה בעצם כשפילי רוח או שחסירי' בעצם וצריכי' לקבל זה מזה וכנ\"ל בב' אופני' הללו שהן עולי' למכוון א' כו' אינו נק' שלום כי הרי מתאחדי' מצד עצמם ואין כאן מחלוקת ופירוד שיצטרך לשלום, אבל אופן הג' שהוא כמשל ב' מלכי' או ב' תלמידי' שהן בבחי' יש גדול בפ\"ע מפורדי' בתכלי' דכל ישות עושה תכלית, שם צריך לעשות שלום והוא כמו אש ומים דמיכאל וגבריאל דכתי' עושה השלו\"ם במרומיו שצריך לעשות שלום ביניהן, וענין השלום הזה הוא לעשות בחי' ביטול הי\"ש לאי\"ן בכל א' במה שמתבטל ממציאותו בהגיעו לאור העליון ממנו הרבה הנה זהו הנק' בחי' המשכת הביטול דבחי' מ\"ה העליון לעשות הביטול ואי\"ן גם בבחי' הישו\"ת והפירוד שזהו כמו ב' שרי' שמתבטלי' מכח אימת המלך וכהנ\"ל, וכך יובן בבחי' יש הוא בחי' ב\"ן דכל ספי' שהוא בחי' המל' שמחמת זה לא יחוברו ב' הפכי' כלל צריך להאיר עליהם מבחי' מ\"ה דחכמ' לעשו' ביש שלהם בחי' הביטו\"ל לאי\"ן ליכלל במקור חוצבם בעצמו' המאציל לפי שכל א' אינו סובל לזולתו ההפכי וצריך לייחדם ולחברם ע\"י הארת שם מ\"ה דתיקון (שזהו ג\"כ ענין הארת שם מ\"ה מלגיו דאיהו ארח כל האצי' כמו להאיר אור החסד בכלי הגבו' כו'), וזהו אנת דמייחד לון גם בבחי' הפירוד וההתחלקו' דבחי' ב\"ן דכל ספי' שזהו הנק' שלום שנעשה במקום מחלוקת דוקא, וכמו למען אחיי וריעיי אדברה נא שלו\"ם ב\"ך בכ\"ב אותיו' דמל' לפי שעיקר מעשה השלום אינו אלא במקום מחלוקת שהוא בבחי' ריבוי התחלקו' אותיו' דבחי' מל' בכל פרט ופרט דט\"ס דז\"א כנ\"ל באריכות. וזהו יעשה שלו\"ם לי שלום יעשה לי ב' שלימות א' שלום בפשמ\"ע באו\"כ דזו\"נ דאצי' שמתחלקי' עד ששה אלפי' רבבו' כו' כנ\"ל, שכל אלה נעשה בהן בחי' היחוד וההתכללו' ע\"י בחי' שם מ\"ה דאיהו ארח כל האצי' שקיו דאילנא כו', ושלום בפשמ\"ט בבי\"ע שהן כמו מלאכי' דבריא' שהן ב' הפכי' כמיכאל וגבריאל וכן פני ארי' ופני שור כו', והרי אנו רואי' שכלולי' זה מזה בתכלית היחוד וכמ\"ש ומקבלי' דין מן דין וכל זה נעשה מבחי' שלום דשם מ\"ה בע\"ס דבי\"ע שנמשך ומקבל משלום העליון דבחי' מ\"ה דזו\"נ דאצי' ע\"י הארת בחי' יסוד דז\"א במל' שנק' ברית שלום, ומיסוד דמל' בבי\"ע וכידוע בענין וידעת כי שלום"],[1900640276,"אהלך, וזהו אדבר\"ה שלו\"ם העליון בך וד\"ל. ובכל זה מובן מ\"ש למרב\"ה המשר\"ה ולשלום אין קץ משום דבחי' ריבוי המל' והשררה שזהו בחי' ב\"ן בחי' יש דכל ספי' דאצי' כמו בחי' ב\"ן דע\"ס דתוהו עושה תכלית הפירוד וההתחלקות מטעם הנ\"ל, וצריך לעשות שלום שהוא להיו' בחי' ביטול היש לאין ע\"י בחי' שם מ\"ה שמברר לב\"ן כו' שזהו הנק' בחי' שלו\"ם בפשמ\"ע ובפשמ\"ט כנ\"ל, וז\"ש למרב\"ה המשר\"ה en.וגם בהתחלקות רבות מרבה השלו\"ם ואחדות ביניהם כנ\"ל וד\"ל.\n<b>(אך</b> הנה עדיין יש להבין בענין זה דלמה צריך לבחי' השלו\"ם לעשו' מבחי' היש לאין מהארת שם מ\"ה החדש שהוא בחי' מקור התיקון (והוא הנק' מתקל\"א שמחזיר להיו' אפי' באפי' כנ\"ל), הלא בכל ספי' וספי' עצמה יש מבחי' מ\"ה ואי\"ן בט\"ס שבה שעולין וכלולי' למעלה בעילה שלו שמצד זה מתייחדי' ומתכללי' זע\"ז וא\"צ לעשו' שלום כלל כנ\"ל ואיך יגבר הי\"ש על האי\"ן בכל ספי' כו'. אמנם הנה באמת צריך להבין בעיקר ענין התוהו והתיקון הנ\"ל דלכאורה אנו מוצאי' להיפך מכל הנ\"ל דבחי' אורו' דתוהו הי' בבחי' הגבורו' בהסתלקות והתכללו' במאצילן ביותר ע\"כ לא יכלו הכלים לסבול האור וירדו ונשברו כו' כידוע וא\"כ נהפוך הוא שבאורו' דתוהו הי' יותר מבחי' האי\"ן ומ\"ה מבחי' התיקון ולמעלה מבואר דסיבת שבירת הז' מלכי' הי' מבחי' ב\"ן שהי' בבחי' י\"ש, וגם זה אמת כידוע דז\"מ הן בבחי' ב\"ן שהוא בחי' היש דוקא, וע\"כ בהכרח צריך לומר דשניהם אמת וא\"כ איך יובן עיקר בחי' התיקון שהוא בבחי' שם מ\"ה דוקא.\n<b>אך</b> הנה יש להקדים לזה ענין א' המבואר במ\"א (ע\"פ ויצר ה' אלקי' האדם עפר מן האדמה כו') בשרש ענין התוהו והתיקון באופן אחר, והוא דכל בחי' ע\"ס דתוהו הי' בהן ריבוי האור בבחי' אי\"ן והתכללו' דוקא כנ\"ל וע\"כ לא הי' כלי מכיל לאור כו', ועיקר ענין התיקון היינו בחי' התיישבות האור בכלי במזג נכון עפ\"י מא' קו המדה (שהוא המתקלא הנ\"ל), וזהו כל עיקר בריא' האדם בשביל ביטול הי\"ש לאי\"ן בבחי' התכללו' דאור וכלי יחד במדה ושיעור דוקא כמ\"ש לכבוד\"י בראתיו כו', ולזה ניתן לאדם גוף חומרי עפר מן האדמה יותר מן המלאכי' שהוא בחי' הישות הגס ביותר להיותו לפי ערך גודל מעלת בחי' האין דנשמתו שלמעלה מהמלאכי' כו'."],[1900640277,"<b>ויובן</b> זה בהקדים תחלה ענין האור והכלי שהן ב' הפכי' בתכלית, להיות ידוע בעיקר בחי' אור וכלי שזהו בחי' אי\"ן וי\"ש דהאור הוא בבחי' אי\"ן דוקא והכלי הוא בבחי' י\"ש דוקא שהן ב' הפכי' כו'. וביאור הענין ידוע דכל עיקר בחי' אור הוא כמו אור המאיר ממקורו שנכלל ועולה תמיד במקורו ואין לו התיישבו' בפ\"ע כלל כאור הנר שמסתלק לולי הפתילה שמושכת להדליקה כו', וכך כל בחי' אור האלקי העליון שהוא בחי' הארה אלקי' המתפשטת ממקורה העצמי מאחר שנמשך מן העצמות תמיד עולה ונכלל בבחי' אי\"ן האלקי במקור חוצבו בביטול תמידי בלי הפסק כלל כנר ה' נשמת אדם שטבע רוח האדם לעלות למעלה תמיד כידוע, והכלי הוא היפך זה ממש והוא כמו הפתילה שמושך האור שיתאחז בו ויאיר למטה בהתפשטו' ויריד' ועד\"מ כלי המוח באדם כשמוכשר ומוכן לקבל צורת אור השכל, אע\"פ שמצד בחי' אור השכל הרי מושלל לגמרי מהיות בבחי' יש ומציא' התחכמו' דבר מה כי עולה ונכלל במקורו בבחי' כח המשכיל ההיולי שבעצם הנפש מאחר שמאיר משם, רק סיבת המשכתו וירידתו להתאחז ולשרות במוח הוא בא מצד בחי' חומר כלי המוח כאשר הוכן מאד לקבל ימשיך ויגביל לאור השכל בתוכו ועושה אותו בבחי' יש ומציא' דבר התחכמו' כו' ונעשה נבדל מן העצם שלו שהוא רק בבחי' אי\"ן והתכללו' במקורו בכח המשכיל כו', וזהו שאור החכמ' בהיותו בכלי דוקא נק' חכמ\"ה בה\"א בבחי' יש ודבר מה והוא בענין של חכמ' שמתחבר בכלי מוח החכמ', אבל קודם ששורה בכלי אינו נק' בשם חכמ\"ה בה\"א (רק שם חכ\"ם בעצם על שיש בכחו להתחכם כשירצה לייגע בכלי מוח החכמ' כו'), וכן ל' בינ\"ה בה\"א הוא אור הבינה בכלי המיוחד דבינה, וכן גדול\"ה וגבור\"ה כו' חו\"ג שבכלי הלב דוקא וכהנ\"ל בכל הע\"ס כשהן אורו' בכלים, וז\"ש חכמ\"ה מוח\"א כו' וד\"ל.\n<b>ומובן</b> לפ\"ז דבחי' האורו' והכלים הן ב' הפכי' בתכלית, האור בבחי' אי\"ן וביטול למעלה והכלי הוא בבחי' יש נפרד למטה דוקא וא\"כ לא יובן כלל איך יתחבר האור בכלי ואנו רואי' שיתחברו ויתאחדו ביותר. אלא צריך לומר שיחודם בא ע\"י בחי' אמצעי שכלול מב' הפכי' שלהם, וענין הממוצע הזה היינו שיש בכלי מבחי' האור והוא בחי' הביטול וההתכללו' מי\"ש לאי\"ן כטבע האור ויהי' באור מבחי' הכלי דוקא היינו שיומשך מאי\"ן שלו להיו' בבחי' יש והתפשטו' למטה, והיינו שהאור והכלי מחליפי' טבעם ועושי' כל א' פעולת זולתו ההפכי דוקא אז יוכלו להתכלל יחד שמצד בחי' התכללו' שכלול א' מבחי' מנגדו יוכלו להתייחד כא' ממש, כמו אש ומים מצד עצמם שהם ב' הפכי' א\"א שיתחברו כלל אבל"],[1900640278,"אם האש יורכב בחלקי המים והמים מחלקי האש יבאו בגוף א' כידוע בס' הטבע (וכן למעלה טרף אש ומים ובלל\"ן משום שהוציא מים מאש ואש ממים דוקא), וכמו האור בפתילה כל זמן שגוף הפתילה קיימת לגמרי בלתי נשרפת כלל אין האור נאחז בה כלל אלא מסתלק מיד ואם נשרפה לגמרי ג\"כ אין האור נאחז כי אין לו במה להתאחז רק כאשר כלה ונשרפת מעט מעט ליכלל באור אז האור והשלהבת נמשך ומתאחד בה זמן רב להאיר ולהדליק כו', ונמצא האור עושה דבר היפוכו שהוא לירד ולהתמשך ולהתאחד בפתילה שזהו מאי\"ן ליש לפי שהפתילה עושה דבר היפוכה כטבע האור והוא הכליון והתכללו' באור הדולק כו', וכדוגמא זו אנו רואי' בצמיחה שכאשר החטה בשלימותה בעפר הארץ בלי רקבון כלל לא יומשך בה כח הצומח כלל ובביטול ישותה וגסותה ליכלל בכח הצומח שהוא הרקבון שנהפך מי\"ש לאי\"ן דכח הצומח יעשה גם הוא דבר היפוכו להתמשך בחטה להצמיח' שזהו מאי\"ן לי\"ש והוא בחי' התכללו' דבר מהיפוכו שגורם התולדה וריבוי (וכן בזיווג גשמי דמ\"ן דנוק' עושה היפוכו בביטול ותשוק' והמ\"ד יורד כו' וזהו אשה כי תזריע כו'), וכן טפה המוליד אינו אלא כשתסרח ותקלט וכידוע ביצירת האפרוח וכהנ\"ל וכן בדם הוא הנפש שאין המשכת רוחניו' דאור וחיו' הנפש בכלי איברי הגוף מאי\"ן לי\"ש כ\"א ע\"י ביטול הי\"ש לאי\"ן מד\"ם שנעשה מן המאכ\"ל וכל\"ה ונכל\"ל באור וחיו' הנפש כו' וד\"ל.\n<b>והדוגמא</b> מכל זה יובן מכל המשלי' הנ\"ל למעלה בעיקר בחי' התיקון שהוא בחי' התכללו' דאו\"כ שכל א' תופס מדרגת זולתו המנגדו, דהיינו שהכלי נעש' בבחי' ביטול הי\"ש לאין ומתכללת באור הגם שמצד עצם מהותה היא דוקא בבחי' יש נעשי' בבחי' ביטול הי\"ש שזהו במדרג' מהו' האור, והאור גם שטבעו לעלו' נעשה בבחי' י\"ש שהוא בטבע הכלי לירד ולימשך למטה כנ\"ל. ואמנם הנה זה עצמו שיהי' הכלי בביטול היש לאין והאור יומשך מאין ליש צריך שיהי' במזג נכון במדה ושיעור ומשקל יפה אזי דוקא מתיישב האור בכלי ומתקיים בו, אבל אם לא נעשה ההתכללו' במדה נכונה ממוצעת כ\"כ כפי הראוי חזר הדבר לבלתי קיום ואין התיקון כלום. וענין המדה הנכונה היינו שלא יוסיף ולא יגרע בין בביטול הכלי לאי\"ן ובין בהמשכת האור ליש שיהי' לפי ערך דוקא דהיינו שלא יהי' ביטול היש דכלי יותר מכפי ערך ההמשכה מאי\"ן ליש דאור, וכן"],[1900640279,"להיפך שלא יהי' ההמשכה מאין ליש דאור יותר מערך הביטול דיש דכלי לאור אלא יהי' במזג נכון לפי ערך לבד, וזהו המדה הקצובה באופן ההתכללו' דכלי ואור הנ\"ל וכ\"ש שלא יהי' בעצם האור ביותר מן המדה מבחי' האי\"ן ובכלי הוא בחי' יש גמור ובמיעוט ביטול היש שאז אין הכלי מכיל האור כלל וקופץ האור ומסתלק כמשל הפתילה שקיימ' בישותה והאור גובר לעלות שאז בלתי מתיישב האור בפתילה כלל, וכן להיפך כשהפתילה כלה ונשרפת לגמרי באור שאז האור ג\"כ מסתלק, דהיינו אם הכלי בביטול היש ביותר והאור גובר לעלו' באי\"ן שהוא מסתלק כו', ולהיפך גם כשהעץ גס ועב ולח והאור מתגבר ונמשך אחריו להדליקו וכמו הפתילה שמשוחה בשמן טוב שהאור נמשך אחריו ביותר והיא קיימת בגסותה מצד לחלוחי' השמן כו' אז יומשך הדלקתו זמן רב ויומשך באין שיעור להתפשטותו, והדוגמא מזה הוא באו\"כ כאשר הכלי בבחי' יש גמור ואין בה ביטול היש כלל וגם האור נמשך מאי\"ן ליש ביתר מכפי המדה אזי נמשך ויורד למטה מטה עד שיומשך בחיצוני' בחי' מותרות שפע רב כו'.\n<b>ונמצא</b> ד' אופני' יש לגריעותא, א' כשהאור בתכלית האי\"ן והכלי בתכלית היש שא\"א שיתחברו כלל כאש הקופץ מן הפתילה הגסה כו', והב' קצה הב' כשהכלי בתכלית היש והיש דומה לאור בבחי' ביטו\"ל לאי\"ן לגמרי כמו כליון הפתילה לגמרי גם זה גורם הסתלקו' האור, והג' כשהאור נמשך ביש דכלי ובכלי יש ביטול היש במדה דוקא עד שמזוג במזיגה נכונה ואם אינו במזג נכון אינו מתקיים היינו שלא יהי' המשכה דאין ליש דאור רק לפי ערך ביטול היש דכלי כנ\"ל, ויש בזה ב' אופני' לגריעותא, א' אם יש ביטול היש דכלי ביותר מכפי ערך ההמשכה דאי\"ן ליש דאור אין האור מתיישב בכלי (וכמשי\"ת שתפלתו יותר מתורתו בענין רו\"ש דתור' ותפלה), והב' אם אין ביטל היש דכלי לפי ערך המשכת האי\"ן דאור בכלי ג\"כ אין האור מתקיים בכלי שאין לו כלי בית קיבול ליכנס בו להיותו בישותו (כמיעוט הביטו\"ל י\"ש בתפלה וריבוי עסק התו' כמשי\"ת), והד' הקצה האחרון לגריעותא שהאור נמשך ביותר ליש והכלי הוא בחי' יש גמור כמו העץ הלח שהאש נמשך אחריו כנ\"ל גורם הירידה בתכלית היפך העלי' בתכלית כשהכלי בתכלית הביטול דישותו והאור ג\"כ בתכלית האי\"ן לעלו' en.כנ\"ל וד\"ל.\n<b>והנה</b> כל ד' אופני' לגריעותא ימצא הכל בבחי' אורות דתוהו וענין שביר' הכלי' דאורו' דתוהו, דמה שאנו מוצאי' באורו' דתוהו שהיו במדרג' עליונה יותר מאורו' דתיקון ונק' אורות תקיפי' וחזקי' כו' שהן מבחי' הגבורו' עליונו' מאד כו' היינו שהי' בהן בחי' הביטול והתכללו' דאי\"ן ליכלל במאצילן בתכלית ההתגברו', אך בחי' המל' דכל ספי' שלהם שהוא בחי' הי\"ש דכלי הי' בבחי' יש שהוא בחי' המלוכה בחי' ב\"ן ולא הי' בכלי בחי' ביטול היש לאי\"ן כ\"כ לפי ערך גודל האי\"ן דאו\"ר שאור דתוהו הי' בבחי' הביטול ואין יותר מדאי, ע\"כ לא הי' כלי היש דבחי' מל' מכיל את האור כלל להיות שאין בו ביטול כ\"כ לקבל גילוי אין כ\"כ ולכך"],[1900640280,"נפלו הכלים ונשברו לפי שממילא יסתלק האור למעלה כמו אור הקופץ מן הפתילה שבלתי כלה כו' כנ\"ל, וזהו עיקר ענין סיבת השבירה בכלים דתוהו לפי שלא הי' הכלי בבחי' ביטול לאי\"ן כ\"כ לפי ערך בחי' האין דאו\"ר שהיו עולין ונכללי' במאציל בהתגברו' הביטול וההתכללו' כידוע בע\"ח וד\"ל, והב' להיפך כשהכלי בתכלית ביטול היש יותר מדאי כמו האור ויותר מערך בחי' האי\"ן דאור שזה ג\"כ בלתי מתקיים (והן נשמו' הגבוהו' שמבחי' ב\"ן דתוהו שעלו למעלה עם בחי' הכלי דוקא כחנוך ואליהו שעלו בגופם למעלה מפני שנתגבר בכלי גופם בחי' הביטול אלקי לאי\"ן יותר מבחי' אי\"ן דנשמ' כו', ובמשה הי' נשמתו מבחי' אי\"ן ומ\"ה ביותר וכלי גופו בביטול הי\"ש לאי\"ן דוקא לפי ערך בחי' המ\"ה דנשמ' שזהו עיקר בחי' התיקון כנ\"ל), וכמשל הפתילה שכלה לגמרי כנ\"ל, וזה הי' ג\"כ בבחי' כלים דתוהו שרק רפ\"ח ניצוצו' נפלו והשאר עלו כו' וד\"ל, והג' באופן שיעור ומדה בעיקר התכללו' דתיקון והוא שבא לשער במדה כמה יהי' ההמשכה מאין ליש דאור וכמה יהי' ביטול הי\"ש לאי\"ן דכלי ואין תיקון אלא בשם מ\"ה שמתקן ומברר לב\"ן דתוהו שיהי' הביטול במדה כנ\"ל שלא יוסיף כל א' לעשות פעולת מנגדו ולא יגרע רק כפי הצריך וזה בענין היפוך מענין מדידה דאור וכלי בעצם הנ\"ל.\n<b>דנמצא</b> ב' מיני תיקון הם, א' בעצם האו\"כ שהוא אי\"ן דאור בעצם שלא יגבר על יש דכלי ולא יגרע אור דאי\"ן אלא כפי הצריך כפי ערך הי\"ש דכלי לבד, וכן הי\"ש דכלי לא יהי' רק לפי ערך האי\"ן דאור לא יוסיף להיו' בבחי' יש ולא יגרע רק כפי הצריך לערך האי\"ן דאור לבד כנ\"ל, והתיקון הב' הוא בהיפוך פעולתם כאשר האור פועל פעולת הכלי לימשך מאין ליש והכלי עושה פעולת האור בבחי' ביטול היש לאין שיהי' גם בזה בחי' התכללו' במזג ומדה שלא יוסיף ולא יגרע בפעולת כל א' מהיפוכו רק לפי ערך, היינו שלא יהי' ביטול הי\"ש לאי\"ן דכלי רק לפי הצריך לפי ערך פעולת האור לימשך מאי\"ן לי\"ש ולא יגבר בחי' ביטול יש דכלי יותר שאינו לפי המדה דאור בפעולתו מאין ליש שאז יסתלק האור כי יוסיף הכלי כח הביטול דאי\"ן דאו\"ר, וכן לא יגרע הכלי הביטול דיש ביותר שאז יתוסף ההמשכה ליש ביותר מצד האור שנמשך ליש ביותר והכלי תוסיף כח להמשיכו ליש שזהו עושה עוצם יריד' והמשכה למטה ביותר, שזהו מדרג' הד' הגרוע מכל, שהוא שהאור נמשך מאין ליש ביותר מדאי וגם הכלי אין בה בחי' ביטול היש כלל שאז זה וזה גורם יחדיו יהיו מכווני' להמשיך לבחי' יש"],[1900640281,"גמור ונפרד לגמרי במדרג' תחתונה ביותר (כמו הנפיל\"י' כו' ששרש הנפיל\"י' מבחי' התוהו שנק' אנש\"י הש\"ם דבחי' שם ב\"ן שנפלו בשה\"כ כו'. והענין הוא דרפ\"ח ניצוצי' שנפלו היינו שנמשכו לבחי' יש ביותר והכלי גם היא בלי ביטול היש כלל ע\"כ זו\"ז גורם שירדו ונפלו בתחתית המדרג' ביותר, והן הנק' נפילי\"ם המה הגבורי' מגבו' עליונו' דב\"ן דתוהו אשר מעול\"ם אנשי הש\"ם כידוע, ודוגמא לזה היינו כמו נשמו' גבוהו' שנפלו למטה בגופי' גסי' מאד שהן כמו עז\"י פני\"ם שנק' תקיפ\"י דר\"א שלבם קשה כאבן לא יכנע לבבו לפני ה' כלל בשום דבר כו' להיותם בתכלית הגסו' והפירוד ליש מפני ששרשם הוא מאורו' תקיפי' וחזקי' דתוהו דוקא, ובנפילתם למטה בק\"נ הן הגבורי' כו' כנמרוד גבור ציד כו', והן בנ\"י האלקי' שירדו למטה שנמשך האור גם הוא ברע גמור מטעם הנ\"ל, וזהו היפך גמור מביטול גוף דחנוך ואליהו הנ\"ל וד\"ל). ולזה יש חילוק בין רשעי' גמורי' שעושי' תשוב' לפרקי' לאותן שאינן עושי' תשוב' לעולם כו'). אבל לתקן ד' אופני' הנ\"ל היינו עיקר בחי' התיקון בב' דברי', א' באי\"ן וי\"ש בעצם שלפי ערך האי\"ן דאור בעצם יהי' בחי' יש דכלי כו' כנ\"ל.\n<b>ויובן</b> זה בנשמו' שבגופי' כידוע שיש בחי' מ\"ה וב\"ן בכל אדם למטה, והיינו הנשמה הוא בחי' מ\"ה והגוף הוא בחי' ב\"ן, דמ\"ה גי' אד\"ם וב\"ן גי' בהמה וכמ\"ש וזרעתי ב\"י זרע אד\"ם וזרע בהמ\"ה, ויש בהרכבה זאת דנשמה בגוף שנק' מ\"ה וב\"ן אור וכלי שהוא בחי' אי\"ן וי\"ש הנ\"ל כל ד' אופני' הנ\"ל, א' שהנשמה בשרשה מבחי' אי\"ן האלקי במעלה יתירה והוא מה שתיכף יתפעל במוחו בגדולת ה' ומתבט\"ל לאי\"ן האלק\"י בנקל מאד בעומק גדולתו, שזהו בחי' מ\"ה דאד\"ם שבנשמתו במדרג' עליונה ביותר, ואמנם גופו שהוא הנה\"ט שנמשכה ע\"י תאות הזיוג דאב ואם שנק' בהמ\"ה ששרשה מהיכלו' דק\"נ היא גסה ביותר והיינו בכל מדו' רעות ובלי ביטול היש כלל שלא יכול לכבוש לבו בכל תאוה כו' עד שלבו קשה ומטומטם כאבן כו', שזהו כמו אור הקופץ מן הפתילה הגסה שבלתי כלה ונשרפ' כלל כנ\"ל (וכאורו' דתוהו שהי' בהן בחי' אי\"ן ביותר והכלי בלי ביטול היש שלא יכילו הכלי ונשבר כו'), והב' להיפך מן הקצה שגופו בחי' ב\"ן גי' בהמ\"ה הוא בבחי' ביטול הי\"ש בקל מאד, כמו מי שלבו ר\"ך כקנ\"ה לשוב בתשו' תמיד בהכנעה אמיתי' וברוח נשברה מאד, וגם בעבודה שבלב בתפלה מיד יתפעל לבו הטבעי גם הוא להבטל לפני ה' יותר כהתפעלו' אור דנשמ' בבחי' מ\"ה ואי\"ן בעצם"],[1900640282,"כו' שזה ג\"כ בלתי מתקיים שהאור דנשמ' אין לה במה להתיישב כאור בפתילה שכלה לגמרי כו' (וכחנוך ואליהו כנ\"ל), והג' (שיש מדה ושיעור קצוב בביטול היש לאין דגופו ובהיפוך בהמשכה דאי\"ן ומ\"ה דנשמ' בבחי' יש ית' בסמוך) כאשר הנשמ' אינה בבחי' אי\"ן ומ\"ה כ\"כ בעצם שרשה וגם הגוף אינו בביטול היש כ\"כ אלא בגדר ממוצע שהי\"ש לפי ערך האין בערך שיוכל האי\"ן ומ\"ה דנשמ' להפוך ולבטל היש דגוף, שאם הי' בנשמ' גרעון אור דמ\"ה ובמיעוט שאינו לפי ערך גסו' היש עד שאין בכח מ\"ה דנשמ' להפוך היש דגוף אזי יפול הנופל כו', ולהיפך כשיש ביטול בגוף יותר מערך האי\"ן ומ\"ה דנשמ' כנשמ' נמוכה בגוף קדוש או להיפך נשמ' גבוה ודק בגוף טמא וגס בלתי מתקיים אם אינו לפי ערך רק שיאיר אור דאי\"ן בי\"ש לפי המדה שיוכל שאת דוקא, עד שיוכל להיות מדה ושיעור גם למן הקצה לקצה דהיינו לנשמה גבוה ביותר נותנין לה גוף גס ביותר שבערך מעלת בחי' אי\"ן האלקי שבנשמ' להפוך חושך הגס כזה לאור ואם אין בכחה כ\"כ אין נותנין לה גוף גס כ\"כ, וכן להיפך לנשמה שפילה ביותר שבחי' אי\"ן אלקי שבה במיעוט האור ביותר בהכרח שיותן לה גוף דק ונקי שיהי' בכח מ\"ה שבנשמ' להפוך חושך לאור שאם יהי' לה גוף גס ביותר יפול בתכלית הנפילה כי אור דמ\"ה מצומצם ביותר והגוף גס ועב ימשיכנו לכבות אורה לגמרי (וכחלוקה הד' דלעיל שנז' בנפיל\"י' שהאי\"ן נמשך לי\"ש ביותר והכלי יש גמור כו'), וזהו המדרג' הד' שהנשמ' שפילה והגוף שפל וגס שיש תרתי לריעותא (והן כמו נש\"י עכשיו בעקב\"ו' משיחא דהנשמו' שפילו' במיעוט היותר אחרון דבחי' מ\"ה ואין דנשמ' גם בראשי הדור כו', וגם הגופי' רחוקי' יותר מן הביטו\"ל לאי\"ן מדורו' הראשונו' שהרי הראשוני' היו חוזרי' בתשוב' ברוח נשברה במעט התעוררו' מלמעלה משא\"כ עכשיו שלא יועיל שום התעוררו' עד שהן כישיני עפר וכו' וד\"ל, משא\"כ דורו של משה ובזמן דוד ושלמה הי' להיפך שהיו נשמו' דבחי' מ\"ה דחכמ' ברא\"ש והכלי שהן הגופי' היו קרובי' לביטו\"ל דאי\"ן האלקי יותר מנשמו' דעכשיו, דבחי' ב\"ן שבעליון הרבה גבוה הוא מבחי' מ\"ה שבתחתון, דב\"ן ומ\"ה אי\"ן וי\"ש ישנם בכל פרצוף אדם במוח ולב ומעשה שהן חב\"ד חג\"ת נה\"י כידוע, וא\"כ מה שנק' בחי' ב\"ן בחב\"ד נעשה בחי' מ\"ה במדו' ועד\"ז ממדו' למעשה שהוא בחי' נה\"י כו', עד שזרע בהמ' דאד\"ם שבמוח חכמ' בראש יותר גבוה מזרע אד\"ם בחי' מ\"ה דנשמו' שבעקביי' וד\"ל (וראי' לזה ממ\"ש אנו כחמורי' ולא כחמורו כו', דחמורו של רפב\"י הי' מן הבהמו' בהררי אלף שקודם חטא עה\"ד טו\"ר שלא הי' בו שום רע, ואע\"פ שהי' חמור לא הי' גופו נטמא ונכשל בשום דבר רע ממילא, ונשמו' שבעה\"ד טו\"ר אע\"פ שמבררי' לגופ\"ם בחי' ב\"ן גי' בהמה אינם כחמורו של רפב\"י"],[1900640283,"שהרי אכלו גופם שאינו מעושר כו', והיינו שרמזו דגם בחי' מ\"ה דנפשם האלקי המברר ב\"ן אינו מגיע למעלת בחי' ב\"ן גי' בהמה שלפני חט\"א עה\"ד כו') וד\"ל.\n<b>והנה</b> בחי' תיקון הב' הוא בענין ההתכללו' דאו\"כ באי\"ן וי\"ש דאו\"כ שמתחלפי' כנ\"ל דהיינו שיש שיעור ומדה בביטול יש הכלי לאור ובהמשכה וירידה דאור בבחי' מאי\"ן לי\"ש כו' כנ\"ל. ויובן זה בבחי' עבודה שבלב באוי\"ר שנק' רו\"ש והוא במלאכי' שנא' בהן והחיו' רו\"ש שכלולי' מב' הפכי' הללו במדה ושיעור דוקא כנ\"ל שהרי המלאכי' הן מבחי' התיקון דכלילן דא מדא כנ\"ל. וזהו אנו מוצאי' גם למטה בענין תורה ותפלה שהן כמו ב' הפכי', דהנה ידוע שהתפלה היא בבחי' רצוא שזהו בחי' הביטול דיש לאי\"ן בהתפעלו' אהבה ותשוקה ליכלל נפשו באחד כו' שנק' הזזה ממקומו כענין צמאה לך נפשי כו', והתור' הוא בבחי' שוב שהוא היפך זה ממש כי עיקר מצות ת\"ת הוא להמשיך אור אלקי בדבר ה' זו הלכה שזהו ההמשכה מאין האלקי בבחי' י\"ש דוקא בבחי' ירידה והתלבשות בלבוש חיצוני בעניני' גשמיי' וכן מעשה המצות כידוע, וצריך להיות בחי' רו\"ש דתפלה ותורה במדה ושיעור שלא יהי' בחי' רצוא דתפלה ביטול הי\"ש לאי\"ן כנ\"ל ביותר מדאי שלא יהי' רק לפי ערך בחי' היריד' והמשכה דתור' מאי\"ן ליש (ולזה אנו רואי' שכל שמאריך בעבודה שבלב בתפלה יותר מדאי שהוא בעסק ההתפעלו' והביטול לבדו ומקצר מאד בעסק תור' ביריד' והמשכת גילוי אלקות בלימוד ומעשה המצות, הרי אין האור מתיישב בכלי כלל וזה וזה לא נתקיים בידו ויפול מעבודתו בלי ספק, אבל כל שמעשי\"ו מרובי' מחכמתו כח מ\"ה דרצו\"א הרי חכמת\"ו מתקיימת יותר כו', שזהו כמו מיעוט האור וריבוי הכלי, ובענין ההתכללו' דאו\"כ הנ\"ל היינו מה שאין בתפלה בחי' רצוא התכללו' מהיפוכו דוקא שהוא להיות ברצוא זה עצמו מבחי' שוב דוקא, והוא להתפעל באהבה להמשיך אלקו' בכלי' דתו\"מ דוקא, כמו והאר עינינו בתורתך כו' שזהו קאי על מ\"ש ותן בלבינו בינ\"ה להבין ולהשכיל ומהו הבינ\"ה לב\"א בהתפעלו' דבינה האלקי' היינו לשמור ולעשו' דוקא כו', וכן מיד אחר ואהבת דרצוא והיו הדברי' כו' ודבר\"ת כו'), וכן להיפך שאין בחי' שוב דתור' ומצו' רק לפי ערך בחי' רצוא דתפלה שאם הוא מקצר בתפלה במיעוט אור ההתפעלו' והביטול כו' ואומר אין לי אלא עסק התור' בחי' שוב גם תורה אין לו שזהו כמו כלי בלא אור (שזהו כירא' שקודמ' לחכמ'"],[1900640284,"דתו' שאם אין ירא' בקבלת מ\"ש בתפלה וק\"ש אין חכמ' וכל שירא' חטא קודמ' לחכמתו דתור' חכמתו מתקיימת, ואמנם א' גם להיפך אם אין חכמ' אין ירא' שצריך להיו' כלולי' זה מזה מפני שזה שאו' אין לי אלא תור' בלא תפלה או להיפך אין לי אלא תפלה בלא תור' זהו כאו\"כ שהאור מרובה שלא לפי ערך הכלי או להיפך שהכלי מרובה מן האור, והיינו הנז' בענין התיקון הא' בעצם האי\"ן וי\"ש דאו\"כ שיהיו במדה כו', אבל תיקון הב' בענין התכללו' בהתחלפו' דאו\"כ הענין הוא שאין באי\"ן מהיפוכו מבחי' יש לפי המדה, וכן להיפך שאין בי\"ש מאי\"ן היפוכו כו', וזהו שא' אם אין ירא' דבחי' רצוא כלול בחכמ' דתורה אין חכמ' ולהיפך אם אין שוב דחכמ' כלול בירא' דתפלה אין ירא' דתפלה כלום כו', וגם כאן שאו' אין לי אלא תור' שאין בו הרצוא שבשוב רק במיעוט ולהיפך שאין בתפלה דרצוא מבחי' השוב דתו' רק במיעוט, והיינו אם כל עיקר לימודו אינו בשביל המשכ' אלקו' בנפשו לתקנה כלל ע\"כ גם אין נפשו טהורה בלב בתשו' ואוי\"ר מסתפק במיעוט וזהו שאינו מתקן נפשו בלימודו כלל, ולהיפוך שכל עיקר עבודתו בלב ומוח בתפלה רק לתקן נפשו להעלותה כו' ואין בזה מהיפוכו לחפוץ בהמשכת ויריד' אלקו' למטה בתו\"מ רק מסתפק במועט כו', אלא צריך שיהיו כלולי' זה מזה במדה יפה).\n<b>ובדוגמא</b> זאת יובן במלאכי' שנא' בהן והחיו' רו\"ש כנ\"ל, דהנה המלאכי' כלולי' מחומר וצורה שנק' או\"כ, וכמ\"ש הרמב\"ן דחומר המלאך מורכב מא\"ש ומים והצור' שלו בחי' רוח וז\"ש עושה מלאכיו רוחו\"ת כו' לפי שיצא שרשם מבחי' התיקון (וכמו תוצא האר\"ץ נפש חי' שהן פני ארי' פני שור למעלה שנמשך מארץ עילא' וכמארז\"ל ועוף יעופף עוף זה מיכאל כו' כידוע) דבחי' מל' כו', והיינו בחי' אי\"ן וי\"ש ב' הפכי' ויש בהן מדה ושיעור בעצם שלא ירבה עצם האי\"ן דאור שהוא הצורה שלהם על בחי' הי\"ש דכלי חומר שלהם, ולא ירבה הי\"ש דחומר שלהם על האי\"ן דצורה שלהם כנ\"ל, לפי שהנפש והצור' שלהם שרשם ממל' דאצי' שהוא בחי' אי\"ן האלקי כו' מבחי' אורו' שבמל' וגופם וחומרם נמשך מבחי' הכלים שבמל' ע\"כ הוא בעצם בבחי' יש נפרד היפך הביטול רק שהוא חומר דק ורוחני יותר מגופו' בנ\"א (והיינו מחומר הבל דיבור העליון שמורכב מא\"ש ומי\"ם ויש בו גם רו\"ש י\"ש וביטו\"ל, משא\"כ הצורה והנפש שלהם מבחי' הצורה שבדיבור העליון שנק' רו\"ח ממלל\"א כו'), וזהו שאנו רואי' שכל ענין עבודת המלאכי' בשירה"],[1900640285,"שאומרי' בכל יום באה בענין השתחווא' דחומר גופם ג\"כ שהוא בחי' רו\"ש מאין ליש ביטול הי\"ש לאי\"ן והכל ע\"י אמצעו' האור והצורה דנפשם שהוא בחי' אי\"ן בעצם כביטול גופו של אדם ברצוא דתפלה ע\"י אמצעו' השגו' אור נשמתו באי\"ן האלקי כו' שמבטל הי\"ש לאי\"ן כאור הדולק בפתילה, ויש בזה כל ד' חלוקו' הנ\"ל בתיקון, הא' באו\"כ בעצם האי\"ן וי\"ש שהוא שיש שיעור קצוב במהו' ועצם האי\"ן דצור' ונפש לפי ערך שיש בחומר בחי' הי\"ש ולא יהי' האי\"ן דצורה יותר מי\"ש דחומר ולא יהי' יש דחומר יותר מאי\"ן דצור' אלא במדה באופן שיהי' ראוי' לקיום (והוא מה שמצינו בנפילי' כמלאכי' דעזא כו' מפני שהי' להם חומר גס ויש ביתר מכפי ערך האי\"ן דצור' שלהם עד שלא הי' בכחו לבט\"ל הי\"ש לאי\"ן ע\"כ נפל\"ו למטה לגמרי כו' וד\"ל, וכנ\"ל בענין הנשמ' וגוף שיש גוף גס ויש ביותר שאינו לפי ערך האי\"ן דנשמ' דהיינו תרתי לריעותא כו', וע\"כ חומר וצורה דמלאכי' הן במדה ושיעור והחומר מעין הצורה שיוכל שאת ולא יפול כו' וכן לא יעלה יותר מכפי המדה ולכך נק' עומדי\"ם כו'), ואמנם זהו בענין תיקון הא' הנ\"ל בעצם האי\"ן ויש דאו\"כ שלהם, וכמ\"כ יובן גם בענין התכללו' דחילוף או\"כ הנ\"ל שבמלאכי' שהן מבחי' התיקון דמ\"ה כו' יש באי\"ן שלהם מבחי' היש דוקא והוא המשכת אין דנפש בכלי להיו' בבחי' שוב, ולהיפך שיש בחומר מבחי' הביטול לאי\"ן והוא בחי' רצוא, וז\"ש והחיו' רו\"ש שבכל א' יש מהיפוכו ממש, וכמו ענין השירה שאומרי' המלאכי' שהנפש או' שירה לפי אופן השגתה ועושה ופועל בזה ביטו\"ל חומר הי\"ש, וגם הרי יש בו מבחי' שוב דוקא וזהו שבחומר בא ההשתחווא' דשוב וגם הביטול הי\"ש לאי\"ן בשעה שהנפש והצו' או' שיר\"ה כו' וד\"ל. וזהו ממש ע\"ד הנ\"ל בבחי' רו\"ש דתור' ותפלה שכלולי' כל א' מהיפוכו דוקא ואזי יש קיום דוקא, לפי שזהו עיקר בחי' התיקון הב' בהתכללו' דאו\"כ בחילוף שיהי' בשיעור ומדה שיוכל הכלי להכיל האור ולא יפול למטה, ואור יתיישב בכלי ולא יסתלק למעלה שזהו מצד שהאי\"ן וי\"ש דאו\"כ כלולי' זה מזה לפי ערך ע\"כ מתאחדי' יחד והיו לאחדי' ממש בקיום נצחי וד\"ל.\n<b>והנה</b> אחר כל הנ\"ל בבחי' התיקון יש להפלא מאד על בריאת האדם שנברא ונוצר מן עפר האדמה ונשמתו נשמת אלקי' חיים וכמ\"ש ויפח באפיו נשמת חיים שזהו דילוג ערך המדרג' מגבוה לנמוך מן הקצה לקצה, דנשמת חיים הרי היא נמשכה מפנימי' ועצמו' אלקי' חיים וגופו עפר דומם מן האדמ' שאין זה לפי ערך כלל וכלל, והוא ההיפך מן המלאכי' שהחומר שלהם הוא מעין הצורה"],[1900640286,"דוקא והוא שאין היש דחומר גס אלא דק וגם הצורה אינו במעלה יתירה כ\"כ כדי שיהי' קיום כנ\"ל והוא להיותם מבחי' התיקון כנ\"ל והרי עיקר בחי' התיקון הוא באד\"ם דוקא דאד\"ם גי' מ\"ה כידוע ואיך מורכב בחומר וצור' שאינו לפי המדה כלל שזהו היפך בחי' התיקון אלא כמו בחי' התוהו שהי' האור בבחי' אי\"ן ביותר והכלי בבחי' י\"ש ביותר שאינו לפי ערך שלזה נפלו הכלים כו', וגם האדם חומר גופו בחי' דומם עפר יש ביותר ונשמתו מבחי' אי\"ן האלקי בעילוי ביותר שאין זה קיום כלל, ובאמת עיקר בחי' התיקון הוא בבריא' אד\"ם וכמ\"ש באני עלמין ולא en.אתקיימו עד דאתברי אדם והוא כשבא נשמתו בגופו הדומם דוקא כו'.\n<b>והנה</b> לפי אופן בחי' תיקון הא' הנ\"ל בעצם האו\"כ דאי\"ן וי\"ש יתכן דוקא ענין בריא' האדם בזה האופן שצריך שיהי' בחי' יש גופני יותר לבחי' האי\"ן ביותר מפני שיוכל להפכו בביטול הי\"ש לאי\"ן, דכל שהנשמ' גבוה יותר יותר יש בכחה לעשו' הביטול לאי\"ן גם בגוף גס ביותר, כנ\"ל שגוף גס נותנין לנשמ' גבוה דוקא ולנשמ' שאינו גבוה כ\"כ אין נותנין לה גוף גס כ\"כ כי לא יש בכח\"ו להפכו לאין ויפול לגמרי וחשב מחשבו' לבלתי ידח כו', ע\"כ מביא וממשיך לנשמ' גבוה לגוף עכור וגס שיוכל להפכו בתשוב' והזדככו' החומר כו', וזהו לפי המדה דוקא שמודדי' האור כמה יכול שאת בכחו להפוך היש כו', להיות ידוע דכל עיקר ירידת הנשמה בגוף אינה לצורך עצמה לתקן עצמה דהנשמ' עצמ' א\"צ תיקון כי נמשכה מבחי' עולם התיקון שהוא שם מ\"ה דאד\"ם דאצי' ולא ירדה רק לתקן ולברר לגוף כו' שהוא בחי' מ\"ה שמברר לב\"ן לעשות מי\"ש אי\"ן לפי ערך כח\"ה בבחי' מ\"ה דתיקון כו', וז\"ש לכבוד\"י בראתי\"ו יצרתיו כו' בחי' נר\"נ שהוא בי\"ע לפי ערך בחי' כח מ\"ה ואי\"ן דנשמ' כך יש בכחה להפוך י\"ש יותר כו' (ולפ\"ז הי' ראוי להיו' בחי' נשמ' בעשי' ונפש בבריא' דכל אור עליון יותר השפלתו למטה יותר כמשל אור גדול שמאיר במקום חושך ואפילה ג\"כ ולמקום חושך ואפילה צריכי' לאור גדול דוקא, אך הפי' הוא דנשמ' בע\"ס דבריא' ונפש בע\"ס דעשי' שזהו חילוק המדרג' באור דמ\"ה כידוע, אבל בענין התלבשו' הנשמ' בגוף הרי א' en.en.כל הגדול מחבירו יצרו גדול דלפי ערך מעלת גדולת הנשמ' כן יצרו גדול כו')."],[1900640287,"<b>והנה</b> גם לפי אופן בחי' תיקון הב' הנ\"ל בהתכללו' דאו\"כ בחילוף דוקא שבאור יהי' מאין ליש ובכלי יהי' מיש לאין הרי כל שהכלי יש בה יותר ביטול היש לאין במיעוט הגסות הרי האור הוא יותר במיעוט ההעלא' וברוב ההמשכה מאין ליש יותר, זהו מעלה יתירה ביותר דכל מה שהכלי מזוכך יותר יותר יומשך האור בישות בכלי, וא\"כ צריך להיו' להיפך דנשמ' נמוכה שבמיעוט האור דאי\"ן יהי' לה גוף דק ומזוכך יותר ולנשמ' גבוה שבריבוי דאין יהיה לה גוף גס יותר. ולכאורה יתכן גם לפי זה ענין בריא' האדם בחומר גס ביותר לצור' גבוה יותר מקצה העליון לקצה התחתון, והכל עולה לענין א' מאחר שניתן מדה גם בהתכללות בדבר מהיפוכו שיהי' באור לפי הכלי ובכלי לפי האור דוקא, דהיינו לפי מדת היפוך דכלי בביטול די\"ש לאי\"ן בגוף דק כך יהי' היפוך דאור ביריד' מאין ליש יותר לא יוסיף ולא יגרע זע\"ז אפי' כמלא נימא, א\"כ היינו הך שלפי en.מדת האי\"ן בעצם יהי' הי\"ש בעצם בתיקון הא' הנ\"ל וד\"ל.\n<b>אך</b> הנה עדיין אין כל זה מתיישב, דהנה לכאורה עיקר מעלת בחי' מ\"ה דתיקון הוא דוקא ענין יריד' האי\"ן בי\"ש להפוך מי\"ש לאי\"ן, א\"כ ירידה זו אינו חסרון אלא מעלה דכל הגבוה יותר יותר ישפל עצמו כנ\"ל וע\"כ צריך שיהי' לנשמ' גבוה גוף גס מפני שיש בכחו להפכו כנ\"ל. ולפ\"ז יש ב' מדרגו' בירידת האי\"ן למטה א' למעליותא שזהו ירידת בחי' מ\"ה ואי\"ן בהתלבשו' בי\"ש להפכו כנ\"ל והב' היפוכו לגריעותא שבא במיעוט האור דאי\"ן עד שהוא כמו בחי' יש נפרד ע\"ד האו' אין לי אלא תור' כנ\"ל שלזה צריך שיהי' גוף דק דוקא שאם יהי' גוף גס יהי' תרתי לריעותא ויפול לגמרי כנ\"ל בענין נפיל\"י' כו', ואין כל זה מובן כלל דלפי הכלל הידוע הרי כל העלא' גורם בחי' המשכה לפי ערך אופן ההעלא' דוקא ומכ\"ש שלא יהי' ההמשכה היפך ההעלא' או גרוע הימנה, וכמו רוח אייתי רוח ואמשיך רוח כו' בבחי' העלא' דרצוא וביטול הי\"ש לאי\"ן כל שהוא בהעלא' וביטול יותר צריך שימשיך המשכה דבחי' אי\"ן ביותר העילוי וכל שאין ההעלא' וביטול היש כ\"כ לא ימשיך מבחי' האי\"ן הנעלה כ\"כ, ובכאן הרי הכל להיפך בב' מיני תיקון הנ\"ל דגוף גס בהעדר הביטול איך נמשך בו מבחי' אי\"ן היותר נעלה כנ\"ל ולגוף דק שהוא בביטול היש יותר יומשך בו בחי' אי\"ן דאור גרוע יותר כנ\"ל, וכן בענין התיקון הב' דהתכללו' או\"כ בחילוף גם הוא בהיפך ממש, דכאשר הכלי בביטול היש יותר אז האי\"ן דאור נמשך בבחי' יש ביותר וכשאינו בביטול הי\"ש כ\"כ נמשך האור דאי\"ן בעילוי יותר, שכל זה היפך גמור מענין הכלל דרוח אייתי רוח כו' דאדרבה כל שהכלי הוא בביטול היש יותר יומשך בו מבחי' האי\"ן ביותר וכידוע הכלל בכל העלא' מ\"ן והמשכת מ\"ד בכל מקום וד\"ל. ועוד יש להבין דאם נמצא ב' מדרגו' בירידת והמשכת האין בב' אופני' הפכיי' כנ\"ל, א\"כ ודאי גם בהעלא' וביטול היש לאי\"ן מלמטה למעלה ג\"כ ב' מדרגו' בב' הפכיי' למעליותא ולגריעותא כנ\"ל בבחי'"],[1900640288,"המשכת האי\"ן, וזה א\"א לומר בהעלא' וביטול היש שיהי' לגריעותא רק שהוא במיעוט הביטול או ברוב הביטול שלפי ערך זה יומשך האור דאי\"ן אם במיעוט וצמצום או בריבוי כו', וכמו אם ישים אליו לבו כו' דרוח אייתי רוח, אבל איך יתכן שיהי' להיפך דביטול היש דגוף דק שהוא בעומק ודקו' יותר יגרום המשכת דאי\"ן במיעוט יותר ובהעדר הביטול לגמרי כמו גוף גס כו' נמשך בו מבחי' האור דמ\"ה en.en.היותר עליון כנ\"ל שזה פלא גדול לכאורה וד\"ל.\n<b>אך</b> הנה יש להקדי' ענין א' הידוע בבחי' ד' אותיו' דשם הוי' שהן י' יראה עילאה ה\"א רחימ\"ו עילא\"ה וי\"ו ה\"א רחימו ודחילו תתאה וכמ\"ש בר\"מ שהוא דו\"ר ורו\"ד כו', ונמצא ב' רחימות באמצע רחימו עילאה ורחימו תתאה ודחילו עילאה דיו\"ד ודחילו תתאה דה\"א מובדלי' זמ\"ז, ואמנם נעוץ תב\"ס וכמ\"ש הן יראת ה' היא חכמ' דהיינו דיראה תתא' דה' אחרונה היא חכמ' שביו\"ד דלפ\"ז יש ב' מיני חיבור רחימו תתאה ברחימו עילאה ודחילו תתאה בדחילו עילאה דוקא, ויש להבין הטעם לזה. והנה ידוע בענין ב' רחימות דו' וה' עילאה הנ\"ל שזהו עיקר ענין בחי' רו\"ש דוי\"ו הוא בחי' התפעלות המדות שבלב דוקא שזהו אם רץ לבך בתשוקה מורגשת לעלות ממטה למעלה כמו תשובה שבלב שמתפעל לעלות בביטול רצון שבלב והעלאה דרצוא זאת גורם המשכה וירידה מגבוה לנמוך והוא בחי' רחימ\"ו עילאה שהוא התפעלות אהבה בתענוגי' שבא ע\"י המשכת אור ההשגה שכליי' האלקי' מאי\"ן הנעלם דחכ' לגלוי יש במורגש העונג שבשכל (בל\"א עש קוועלט אין מוח כו'), וזהו כמו הנשמות נהנין במורגש העונג באה\"ר בהשגה דבינה ונמשך ללב וזהו הנק' מאי\"ן ליש, מאי\"ן דכתר וחכמ' ליש דבינה בבחי' פנימי' בינה כידוע שזהו שרש העוה\"ב ג\"כ כמ\"ש להנחיל אוהבי יש כו' והוא בחי' שו\"ב דרחימ\"ו עילאה שאחרי הרצוא דרחימו תתאה, וכמ\"כ ענין רו\"ש העליון יותר בדחילו עילאה ודחילו תתא' שנעוץ תחב\"ס דוקא כנ\"ל דהיינו בחי' ביטול היש הנפרד כמו בקבלת עמ\"ש פשוטה שמכניע א\"ע ומבטל רצונו שהוא בחי' מ\"ה ואי\"ן ממש רק שהוא מלובש בחיצוני' בפועל המעשה לבד שירא למרוד בקונו שנק' יר\"ח לבד, זהו בחי' העלא' לגרום המשכ' דבחי' מ\"ה העליון דחכ' וכת\"ר שהוא בחי' מ\"ה העצמי שבטל במציאו' בעצם לאין האלקי כו' וכנחנו מ\"ה דמשה וכן בכל כ\"ח מ\"ה"],[1900640289,"דחכ' כו', וז\"ש הן יראת ה' היא חכ' ממש דדחילו תתאה דוקא עולה בדחילו עילאה יראה עילאה דמ\"ה בעצם שלמעלה גם מהתפעלות רחימו עילאה דבינה הנ\"ל וד\"ל (וראי' לזה הוא מה שאנו מוצאי' שעיקר בחי' הכלי להשראת אור העליון דמ\"ה ואי\"ן דח\"ע הוא דוקא בשפלות וענוה יתירה דמ\"ה שלמטה בביטול היש לבד שזהו הכנעה פשוטה וכמו שא' יהיב חכמתא לחכימי\"ן, והיינו מפני שאינו נותן בחי' ח\"ע רק לחכימי' בביטול היש וגסות פשוטה וכמו ונפשי כעפר לכל ממש אז פתח לבי בתורתך שלא תמצא החכמ' בגסי הרוח, וכמו שאמרו לא בים היא במי שמרחיב דעתו עלי' כים כו', וזהו עיקר הטעם שנמשך פנימי' ח\"ע למשה יותר מכל האדם כו' לפי שהי' עניו יותר מכל האדם כו' כידוע, וזהו הטעם בענין דרבא יתיב באימתא ופתח בשמעתתא כו', וכן במ\"ת שאמרו נעשה בקבלת עומ\"ש זכו לקבל פב\"פ כו' שזהו ענין מה להלן כו'). ונמצא שזהו דוקא בחי' העלאה וביטול שגורם המשכה עליונה דמ\"ה העליון אשר אין ביכולת בחי' העלאה דרצוא שבלב להמשיך כלל כנ\"ל והוא דוקא עוצם ההכנעה והשפלות, או בקעמ\"ש כנ\"ל וד\"ל. והטעם האמיתי לזה היינו לפי שכל אור היותר עליון לא יומשך כ\"א בדבר השפל ביותר וכמו כי רם ה' ושפל יראה כו' (שזהו עמ\"ר ועמ\"ת ששקולין במשקל א' ממש כידוע), ועד\"מ המלך המרומם ביותר א\"א להגיע לפניו בשום צד קירוב אהבה כו' רק בביטול היש ביותר כמו באימה ורתת כו' או רק בביטול העצמות לבד, היינו שלא יתפס מקום כלל כזבוב כו', וכן עד\"מ תלמיד לפני רבו כל שצריך לקבל אור שכל וחכ' גבוה ביותר צריך לבא בעצמו בביטול הישות ביותר וכמו שא' כל תלמיד שאין שפתיו נוטפות כו', וכשאינו מקבל חכמ' גבוה כ\"כ אינו בביטול היש כ\"כ וכ\"ש כשאינו יושב לפני רבו ללמוד, וכך הי' במ\"ת שעל כל דיבור פרחה נשמתן לפי שהיו מקבלי' מאור פני ח\"ע כו', וכן"],[1900640290,"ג\"פ בשנה יראה כו' בהשתחוואה, וכן ענין הקבלת פני רבו ברגל וכה\"ג, וכן בחי' השתחוואה דש\"ע דאד' שפתי כו' כידוע) וד\"ל.\n<b>והנה</b> לפי הקדמה זאת יובן עכ\"פ שיש ב' מדריגות בהמשכה דאי\"ן ליש וב' מדריגות בביטול היש לאי\"ן, דהנה בב' אהבות הנ\"ל הרי בחי' אהב' בתענוגי' במורגש שבהשג' דבינה נמשך מאין דחכמ' ליש דבינה כנ\"ל וההמשכה דאין ומ\"ה דחכמ' שבא בהתלבשות ליש ביראה תתאה דהן יראת ה' היא חכמ' בראש כנ\"ל דמ\"ה העליון יורד ומלובש בביטול חיצוני זה כענוה דמשה בביטול היש לגמרי מצד שהי' בו בחי' מ\"ה העליון, הרי ב' מדרגות בהמשכה דאי\"ן ומ\"ה ליש א' בבינה רחימו עילאה והב' במל' יר\"ת, וכמ\"כ ב' מדריגו' בביטול היש לאין והוא המבואר למעלה האחד בבחי' רו\"ש דב' אהבות הנ\"ל דרצוא שבלב ביטול היש במדו' שבלב שעולה להמשיך בחי' שוב והמשכת אהבה בתענוגי' דבינה כו', והב' ביטול היש דהכנעה חיצוני' בקבלת עומ\"ש או ביטול דעצמו' שאינו נתפס מקו' כלל כו', זהו בחי' רצוא לבחי' שוב דח\"ע פנימי' והביטול דמה העליון כמו יהב חכמתא לחכימין כו' כנ\"ל. ונמצא בא כל זה בב' אופני' הא' בהקדם ההמשכה תחילה להעלא' והוא שההמשכה גורמת ההעלא' דוקא בב' מדריגו' דהמשכה הנ\"ל, כמו בהקדם המשכה דאין ליש בעונג המושג גורם העלא' התפעלו' המדו' שבלב וכן המשכו' מ\"ה העליון דחכמה גורם ביטול חיצוני דהכנעה דקבלת מ\"ש או בחי' שפלו' וענוה יתירה או כמלך שמתגלה אימתו שיפול לב העבד באימה ויראה גדולה, וכן רב לתלמיד וכמ\"ת שנתבטלו מפני שראו כו' שיש בזה ביטול פנימי' מכל וכל וכו' עד שנעשה כאבן דומם באימה ברתת וזיעה כו' וד\"ל.\n<b>ולפ\"ז</b> יהי' איך שיהי' הרי בחי' ההעלא' כפי אופן ההמשכה וההמשכה לפי אופן ההעלא' בכל ב' מדריגו' דהמשכה והעלא' הנ\"ל ולא שיהי' להיפך או גרוע בערך זה מזה כלל כו', וא\"כ יש להבין למה אנו מוצאי' בבחי' רו\"ש דתפלה ותורה להיפך מזה, דהרי הביטול דרצוא שבלב באהבה שמצד ההתבוננו' בק\"ש צריך שיעורר המשכה דשוב בענין האהבה שבשכל כנ\"ל, ולימוד התורה הרי הוא בחי' שוב השני דהמשכת מ\"ה דח\"ע בביטול חיצוני דקבלת מ\"ש דתפלה בסוף כנ\"ל, ואיך יהי' בחי' שוב דתורה לרצוא שבלב שאין חיבור נמצא ביניהם כלל לפי הנ\"ל ואיך בק\"ש אנו או' ואהבת בלב תחלה ואח\"כ ודברת בם כו', ועוד שהרי עיקר התפלה הוא ביטול חיצוני בהשתחוא' שהוא כלי לבחי' מ\"ה העליון דוקא כנ\"ל והיינו ענין ת\"ת ממש, ועוד ענין מצות ק\"ש מהו דודאי פי' שמ\"ע ישראל הוא בהשגה דבינה דשמוע באזן הוא בבינה והוא שמוליד אהבה בלב באמרו ואהבת"],[1900640291,"וזה שלא לפי הסדר שהשוב יקדים לרצוא כו'. אלא צ\"ל דשני מיני עבודה הם א' בשוב שקודם לרצוא ויש בזה ב' מדריגו' הנ\"ל בהמשכה דאי\"ן ליש א' אהבה שבשכל בעונג מורגש באמרו שמ\"ע ישראל למס\"נ באח\"ד כפי השגתו כמו ר\"ע הי' מאריך באחד כו' שזה גורם העלא' דואהבת והן בחי' רחימו' הנ\"ל, והב' במצות ת\"ת דודברת בם שהוא המשכה דמ\"ה העליון בדיבור בד\"ת בחיצוני' הביטול רק להיו' כלי לדבר ה' שמדבר כידוע, ועבודה הב' ברצוא שקודם לשוב והיינו בב' מדריגו' דביטול הי\"ש לאי\"ן הנ\"ל והיינו פסד\"ז שקודם ק\"ש בהתפעלו' המלאכי' בבחי' רצוא שבלב כמ\"ש והחיות רצוא כו' ומעורר המשכה דאי\"ן לי\"ש בבינה בשמ\"ע ישראל בחי' אהבות הנ\"ל, והב' ביטול חיצוני בהכנעה שפלו' בעמידה דתפלה כשאו' אד' שפתי תפתח כמו אין מלה בלשוני כו' וכעומד לפני מלך מרומם כנ\"ל בביטול העצמו' וכרבא דפכר ידי' ומצלי כו', כשכורע בברוך שגורם המשכה דמ\"ה העליון להיו' בבחי' ביטול בפנימי' עד שאינו במציאו' ברתת en.ובאימה כו' וכידוע דהשתחווא' דש\"ע בבחי' אצי' ממש וד\"ל.\n<b>ובזה</b> יתורץ הנ\"ל דמצות ת\"ת הוא שוב לרצוא דתפלה בשמ\"ע דוקא שהי' בדרך העלא' דביטול הי\"ש בחיצוני' להמשיך מ\"ה העליון, ומהו המשכת מ\"ה העליון להיות בביטול פנימי כנ\"ל זהו מצות ת\"ת שאחר התפלה דש\"ע דוקא שהוא בחי' המשכה דמ\"ה העליון שיורד בד\"ת שמדבר והוא ממילא בביטול פנימי כענין שכינה מדברת מתוך גרונו כו' וכרב יהוד' וכו', וע\"כ מי שתורתו אומנתו פטור מן התפלה דוקא שזהו המכוון העיקר דתפלה שיהי' נמשך מבחי' מ\"ה דח\"ע כמו מלך שמתגלה וכמ\"ת כו' כנ\"ל, אבל אינו פטור מן הק\"ש שהוא בחי' השוב דאין ליש בבינה למס\"נ באחד אחר בחי' הרצוא דאוי\"ר שבלב גם במי שתורתו אומנתו, וזהו פשט הי\"א דאו' אין לי אלא תורה בביטול חיצוני שנעשה ביטול פנימי ע\"י בחי' המשכה דמ\"ה דח\"ע מלמעלה למטה בלי רצוא ושוב דב' רחימו' הנ\"ל, שאז אפי' תורה אין לו פי' שאין מ\"ה דתורה מתלבש בנפשו גם בביטול חיצוני דירא' תתאה מאחר שלא עלה נשמתו בבחי' רו\"ש דב' רחימו' הנ\"ל איך ישכון יו\"ד עילא' בדילוג גדול בה\"א תתאה כו', וזהו מפני שאו' אין לי אלא תורה דהיינו שלא יחפוץ בתבונה דבינה לב\"א כלל, רק התורה כמו שהיא בבחי' מ\"ה העליון שישכון"],[1900640292,"בנפשו הרי שעושה מבחי' אי\"ן י\"ש היפך המכוון דיריד' מ\"ה העליון לעשו' ביטול היש לאי\"ן כנ\"ל אפי' תורה אין לו באמת גם במי שתורתו אומנתו כנ\"ל, אך מי שתורתו אומנתו שיש בו ביטול פנימי דביטול כל עצמו' לא יתכן כלל שיאמר אין לי אלא תורה כו', רק שמקצר בתפלה כר\"י דמצלי לל' יום כו' כידוע, וע\"כ גם ר\"י הנשיא הי' מעביר ידיו ע\"ג עיניו בפסוק ראשון דק\"ש כמ\"ש אם ישים אליו לבו בק\"ש אז דוקא רוחו ונשמתו דבחי' מ\"ה העליון אליו יאסוף להתמשך בקול ד\"ת שלומד וכמ\"ש ואשי' דבר\"י בפי\"ך שצריך שימה שישים דבר ה' בפיו ובלא ק\"ש לא ישים דברו בפיו כמו שהוא למעלה וזהו שאפי' תורה אין לו וד\"ל, ומכש\"כ זה שאו' אין לי אלא תורה כפשוטו בלא דו\"ר כלל ובלא ביטול דקבלת מ\"ש וגם לא להמשיך אור אלקי בדבר ה' שזהו רק להמשיך מאי\"ן לי\"ש גמור להיו' בבחי' האין יש נפרד לומר אין לי, עד שעושה זה ליש ודבר בשביל עצמו לבד כמו להתגדל בה כו' אין לו כלום, וזהו כמו ענין הנ\"ל בגריעותא דמאי\"ן לי\"ש שהוא במיעוט הביטול דאי\"ן אדרבה לעשותו בבחי' י\"ש גמור שזהו היפך en.ממש מיריד' והתלבשו' מ\"ה ואין לעשו' מי\"ש אי\"ן הנ\"ל וד\"ל.\n<b>ובכל</b> זה יתורץ הקושי' דלעיל בענין ב' מיני תיקון הנ\"ל בי\"ש ואין בעצ\"ם ובחילוף דאין וי\"ש באו\"כ הנ\"ל, דהנה לפי כל הנ\"ל מובן עכ\"פ דההעלא' וההמשכה דאין וי\"ש באופן א' הם באין, אך הנה לפי המבואר למעלה ברו\"ש דב' מיני עבודה הנ\"ל הכל למעליותא א' ברצוא שקודם לשוב דרצוא שבלב בפסד\"ז לפי ערך עומקה ודקותה בהתפעלו' וביטול הי\"ש באהבה שבלב כך יומשך מאי\"ן דחכמ' בהשג' לעומק ודקו' בעונג המורגש באהבת הנ\"ל, ומי שלא מתפעל בלב מן השכל כ\"כ לעומק לא יומשך כ\"כ מאין ליש בשמ\"ע ישראל, וכן בעבודה הב' דתפלה שהכנעה בביטול חיצוני ממשיך בחי' שוב דמ\"ה העליון ג\"כ לפי ערך דוקא, וכמ\"כ בעבודה הב' דשוב שקודם לרצוא כמו בק\"ש שנמשך ואהב\"ת בינ\"ה לב\"א ובת\"ת דשו\"ב דמ\"ה דח\"ע נמשך ביראה תתאה ביטול חיצוני הב' בא במדה לפי ערך רו\"ש דב' רחימו' הנ\"ל שהרי אם או' אין לי כו' כנ\"ל וד\"ל. אך מה שאנו רואי' על גריעותא בב' מיני המשכו' דמאין ליש וב' מיני ביטול דרצוא הנ\"ל כמו במיעוט קבמ\"ש והכנע' שהוא או' אין לי כו' להיות מאי\"ן יש גמור הרי תרתי לריעותא, וכן בק\"ש אינו מתפעל בלב כלל וגם אינו נמשך לבינה להתענג על ה' למס\"נ אדרבה עושה מזה י\"ש שי\"ש מי שמשיג כאיש חכם בעיניו לומר רזי לי כו' וכאו' אין לי כו', הנה כל זה בא מתרתי לריעותא שבנשמתו וגופו דהנשמ' במוח ורוח בלב וכשגופו גס אינו מתפעל לבו ליבטל מישותו לאי\"ן כלל וגם"],[1900640293,"נשמה שבמוח אינו בבחי' אי\"ן בעצם רק בצמצום גדול, ע\"כ עושה י\"ש בהשגת\"ו רק ההשגת שכל מצד עצמו כאו' אין לי כו' והוא הגריעותא דמאי\"ן ליש הנ\"ל וגריעו' הגוף שעושה תרתי לריעותא הנ\"ל וד\"ל. וכמ\"כ בעבודה דתו' וק\"ש ששוב קדם לרצוא כנ\"ל, יש תרתי לריעות' מצד ששמיע\"ה דבינה דנשמה בק\"ש אינו עושה בחי' ביטול דרצוא שבלב בואהבת כלל ממילא יהי' יש גדול בעוסק בתו' ואו' אין לי אלא כו' כנ\"ל וד\"ל. ונמצא יש ריחוק ערך מדריג' בדילוג גדול כמעט מן הקצה לקצה בב' מיני עבודה הנ\"ל בין כשהם תרתי למעליותא שהרו\"ש דב' רחימו' הנ\"ל בתכלי' האמיתי דממילא ודאי תפלתו ותורתו ביראה עילא' ותתא' בתכלי' כמו לר\"י הנשיא שתורתו אומנתו כנ\"ל ותפילתו ברחב\"ד שנחש כרוך כו' וכה\"ג, ובין תכלית השקר בעוסק בתו' של\"ש רק או' אין לי כו' ובתפלה וק\"ש בפיו ושפתיו וכבד לבו רחוק כו', מאחר שאין בו התפעלו' אהבה ברצוא כלל ולא בחי' שוב דבינה לבא כלל רק מרחוק מאד ה' נראה לו, ועושה זה ליש נפרד לעצמו כנ\"ל היפך גמור מבחי' מ\"ה האמיתי דאין ויש בחו\"ב הנ\"ל וכמ\"ש בביטול היש דיראה תתא' ע\"י ירידה דמ\"ה למטה כנ\"ל שגבוה יותר כנ\"ל, ונמצא תלוי הכל בנשמה קדושה ביותר וגוף טהור ביותר דטהרת הלב מביאה לקדושת הנשמ' en.וקדושה דנשמה עושה לטהרת הלב והכל א' כמובן מכל הנ\"ל וד\"ל.\n<b>יום א' ט\"ז אדר תקפ\"ה שקלאב</b>\nאך הנה אמרז\"ל המתפלל צריך שיתן עיניו למטה ולבו למעלה דוקא ומבואר ענין זה המא' במ\"ש במ\"א על ענין המא' המן מן התורה מנין שנא' המן העץ כו' להיו' שקליפ' עמלק נק' ראשי' גוים והוא בחי' תמצית הז' מדו' רעו' דז' אומו' מפני שהוא שרש בחי' עה\"ד וע\"כ נק' ראשית לגוים בחי' מקיף נוגע ואינו נוגע ע\"כ אינו נמנה עמהם. והענין הוא כי המדה הרעה כמו התאוה והחמדה הרעה שהוא אהבה רעה לא הי' בה רע וקיום וחיו' כ\"כ כ\"א מצד בחי' עוצם ההרגשה שיש"],[1900640294,"בה שנק' דעת, שי[ו] דע ומרגיש בדבר רע זה ביותר כמו התינוק שגם שיש בו חום התאוה ואהבה רעה אם אין בו דעת [שהוא] ההרגשה היטב בנפשו להתמשך אחר זה אינו נמשך ומתפעל בתאוה זו כלל, וע\"כ אין לקטני' בושה להיות ערומי', וכן באדה\"ר קודם החטא דעה\"ד דכתי' ויהיו שניהם ערומי' ואחר החטא דעה\"ד א' לו מי הגיד לך כי עירום אתה המן העץ כו' דמשמע שזהו כל עיקר מהו' העה\"ד שעושה בנפש בחי' עוצם ההרגשה להרגיש א\"ע ביותר (בל\"א ער האט דעם חוש צו דער הערין זיך זייער טיף כו'), והיינו גם בלא התפעלו' תאוה וחמדה אינו רק בהרגשת עצמו לבד ביותר ולא יוכל לזוז מהרגשה זו כלל וכלל כי נשרשת בעומק נפשו עד שלא ידע וירגיש דבר חוץ מעצמו וזה עיקר ומקור לכל תאוה שתתאוה הנפש לרע, ואם אין בו חוש זה כ\"כ לעומק בקל יכול להזיז ולהסיח דעתו מכל רע אשר יפנה לבו אליו כי יסיר בקל המשכת והרגשת עצמו לזה כו', ואפי' מי שאין בו רק אהבת עצמו ביותר עד שהדבר הרע שיזיק לנפשו יתרחק וישנא ביותר ודבר הטוב יקרב בכל לבו שזהו האות על עוצם הרגשת עצמו ביותר כו' שנק' יש מורגש ביותר (בל\"א ער איז באי זיך זייער טייער און ציטריק כו' ער איז נאר אין זיך אונ וואש ניט זיך הערט ער גאר ניט כו'), ואע\"פ שזה אינו דבר רע כלל שהרי כל אדם אוהב א\"ע, וע\"כ כל דרכי איש זך בעיניו עד שאין אדם רואה חוב בעצמו כלל ואינו מרגיש רק בטובת עצמו וצערו ולא בטובת חבירו וצערו כלל, מ\"מ הרי זה עיקר בחי' העה\"ד טו\"ר שמרגיש הטו\"ר בנפשו רק לעצמו כו' ומזה מסתעף עיקר ושרש התאוה רעה כו', כי אנו רואי' שבכל תאוה אע\"פ שהוא תאוה רעה מצד העצם כמו תאות הממון ותאות הניאוף וכה\"ג עיקר כח התאוה הוא תאות הנפש דוקא, והוא במה שמתאוה בתאוה זו לתענוג עצמו ע\"כ יתמשך לבו לתאו' זו וא\"כ העיקר הוא רק בחי' ההמשכה שתמשך נפשו לזה, והתמשכות זאת אינו רק לפי ערך עוצם ההרגשה שתרגיש הנפש בעצמה יותר אז יש בה תוקף התאוה יותר וכל שאינו בהרגש עצמו כ\"כ לא יומשך להתאו' תאוה כ\"כ ובקל יסירה מלבו לגמרי, וראי' לזה מן המביא עצמו לידי הרהור תאוה רעה שזה אינו רק מצד עוצם הרגש עצמו להתענג ולשבח נפשו ולמלאו' לבבו בכל מיני טוב ותענוג חמדת עוה\"ז, משא\"כ מי שאין בו חוש ההרגש לדעת את הרע לא יומשך להביא עצמו לידי הרהור רע כלל וגם אם יבא שלא בכונה מיד יסירנו בקל כו', וכן במדת הכעס שהוא רק על דבר המנגד לרצונו מאד וחפץ לבו שמושרש בו עד שיג[י] ע בעצמו כידוע [ש] לא יגבר הכעס רק במי שמושרש ומורגש בעצמו"],[1900640295,"ביותר כמו בסיבת תאוה לאהבה רעה שהוא להמשיך לעצמו (צו זיך) ולמלאו' תאו' לבו דוקא, ובכעס על המונע תאותו ג\"כ בהרגשה זו עצמ' תליא וכן בהתגברו' [מדת] הנצחון ומד[ת] ההתפארו' רק מצד עוצם כח ההרגש עצמו ביותר הן באין כנ\"ל וד\"ל (וראי' לכל זה ממה שאנו רואי' במקום שיש הפשטת הרגש עצמו לגמרי מכל וכל יפול מכל תאו' וכעס ונצחון כו', כמו בעת צרת נפשו [או] ביסורי מות או כמו במלחמ' וכה\"ג שאינו מרגיש עצמו אז כלל וכל[ל] אין בו כח להתמשך לתאו' וחמדה כלל ולא יכעוס על העובר רצונו [כלל] גם שיג[י] ע לנקוד' לבו מאד כו'. או להיפך בעת רוממו' נפשו בעונג רב ונפלא מאד שהוא מגיע בעצם נקו' נפשו כמו בעת חתונת בנו או איזה בשורה נפלא וכמו מן גדולה יתירה או חכמ' עמוקה ביותר שאז יהי' ג\"כ בהפשט' עצמו ביותר עד שכל תאוה ימאס ויעבור על כל מדותיו לגמרי מכל וכל כו' וד\"ל, ואין זה מצד הגסו' דאדרב' מצד הגסו' רוח וגובה לבו יתמשך לכל דבר תאוה וכעס רציחה יותר כמו בהמן שא' וכל זה איננו שוה לי כו' משום דמרדכי לא קם ולא זע ממנו שזהו לנגד נקו' גסו' רוחו הי' חפץ להשמיד [את] כל היהודי' כו', רק בעונג שהוא מרומם הנפש לבחי' אין בהעדר הרגש עצמו עד שיקבל באהבה השונא ויעשה עמו רב טוב ויפזר כל הונו וכה\"ג בהפקירו' לגמרי כו'). והנה לזה הטעם נק' עמלק ראשית גוים ששרשו בדעת דעורף שהוא בחי' התוקף בהרגשת עצמו דוקא בלי יזוז ממקומו כלל (בל\"א שטארקייט), וזהו מי שלבו קשה כאבן בל יפול משום דבר אלקי והוא בחי' מקיף לז' מדו' הרעו' כמו נוגע ואינו נוגע שאינו נמנה בז' מדו' והוא שרש עצמי להם כנ\"ל, והוא הנק' ישו\"ת וגסו\"ת שאין בו ביטול עצמו והזזה ממקומו לעולם מטעם הנ\"ל, וזהו שעמלק הי' לו חוצפה ועזות [ללחום] בישראל הגם ששמע כל האותו' כי לא נפל לבו מכל גילוי אור אלקי כלל, וזה ישנו בכל איש שנק' בחי' טמטו\"ם הל\"ב שלא יפול לבו ולא יזוז כלל מכל [גילוי] אור אלקי המתגלה במוחו כו' כידוע, וזה נפל בשבה\"כ ראשונה והוא מלך בלע בן בעור שהוא בחי' en.הדעת דקליפ' כמו [כ] בלע את הקדש וכמ\"ש במ\"א.\n<b>והנה</b> זה ימצא גם בסט' דקדוש' והוא בחי' המ\"ן דקדושה לאחר הבירור כמו ויגבה לבו בדרכי ה' שגם בדרכי ה' ממש יש בחי' ישו\"ת וגסו' שנק' גבהות הלב ממש אך שהוא בסט' דקדוש' האלקי', וזהו ממש כמו התוקף ההרגש בעצמו הנ\"ל כך תוקף לבו בסט' האלקי' בהגבה' ה' והתנשאו' בלי יזוז כלל, וזהו"],[1900640296,"מעלה יתירה להיותו מבחי' הדעת דקדוש' בתוקף גדול מאד [ע\"כ לבו כלב הארי'] לעבודת ה' כו'. אך מסתעף מזה ההנאת לעצמו [ובעונג ע] ד שאינו [רק] להרגיש עצמו בדבר הגם שהוא דבר שבקדוש' כמו למען שמי יכבד ה' כו' וכמו ערב רב כו' כידוע. וזהו שא' המתפלל צריך שיתן עיניו למטה [ולבו למעלה פי' לבו למעלה הוא בחי' התוקף בלב בהגבהה והתנשאות בתשוקה וחיות מורגשת בעצמו בתכלית כמו ויגבה לבו כו', ואמנם באותו רגע יהיו עיניו למטה] שהוא בחי' הביטול דכח מ\"ה ואי\"ן אלקי שבמוחו שזהו היפך ממש מבחי' הישות וגסו' תוקף הצמאון שבלב למעלה כמים שמכבה האש ממש, כידוע דמוח החכמ' הוא קר ולח בבחי' יסוד המים שיורד מגבוה לנמוך וזהו בחי' העדר ההרגשה בעצמו מכל וכל כנ\"ל בענין אי\"ן וי\"ש בעצם כו', והוא המוח השליט על הלב להפכו מטבעו שהוא בהגבהה והוא הצמאון שמיסוד האש דבינה לבא, היינו מוח הבינה שהוא חם ויבש ומאיר ביסוד האש שבלב להיות עולה בישות [בתוקף] ההתפעלו' כמו אם רץ לבך כו', היפך ממש מן הביטול דאי\"ן כו', וזהו שעיניו למטה ולבו למעלה דבר והיפוכו כא' עיניו דחכ' שבמוח ששם הנשמ' למטה בלב לעשו' מיש אין ממש ולבו למעלה להיות יש כו', ולכאורה איך יהיו ב' הפכי' כאלה כא' אם לבו למעלה איך יהי' עיניו למטה כו' ואם עיניו למטה איך יהי' לבו למעלה בהגבהה, אלא צריך לומר שיהי' העיקר בביטול דאין וביטול דכ\"ח מ\"ה שבמוח בלב ומה שלבו למעלה הוא [בא] במדה ושיעור מועט רק כפי הצריך לבד [ל] שלימות הדבר דוקא כו'. והענין הוא כידוע [בענין] ת\"ח צריך שיהי' בו חלק א' מס\"ד שהוא שמיני שבשמינית גסות ומעטרא לי' כסאסא כו' אבל יותר מזה שהוא [חלק ס\"ג] נאמר כולו ס\"ג בחי' גסו' דקליפ' המן, והטעם לשיעור זה דוקא לפי שמוח החכ' כולל"],[1900640297,"ל\"ב נ\"ח, והן ד' חדרי' שבמוח שכל א' [נחלק] לח', וחפ\"ח הוא ס\"ד, כי לבנ\"ח מתפשטי' בלב ונק' ל\"ב שבילי' כו' שבדע' העליון חדרי' דמוח ימלאון ומתפשטי' ע\"י ד\"ת בלב ג\"כ לל\"ב וב\"פ ל\"ב [הוא] ס\"ד, ונמצא הגסו' שבלב כאשר הוא חלק ס\"ד לבד מכללו' המוח והלב מעטרא לי' כו', כי כאשר הלב בטל לגמרי לגבי הביטול דאין שבמוח החכ' הנ\"ל לא יהי' לו חוזק כלל בנפש שלא יגבה לבו לעבוד ה' כלל כו', מצד עוצם השפלו' לומר מי אנכי כו' כמו וינועו כו', אך מעט הגבהת הלב יועיל לת[וקף] אור דכח מ\"ה דוקא להיו' בבחי' כתר ועטר' לה כו', ועוד כדי שיהי' חיבור ללב בחלל הימני דרוח החיים עם מוח החכמ' בבחי' אין דוקא א\"א כ\"א ע\"י התנשאו' דלב מעט בגסו' שבחלל השמאלי, וזהו ע\"י שמיני שבשמינית דבינה לבא בעלי' דוקא דרוח אייתי רוח ברו\"ש דוקא שאז מתחבר כח מ\"ה דמוח החכמ' בחלל ימיני דרוח החיים כו' וד\"ל. אך יותר מזה הוא גסו' וי\"ש דלב שאינו מועיל אח\"כ ביטול ואי\"ן דנשמ' שבמוח בלב כלל אע\"פ שאי\"ן דחכמ' הרבה יותר מישות שבלב וגם אין הישו' רק בהתפעלו' רצוא דבינה לבא הנ\"ל וד\"ל.\n<b>אמנם</b> לכאורה זהו פלא גדול מאד אדרבא לכאורה כל שהביטול דישו' בלב יותר [יותר] יומשך מאי\"ן דחכמ' וכמ\"ש בלב כל חכ\"ם ל\"ב דוקא בענוה ושפלו' [יתירה נתתי] ח\"ע יותר כענוה דמשה כנ\"ל ומה יועיל מעט הגסו' לעשו' עטרת דח\"ע אם הוא היפוכו, ועוד למה בחלק ס\"ג יזיק לאור רב דביטול דאין כו'. אך ידוע דחו\"ב שנק' אי\"ן וי\"ש שניהם ממקור א' נובעי' והיינו מקור של קנ\"ה חכמה קנה בינה ב' מזלות דנוצ\"ר ונק\"ה כו', וכידוע בענין רואי' את הנשמע כו' שזהו ענין הב\"ן בחכמ' וחכם בבינה, דכמו שיש ב' מיני אי\"ן א' אי\"ן בעצם קודם שהחכמ'"],[1900640298,"מאין תמצא שלא נחלק לל\"ב נ\"ח עדיין והב' אין דחכמ' שנמשך לל\"ב נ\"ח, כך בי\"ש דבינה ב' מדרגו' א' שנמשך מאין דחכ' לבינה שבא בהשגה ומשם לל\"ב ונק' שמיני' כו' והב' י\"ש העצמי' שקודם לאי\"ן דחכמ', וז\"ש להנחיל אוהבי י\"ש דג\"ע ועוה\"ב ששרשן למעלה מב' מזלות דאין ויש דחו\"ב הנ\"ל, וזהו ב\"פ קנה דחכ' ובינה גימט' יש כו', וע\"כ במעט יש דחלק שמיני שבשמיני' דבינה לבא ברצוא הנ\"ל הרי עולה למקורו בי\"ש העצמי דאי\"ן דחכ' משם נמשך וזהו הב\"ן [ב] חכמ' שלמעלה [מ] חכמ' ולכך מעטרא לי' שהוא נעשה בחי' כתר דחכמ' כנ\"ל, אבל בחלק ס\"ג נעשה בחי' י\"ש דבינה שהוא בס\"ג שמקבל מע\"ב דחכמ' שמזה נמשך היש גמור כו' וד\"ל. וזהו שא' לבו למעלה בבחי' רץ לבך שהוא הישות שבבינה עולה לשרשו דוקא שלמעלה מן הל\"ב דנ\"ח ע\"כ מעטרא לי' כו', ומה שהביטול דיש גורם אי\"ן דח\"ע כנ\"ל זהו בא ממה שלבו למעלה דוקא כמו שח\"ע נמשך מי\"ש לאי\"ן שהוא מקור להמשכה דחכ' מאין לי\"ש בבינה כו' וד\"ל.\n<b>(ובזה</b> יובן ג\"כ מ\"ש ויקח המן את הלבוש ואת הסוס, דסו\"ס ב\"פ ג\"ס דבחי' התנשאו' דלבוש מל' דקדוש' באה אחר האין דח\"ע דוקא שזהו י\"ש דמלוכה התנשאו' אלקי' [גיאות] לבש אשר לבש בו המלך מרומם לבדו והוא התנשאו' העצמי' בחי' י\"ש האמיתי, וזהו אשר אהי' כו' בבחי' בינה דעוה\"ב י\"ש האמיתי כידוע בפי' עד יעבור סתם ופי' ימלוך לע\"ו וכפי' ונחי' לפניו ממש כו', וזהו סו\"ס ב\"פ ג\"ס ס\"ג דבינה שיורד בו בחי' התנשאו' הזאת העצמי' שלמעלה מעלה עד אין קץ להיות בבחי' יש כמו ב\"פ י\"ש גי' תר\"ך דכת\"ר, וזהו שניתן ממילא כת\"ר מל' בראש\"ו וקאי על הסו\"ס שרכב עליו המלך כמו במ\"ת דכתיב כי תרכב על סוסיך [שכלולילם ב] סו\"ס אחד שהי' מעין עוה\"ב ממש, אבל בחי' המן דקדוש' שהוא ס\"ג דבינה גם במקורה בי\"ש שקדם לאין אינו מגיע ליש האמיתי"],[1900640299,"שמצד עצמו, כ\"א אשר ניתן ממילא, והיינו עטרה שעטרה לו אמ\"ו שהן כנ\"י באמרם נעשה שהוא בחי' אין העצמי והאמיתי כו' (דבחי' יחידה שהוא כלי לבחי' יחיד מרומם לבדו כו' [שאין זה כלל בזלע\"ז כו'] ), ומזה בא העוה\"ב להיו' נחי' לפניו ממש בי\"ש מורגש גמור ולא בחלק ס\"ד לבד אלא כולו ג\"ס ואין בו שום שמץ גסו' כלל אדרבה תכל[ית] האין האמיתי כו', ונמצא תכלי' האי\"ן מתייחד עם תכלי' הי\"ש והיו לאחדי' ממש, משא\"כ עתה דיחיינו מיומיי\"ם ד[חו\"ב] לבד במקורם של הב' מזלו' דאי\"ן וי\"ש שבא בהמשכה שצריך שיהי' הי\"ש רק שמינית שבשמינית, ועיני\"ו למטה לעשו' בלב בחי' ביטול הי\"ש לאי\"ן ע\"י ח\"ע כו' (וזהו דגואל ראשון הוא משה עני\"ו מא\"ד תכלי' האי\"ן היינו גואל אחרון דמשיח שיאיר בו מהתנשאו' די\"ש האמיתי דוקא). ובזה יובן מ\"ש במ\"א בענין לבו למעלה, למעלה ממש בעצמו' ד[א] א\"ס במהותו ולא במציאו' התפשטות [בכח\"ב] כו' ועיניו למטה בעי\"ן דח\"ע מאי\"ן דח\"ע ביח\"ע ויח\"ת כו' עד בחי' אין האמיתי. וזה א' בעיניו למטה בתכלי' האי\"ן ומ\"ה כענוה דמשה כו' הוא עושה לבו למעלה לידבק במהו\"ע ממש, ודוקא כשעיניו למטה לעשו' מחושך דנה\"ב לאי\"ן עד שמשיג תמיד בעיני בשר ממש כאתה הראתה דמ\"ת ולע\"ל כו' אז לבו למעלה ממש, ולא שיהי' לבו למעלה קודם שעיניו למטה ממש, שלא יסתיר לו חומר גופו כלל וכמו לע\"ל שנא' ונחי' לפניו ממש בי\"ש מורגש ובלי הסתר פנים כלל וכלל כנ\"ל, וכמו ומבשרי אחז' אלו\"ה מבשר\"י ממש אחז' ואין בזה הסתר כלל, וזהו תכלי' השלימו' דלע\"ל בתחה\"מ ועוה\"ב שנא' להנחיל אוהב\"י י\"ש דוקא כו' וד\"ל.\nבע\"ה שבת פ' ויקרא שנתקפ\"ה\nואחר כל הנ\"ל יתורץ ענין הנ\"ל בענין רו\"ש דק\"ש ותפלה ותו' בב' מיני עבודה הנ\"ל הכלולי' בענין דו\"ר ורו\"ד הנ\"ל בפי' הן ירא[ת ה'] היא חכמ' באריכו',"],[1900640300,"דכ\"ז אינו מדבר רק בחו\"ב שנק' אי\"ן וי\"ש כמו שנמשכו כבר ממקור' בבחי' עו\"ע העלם וגילוי כמו והחכמ' מאי\"ן כו', אבל במקור' באי\"ן וי\"ש האמיתי' היינו תרתי למעליות' דנשמה קדוש' בתכלי' וגוף טהו' בתכלי' כמו ענוה וביטול דאי\"ן ומ\"ה דמשה, שזהו מצד מעלת הנשמה כמו שהיא בשרשה הראשון באי\"ן האמיתי כו' ובחי' הי\"ש דגוף אינו מסתיר כלל, ואדרבה מקבל בעצמו מבחי' י\"ש האמיתי כמ\"ש למעלה באריכו' בענין לבו למעלה ועיניו למטה כמו שיהי' לע\"ל בתח[ה\"מ ובעוה\"ב] דכתי' ונחי' לפניו ממש עד שאין צריך ביטול הי\"ש מאי\"ן דח\"ע כלל וד\"ל. ולהבין זה בתו' ביאור הנה אנו מוצאי' גם בתו\"מ דעכשיו דעיקרם הוא בבחי' התיקון דמ\"ה ואי\"ן דח\"ע דמברר לב\"ן די\"ש דתוהו כנ\"ל, וכידוע דבח\"ע דוקא אתברירו רפ\"ח כו'. אך [הנה] מצוה א' מן המצות יצאה מכלל כל המ\"ע שהיא ממש כדוגמא דלע\"ל גם עתה והוא מצות פרה אדומה שעלי' אמר שלמה אמרתי אחכמ' והיא רחוקה ממני כידוע, דהנה מבואר בלק\"ת עיקר ענין מצוה זו דפרה אדומ' שהוא בחי' ב\"ן דנוג\"ה פרה סוררת כו', שנפלה מב\"ן דתוהו וע\"י שריפת' עם עץ ארז כו' ומים חיים אל כלי הוא עיקר התיקון כו', וכמ\"ש במ\"א באריכו' ענין זה בכל פרטי', אך בדרך כלל הנה זהו כללו' ענין דתחה\"מ ועוה\"ב דמי חטא' דפרה הוא ענין תחה\"מ מטלא דבדולחא כו', ומים חיים היינו כמ\"ש ביום ההוא יצאו מ\"ח כו' שהוא במקור הח\"ע הראשון. וזהו ענין טהרה וקדוש' [ש] טהרה דתחה\"מ מביאה לידי קדוש' דעוה\"ב שנחי' לפניו ממש, וזהו ענין ברכות דאתה גבור ואתה קדוש כו' וד\"ל.\n<b>וביאור</b> הדברי' הנה באמת להבין עיקר ענין תחה\"מ מענין הזא' מי חטא' שמטהר טמאי', יש להקדי' תחלה בענין וייצר ה' את האדם עפר מן האדמ' שצבר עפרו ממקו' בהמ\"ק כגולם ונפח בו נשמ' חיים דפרח' מחי העולמי' ממש שזהו"],[1900640301,"כחומר וצורה ממש כמלאכי' וחיו' ודו\"צ כו', ואיך [יהי'] חומר גולם עפר ממש לצורה עליונה כזאת דנשמ' חיי החיים ממש כו', וצ\"ל דהי' חומר זה מוכן לקבל הצורה הקדוש' בתכלי', וראי' לזה ממה שא' דעקבו של אדה\"ר קודם החטא מכהה גלגל חמ', וגם אם הי' העפר הזה טהור בתכלי' הפשט' גסו' כו' [הרי מ\"מ] א\"א לדמות בעפר [זה] שיהי' מוכן לצורה עליונה כ\"כ כו', ואם כבר הי' לעולמי' בנשמ[ת] משה דמ\"ן המי\"ם עליונים מעה\"ח וז\"ש כי טוב בטי\"ת רבתי וקאי גם על גופו שהי' טוב בעצם באופן שהי' חומר מוכן לקבל צורה עליונה דנשמתו, אבל הי' נשמתו בגוף שנמשך עכ\"פ מיחוד גופני דאב ואם אע\"פ שהי' בקדוש' יתירה אין לזה ערך כלל לגבי נשמ' אדה\"ר דכתי' ויפח כו', וכמו כן יהי' בתחה\"מ בטל אורו' כו' שיבנה בנין חומר גוף מן העצם ויפח בו רוח חיים העליון, וז\"ש ביום הג' יקימנו ונחי' לפניו ממש שבודאי כ\"ז בא בדילוג המדריגו' ביותר כו' (וגם כמו נשמ' חנוך ואליהו בגופם שעלו למעלה אין זה רק מצד שהיו במדריג' גופו של אדה\"ר קודם החטא, אעפ\"כ תחה\"מ לע\"ל למעלה מהם מצד שיהיו בגופם למטה בישותם דוקא כו'), ויהי' איך שיהי' עכ\"פ הי' עפר גופו של אדה\"ר חומר מוכן לצורת נשמתו העליונה, וזה מצד שלא הי' בעפר זה שום רע רע וגסו' כלל וכלל אפי' שמץ מיני' רק גוף טהור וקדוש מעפר שבקרקע המשכן כו', וכך יהי' גופי' שבתח\"ה ממש ובמעלה יותר עליונה כי הרי יהיו בחי' כלי להכיל אור עצמו' en.אלקו' ממש שלא הי' באדה\"ר רק חלק קטן מזה (כמו בבחי' צמצום דא\"ק כו').\n<b>ובדוגמא</b> יובן בענין שריפת פרה אדומ' שהוא אפ\"ר א' פ\"ר כו', דהנה ההפרש בין עפר לאפר ידוע שהעפר מורכב מד\"י ארמ\"ע כי יש בו יסוד המים ויסוד הרוח יש בעפר וגם יסוד האש כסלע קשה ועפר תיחוח וכל צומח יצמח מן"],[1900640302,"העפר כמ\"ש הכל הי' מן העפר כו', ואמנם הכל בבחי' כח היולי ופשוט דוקא כי כח הצומח שבארץ בהעלם הוא וגם יסוד המים להיו' נובע בע[פר] מים חיים ממש, וכן יסוד האש ויסוד הרוח הכל בהעלם ובכח היולי בעפר יסודם ויוצאי' לגילוי מן ההעלם, וכל זמן שכלולי' שם נכללי' הכל ביסוד העפר וע\"כ נק' חומר העפר חומר פשוט והיולי שממנו יבא הכל לגילוי (וכן במע\"ב תוצא הארץ נפש חי' כו' משום דנעוץ תחילתן בסופן דוקא שהוא בחי' התהוו' הי\"ש מאי\"ן ממש כו'), וע\"כ עפר שבו נמשך נשמ' אדה\"ר הי' כמו [חומר] פשוט רק מורכב בו בהעלם כל אשר יצא בו לגילוי אור מי\"ש לאי\"ן בחכ' ומדו' ודיבור שהי' לנפש חי' לרוח ממללא ע\"י נשמתו שמאי\"ן לי\"ש כו', אבל האפר הוא אשר נשאר אחר כלות [חלקי ה] הרכבה דד\"י ארמ\"ע כ\"א וא' כלה והלך [לו] ולא נשאר רק האפר ונק' גם הוא חומר הפשוט לפי שזהו הכלל בכל מקום שכל מורכב כלה והולך אבל העצם הפשוט אינו כלה, ואפר זה אע\"פ שיש בו מיסוד האש יותר מיסוד העפר מ\"מ נק' חומר הפשוט [גם בעפר] הנשרף וכ\"ש בע\"ץ ובע\"ח כו', ויש מעלה באפר שאין בעפר במה שכלה ממנו כל ההרכבה משא\"כ בעפר שהוא מורכב כנ\"ל ויש מעלה בעפר שהכל הי' ממנו (יש מאין כנ\"ל) משא\"כ אפר שלא יצמח כו'. והדוגמא מזה יובן במ\"ש אע\"ה ואנכי עפר ואפר שכונתו על גופו ועל שרש נשמתו דע\"י עבודתו התמה בכל כלי גופו להוציא לאור כל טוב שבו הגנוז בהעלם כמו באהוי\"ר וחכ' ורצון רק לה' לבדו, כדוגמ' חומר גופו של אדה\"ר שהי' כלי לאור נשמתו, וגם ע\"י אור נשמתו שרשפי' רשפי אש שלהבת י\"ה שהוא בא מאי\"ן האלקי שהתהלך לפני ה' למס\"נ באחד, שזהו עד\"מ משריפת כל חלקי ההרכבה שבעץ עד שלא נשאר רק האפר שהוא בחי' עצם פשוט כך הי' לבב\"ו נאמ\"ן גם בלב בשר בעצמיו' ממש בגופ[ו] כמו בנשמתו ממש, וז\"ש ואנכי עפר ואפר וקאי גם על שרש נשמתו שהי' בחי' מרכבה לאור חסד דאצי' שהוא בחי' האפר לאחר כל הביטול היש המורכב כו' en.והוא בחי' עפר שהוא כחומר פשוט בתחלה ובסוף בלי שינוי כלל וכלל כו' וד\"ל.\n<b>ועד\"ז</b> יובן ג\"כ בענין אפר דפרה דהנה ידוע בשורש בחי' פרה אדומ' שהוא מבחי' גבורו' עליוני' דבחי' התוהו דז' מלכי' שמלכו בארץ אדו\"ם, שם ב\"ן שהוא בחי' גבו' עליוני' דקדוש' ליכלל באור המאציל בעוצם התשוקה"],[1900640303,"ו[ה]התלהבות ברשפי אש שלהבת י\"ה דהיינו בבחי' עצמו' דוקא, והוא בבחי' עשר' נקו' עשר' כתרי' דע\"ס דתוהו הן אורו' עצמיי' בלי התחלקות לי' עדיין, וזהו כמו למטה באדם הוא עצם הרצון ועצם החסד כו', טרם שמורכב בדבר מה בט\"ס וכו', וכמו התפעלות עצמות נקו' הרצון שאינו מורכב כלל בטעם ושכל לרצון ולא בא כלל להתחלקו' פרטי' איך ומה הוא הרצון, אם באהבה או בירא' שהוא חדוה או מרירו' רק בחי' עצם נקו' הרצון הפשוט ההיולי כענין התעוררו' התשובה בבע\"ת אמיתי ששב לאל בכל לבבו מקרב ולב עמוק שהוא בכל נקו' [הרצון] לה', ואח\"כ בא התפעלו' עצמיו' רצון זה בהרכבה והוא לבחור בדרכי הטוב לדבקה בהם בה' ולמאוס ברע המנגד שהן אוי\"ר שברצון, וכה\"ג בבחי' נקוד' אור החכמ' טרם שבא בהרכבה בחלקי' שוני' כמו שכל המוליד אהבה וחסד או שכל המוליד יראה ודין, וכה\"ג בכל המדו' נק' בחי' העצמיו' של כל מדה בשם כתר שבה והוא רק עצם פשוט בלי הרכבה כלל וכלל כידוע, ובודאי יש בכלל מאתים מנה שממילא יחולק ויתפשט הנקוד' העצמיו' ויבא לגילוי מההעלם בכל פרטי התחלקו' הט\"ס שבה כידוע, ונמצא שזהו כחומר הפשוט דעפר שכלול מכל פרטי דצח\"ם וארמ\"ע כמ\"ש הכל הי' מן העפר כנ\"ל שזה שיתפעל במדו' אוי\"ר וישכיל שכל כו' היינו בצמיחה מן העפר שממנו מתהווה הכל כנ\"ל או כמו חומר הפשוט העצמי דאפר הנ\"ל שבא אחר כליון כל חלקי ההרכבה שבד\"י ולא נשאר רק העצם הפשוט כנ\"ל. ושני האופני' האלה הוא בנמשל בע\"ס דתוהו שראשי' אור שלהם בהתהוות עיקר מציאותם הי' רק כנקוד' שהוא בחי' האחרונה, והוא בחי' שם ב\"ן דמל' והוא בחי' הכתר דנעוץ תחלתן בסופן וכמ\"ש בהן וימלוך פ' כו' וזהו כדמיון העפר, וכן בבחי' התכללותן בעצמו' המאצי' שמחמ' ריבוי התשוקה באש ההתלהבות ליכלל שם לא נשאר רק בחי' נקו' א' העצמי דבחי' כתר כדמיון האפר כנ\"ל שהוא אחר כלו' ההרכבה. והנה ידוע שמפני שלא יכלו הכלי' להכיל האור נפלו ונשברו כו' וענין שביר' זו ידוע שירד בעוצם ירידת [ה] השתלשלו' [ב] פירור אחר פירור דאותיו' וכלי' כו' עד התהוות בחי' נוג\"ה דבי\"ע, והוא בחי' פר\"ה פ\"ר ה' דהיינו גבורות קשו' דק\"נ שנק' פרה סוררת כו', וזהו כמו בחי' אש תאוה זרה דמעשה [בהמה ש] באדם למטה שנק' בע\"ר כמו בינו בוערי' כו', וזהו שרש כל רע גמו' דגקה\"ט כו' כרציחה וניאוף וכה\"ג ואין מיתוק הדין הקשה אלא בשרש' דוקא שהוא"]]});
